  Item_10025_Name = {
    Text = "苍白后裔"
  },
  Item_10025_StoryDesc = {
    Text = "风从四面八方涌来，你手持蜡烛站在迷宫入口。\n你有些迷茫。\n似乎上一秒，你还在弥萨格的食堂里，听夏洛特讲一些关于图书馆地底迷宫的传说。\n而现在，你穿着睡衣，睡眼惺忪地行走在一个接一个的甬道里。\n「夏洛特，夏洛特……」\n伴随窸窸窣窣的响动，白色的蜘蛛潮水般涌入。\n它们凝结成苍白的少女。她坐在肉块雕砌的秋千上，一荡一荡的。\n\n「你来了。」她说。\n「我来找夏洛特，我的朋友。她迷路了，我要找到她……」\n你几乎就要哭出声来。\n少女咯咯笑了起来。她跳下秋千，走到你面前。\n「你忘了吗，我们的交易……」\n女孩伸手抚上你的肚子，恍然大悟。\n「对哦。你早已成为我的子嗣，所以什么都不记得了。」\n「子嗣……？」\n你低头感受着你们肌肤相触的地方。\n温暖的触感如蛛网般深入皮下，再蔓延到血管的最深处。\n少女神秘地眨了眨眼，凑近你耳边轻声说：\n「夏洛特，就在你的肚子里呀。」"
  },
  Item_10026_Desc = {
