  Item_10065_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「小小心愿」。\n\n女孩在六岁生日的那天许下心愿：\n拥有一只名为「波波」的玩具熊，以及爱——不需要太多，一点点就够了。\n女孩从来都不是一个擅长幻想的人，也不是一个贪心的人。"
