  Item_10066_Desc = {
    Text = "当灵知被无限放大，它将触及真相的一角。\n由银芯驱动的特殊仪器，能按照预设值永久提升唤醒体的能力。\n守密人达到40级后，可以选择任一唤醒体，使其获得以下增幅：\n·等级提升至50级\n·所有技能提升至3级\n·突破等阶提升至4阶"
  },
  Item_10066_Name = {
