  },
  Item_10094_Desc = {
    Text = "主属性从暴击率、暴击伤害、死亡抵抗和伤害强效中随机获得1个。"
  },
  Item_10094_Name = {
    Text = "生机榨取Ⅲ"
  },
  Item_10094_StoryDesc = {
    Text = "脐带连接着无穷无尽的未来。"
  },
  Item_10095_Desc = {
    Text = "为了人类存续。\n被保存在画框里的记忆。用以升格血肉界域唤醒体的材料。"
  },
  Item_10095_Name = {
    Text = "记忆副本"
  },
  Item_10096_Desc = {
    Text = "给予我们未可知晓的认知。\n源自菲林诗社的特殊胶片，能转写人的认知。\n用以升格超维界域唤醒体的材料。"
  },
  Item_10096_Name = {
    Text = "认知模板"
  },
  Item_10097_Desc = {
    Text = "花语：离我远点。\n低茎海百合的化石。用于提升深海界域唤醒体的技能等级。"
  },
  Item_10097_Name = {
    Text = "低茎海百合"
  },
  Item_10098_Desc = {
    Text = "詹金如她的老鼠伙伴布朗一般机敏迅捷，神出鬼没。\n·借助超维跃迁，造成大量伤害\n·拥有随机应变的伤害能力"
  },
  Item_10098_Name = {Text = "詹金"},
  Item_10099_Desc = {
    Text = "主属性从暴击率、暴击伤害、银钥充能等级和狂气回充等级中随机获得1个。"
  },
  Item_10099_Name = {
    Text = "生机榨取Ⅰ"
  },
  Item_10099_StoryDesc = {
    Text = "脐带连接着无穷无尽的未来。"
  },
  Item_10100_Desc = {
    Text = "释放狂气爆发后能够额外获取狂气和临时暴击伤害，绝佳的运气往往能够与队友一同分享自身的好运。"
  },
  Item_10100_Name = {
    Text = "好运时间"
  },
  Item_10100_StoryDesc = {
    Text = "沿着泰姆河一路向下，向右拐至贝克曼街，继续行走大约一百英尺，你就能在那不起眼的角落看到「莱克侦探事务所」。\n\n作为伦蒂尼恩破案率最高的侦探事务所，这里没有塞满专业书籍的大书架，没有贴满剪报的墙面，也没有精致的下午茶。\n你大概率只会撞见门前挂着的「有事外出」标牌以及趴在一旁的疲惫老狗。\n\n若是运气好点，在某个天气晴朗的周日上午，你兴许能等到宿醉归来的名侦探先生。\n此时他刚结束上一把赌局，兜里没剩几个钱，你可以尽情向他提出你的无理委托：寻找猫咪、解救入了邪教的老母亲、搜集丈夫的外遇证据……\n只要你有，他就能接。\n\n「我享受濒死前的瞬间，所以我注定会成为一名赌徒。」\n「那成为侦探呢？恕我直言，我看不出寻找猫咪和濒死之间的相关性。」\n「不，你不明白……寻找真相的过程本身就已足够迷人，不论大小。就像……」\n「就像奔赴一场和死亡的约会。」"
  },
  Item_10101_Desc = {
    Text = "造成更多狂气和中毒的同时能够献祭敌方生命转化为临时暴击伤害，虔诚的信仰能够驱使更多的触腕。"
  },
  Item_10101_Name = {
    Text = "虔诚的伟力"
  },
  Item_10101_StoryDesc = {
    Text = "螺湮的主宰啊，请聆听我的祷告。\n降下你的预言，给予我启示，\n让我能够复原你的国。\n在这无信仰的土地，在这海洋环绕的冰原，\n将你的石柱立起，将你的神殿搭建。\n\n号令深渊之主啊，台上的是献给你的礼。\n纯净的血肉来自满月的羔羊，强健的心来自成年的公牛，\n锐利的眼来自翱翔的雄鹰，坚硬的骨来自巡洋的鲸。\n青金石是你的王座，黄金是你的冠冕，\n请赐予我你的梦境，告予我神言，\n让我能够复原你的身。\n在这冰下的深渊，在这海下的领域，\n将正确时刻降生的母体奉献。\n\n通晓万事的利莫里亚之王啊，请回应我的祷告。\n自你入海长眠以来，已过了千百年，\n我以你的名，行你的事，宣扬你的美名，从未懈怠。\n坚定的是我的信仰，虔诚的是我的心。\n你是唯一的神王，是不朽者的化身，\n愿你终结我的等待，再临于世，让我得以聆听你智慧的言。"
  },
  Item_10102_Desc = {
    Text = "主属性从狂气回充等级、死亡抵抗、银钥充能等级和伤害强效中随机获得1个。"
  },
  Item_10102_Name = {
    Text = "猩红之悸Ⅴ"
  },
  Item_10102_StoryDesc = {
    Text = "传说中最初的魔像创造者，以血液滋养魔像。"
  },
  Item_10103_Desc = {
    Text = "主属性从暴击率、暴击伤害、银钥充能等级和狂气回充等级中随机获得1个。"
  },
  Item_10103_Name = {
    Text = "猩红之悸Ⅰ"
  },
  Item_10103_StoryDesc = {
    Text = "传说中最初的魔像创造者，以血液滋养魔像。"
  },
  Item_10104_Desc = {
    Text = "封装大量银芯的礼盒。它们只负责创造奇迹。"
  },
  Item_10104_Name = {
    Text = "至尊银芯礼盒"
  },
  Item_10105_Desc = {
    Text = "主属性从暴击率、暴击伤害、银钥充能等级和狂气回充等级中随机获得1个。"
  },
  Item_10105_Name = {
    Text = "少女之蛹Ⅰ"
  },
  Item_10105_StoryDesc = {
    Text = "为您奉上纯洁的躯壳。"
  },
  Item_10106_Desc = {
    Text = "诃勒特代理院长特批的丰厚补给。\n封装着珍稀材料的木盒，为执行密境课室的日常试训与周常试训任务的守密人提供援助。\n从以下素材中选择一种：\n纯白秘篇*12\n淬制心灵*12\n意识副本*12\n灵知模板*12"
  },
  Item_10106_Name = {
    Text = "Ⅱ级补给（已废弃）"
  },
  Item_10107_Desc = {
    Text = "密契的本质即为禁忌的、难以被认知的知识。在使用拓片进行重新描绘后，密契的力量将得到进一步强化。"
  },
  Item_10107_Name = {
    Text = "密契拓写（已废弃）"
  },
  Item_10108_Desc = {
    Text = "王国货币的优雅代称。处处皆可获取，事事皆需使用。"
  },
  Item_10108_Name = {
    Text = "蔷薇金券"
  },
  Item_10110_Desc = {
    Text = "主属性从界域精通、黑印掉落、死亡抵抗和伤害强效中随机获得1个。"
  },
  Item_10110_Name = {
    Text = "机械降神Ⅵ"
  },
  Item_10110_StoryDesc = {
    Text = "机械是绝对纯净。"
  },
  Item_10111_Desc = {
    Text = "主属性从暴击率、暴击伤害、银钥充能等级和狂气回充等级中随机获得1个。"
  },
  Item_10111_Name = {
    Text = "36室之环Ⅰ"
  },
  Item_10111_StoryDesc = {
    Text = "旋转，然后遗忘——这是她生命的全部。"
  },
  Item_10112_Desc = {
    Text = "唤醒仪式后，残留在「黑池」中的浮沫。或许只有来自其他维度的商人能领会它的价值？"
  },
  Item_10112_Name = {
    Text = "根源浮沫（已废弃）"
  },
  Item_10113_Desc = {
    Text = "漏风的家。总比没有的好。\n被遗留的蛹壳。用于提升血肉界域唤醒体的技能等级。"
  },
  Item_10113_Name = {
    Text = "风干虫蛹"
  },
  Item_10114_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得「24」时转换获得，用于激活「24」的启灵。"
  },
  Item_10114_Name = {
    Text = "残片·「24」"
  },
  Item_10114_StoryDesc = {
    Text = "重复获得「24」时转换获得，用于激活「24」的启灵。"
  },
  Item_10115_Desc = {
