  },
  Item_116597_Name = {
    Text = "觐见奉礼"
  },
  Item_116715_Desc = {
    Text = "用藤环与鸟羽制作的简易捕梦网，有着并不可靠的灵性，使用后大部分时候会失败，有时能够打捞起梦残缺的碎片，大多只是一些快速闪回的画面。"
  },
  Item_116715_Name = {
    Text = "暗淡捕梦网"
  },
  Item_116716_Desc = {
    Text = "以奇异的古老鸟骨捆制成的捕梦网，能够将梦境纤毫毕现地呈现在你的脑子里，就像你真的经历过那些故事，见过那些梦里的人。美梦虽好，小心沉迷。"
  },
  Item_116716_Name = {
    Text = "蜃景捕梦网"
  },
  Item_116717_Desc = {
    Text = "用鹿皮绳与水晶点缀的捕梦网，形似眼珠的宝石赋予了它更好的灵性，使用后能够窥见模糊而完整的梦境。逃避现实的人啊，努力去打捞一个美梦吧。"
  },
  Item_116717_Name = {
    Text = "灵光捕梦网"
  },
  Item_116762_Desc = {
    Text = "获得幻衣「幻梦假日」后解锁。\n「守密人，要和我走走，去海边吹吹风吗？」"
  },
  Item_116762_Name = {
    Text = "环行·拉蒙娜·幻梦假日"
  },
  Item_116763_Desc = {
    Text = "对于环行·拉蒙娜而言，生命是场匆促而往复的试炼。\n训练，解决谜团，演算世界能够迈向未来的概率，然后亲眼见证那些她想要拯救的、渴望守护的美好破碎。\n一次又一次。\n再后来，生命是孤独而无止境的等待。\n她在已经失去希望的破灭世界，仰望无垠的纯黑色夜空，期待着来自遥远维度的呼唤。\n一日又一日。\n这是她的宿命，她也习惯了这宿命，接受了这宿命，直到——\n「拉蒙娜，我们可是在度假，不要板着脸，笑一下啦~」\n「拉蒙娜，你看到了吗？莉莉她们堆了个城堡，要不我们也加入？」\n「拉蒙娜，夏天怎么能缺少冰淇淋！今天我请客，来，这是你的。」\n「拉蒙娜……」\n「拉蒙娜。」\n「拉蒙娜！」\n一声又一声熟悉的呼唤里，夏日的阳光肆无忌惮地炙烤着万物。\n她看到沙滩上的「城堡」在阳光下熠熠生辉，也感受到冰淇淋融化在手上留下的黏腻触感。\n海水是凉的，沙子是热的，墨菲准备的吉事果是甜的，莱克宴请的奎宁水是苦的。\n这一切都是那么新奇，令她克制不住想要感受更多，品味更多。\n最重要的是，那个人还在，就在她身旁，这样的鲜活，这样的真实。\n就好像曾经的那些毁灭、崩坏、痛苦、绝望，才是幻觉。\n“……”\n阳光炙晒的海滨里，环行·拉蒙娜沉默，然后，缓慢而坚定地露出笑容。\n「是的，我们是在度假，所以守密人，要和我走走，去海边吹吹风吗？」\n与此同时，那无垠纯黑色夜空下的她，也在泪水浸湿的眼罩下，于不愿苏醒的清醒梦里，露出了同样的笑容。\n这次，她终于拥有了那些破碎过无数次的美好。\n哪怕，只是一场幻梦。"
  },
  Item_116763_Name = {
    Text = "幻梦假日"
  },
  Item_116764_Desc = {
    Text = "解锁后，完成「铭刻的启程」全部任务可额外获得以下奖励"
  },
  Item_116764_Name = {
    Text = "铭刻的启程"
  },
  Item_116792_Desc = {
    Text = "「来啊，快活啊~」"
  },
  Item_116792_EmojiName = {Text = "引诱"},
  Item_116792_Name = {
    Text = "泰旖丝·引诱"
  },
  Item_116872_Name = {
    Text = "艾瑞卡房树人"
  },
  Item_116873_Name = {
    Text = "莉莉房树人"
  },
  Item_116874_Name = {
    Text = "奥尔拉房树人"
  },
  Item_116875_Name = {
    Text = "我的房树人"
  },
  Item_116878_Desc = {
    Text = "属性为界域精通的命轮。"
  },
  Item_116878_Name = {
    Text = "你我终将重逢"
  },
  Item_116878_StoryDesc = {
    Text = "你和拉蒙娜从未约定再次相见。\n门扉在眼前缓缓合拢的刹那，你们心中划定的别离的时限，已是注定的永恒。\n\n所以，当她在时光的罅隙里，转瞬即逝的相逢里轻轻勾起你的小指……\n这已经是预期之外、足够幸运的重逢。\n「你一点都没有改变。」她说。\n\n为了这一句话语，为了指尖微弱的温度……纵然遥隔两个世界，你仍愿倾尽所有，飞跃银河与她相见。\n明年今日，勾指起誓。"
  },
  Item_117263_Desc = {
    Text = "逸散在不知谁的梦境中的情绪粒子，碰触时仿佛能听到谁回望来路时的迷茫低语。\n用于提升守密人在调查事件「乐园」中的共鸣。"
  },
  Item_117263_Name = {
    Text = "迷惘之心"
  },
  Item_117843_Desc = {
    Text = "弥萨格定期进行的太阳黑子辐射测量，用于排除唤醒体所受精神干扰。"
  },
  Item_117843_Name = {
    Text = "辐射监测"
  },
  Item_117844_Desc = {
    Text = "弥萨格定期进行的月球距离测量，用于确认黑池内银芯的稳定性。"
  },
  Item_117844_Name = {
    Text = "月距遥感"
  },
  Item_117845_Desc = {
    Text = "弥萨格定期进行的潮汐水位测量，用于监测深海之内的银芯丰富度指标变化。"
  },
  Item_117845_Name = {
    Text = "潮位巡查"
  },
  Item_118128_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「偏航船」。\n\n深海的使徒虔诚地跪伏于少女的阶下，献上名为忠贞之吻。\n在错误的航向上，她已经行进了太远。"
  },
  Item_118128_Name = {Text = "偏航船"},
  Item_118128_StoryDesc = {
    Text = "海的使徒虔诚地跪伏于少女的阶下，献上名为忠贞之吻。\n在错误的航向上，她已经行进了太远。"
  },
  Item_118305_Desc = {
    Text = "深潜经验达到一定值时，深潜等级提升。可在幻梦深潜中获得。"
  },
  Item_118305_Name = {
    Text = "深潜经验"
  },
  Item_119011_Desc = {
    Text = "轮选经验达到一定值时，轮选等级提升。可在相位对弈轮选模式中获得。"
  },
  Item_119011_Name = {
    Text = "轮选经验"
  },
  Item_119012_Desc = {
    Text = "预组经验达到一定值时，预组等级提升。可在相位对弈预组模式中获得。"
  },
  Item_119012_Name = {
    Text = "预组经验"
  },
  Item_119149_Desc = {
    Text = "记载了在混沌空间进行的绝密实验的神秘古籍。\n可从中选择1个「星辰篇」中的「混沌」界域中的限定命轮免费获得。"
  },
  Item_119149_Name = {
    Text = "混沌实验·星辰篇"
  },
  Item_119150_Desc = {
