  },
  Item_119689_Desc = {
    Text = "获得幻衣「孽宴狂欲」后解锁。\n「来吧小树苗，释放你的欲望，加入永不停息的狂欢吧！」"
  },
  Item_119689_Name = {
    Text = "孽宴狂欲"
  },
  Item_119690_Desc = {
    Text = "啪答……啪答……\n作为亚兰最优秀的猎手，我早已习惯了各种恶劣的环境——沙漠、雨林、沼泽，甚至是充满胃酸的巨兽腹中，都不会让我产生一丝一毫的动摇。\n但不知为何，当我感受到身上这粘稠的液体时，我还是不适地抖了抖身子，就好像这是人类完全不能接触的孽物。\n「好孩子……好孩子……」\n我变成了一个婴儿？现在还不确定，但可以肯定，我的身体发生了某种变化。\n有一双温暖的手把我轻轻抱起，没入身后哺育者的怀抱，同时一股饱满的欲望缠裹着我，却如羊水般温暖令我安心。\n我尝试了几次，终于睁开了眼，但眼前令人恐惧的景象让我不自觉地扭动身体，试图将整个躯体没入丰满的乳房。\n那是触手扭曲交错的犄角、将头部纵向分开的巨口、不断滴落的绿色粘液，我从未见过这种恐怖的怪物……我本想移开视线，却发现自己如同着魔一般，只能目不转睛地盯着眼前的畸形之物。\n它们同样在目不转睛地盯着我，我轻易地从眼神中读出了它们对我肉体的渴望。\n可为什么……那疯狂的眼神中，却带有如此纯粹的期待？\n「乖孩子……别害怕……」\n如母亲般温柔的话语在我耳畔响起，那是温暖的手掌拂过全身的感觉，这一刻我的心情突然变得平静，仿佛身后之人真的是我的母亲，而我此刻正处于最安全的港湾里。\n虽然我的理性告诉我这并不可能，但我还是撒娇似地蹭了蹭她正在帮我梳理毛发的……等等……梳理毛发？\n意识到什么的我尝试触摸自己，却发现眼前的并非是我那双布满伤痕手，而是一只漆黑的羊蹄。\n啊……原来如此……原来这才是我本来的样貌，这才是母亲赋予我的……\n当我意识到这一点时，血脉最深处所埋藏的一切瞬间浮现在我的眼前，我理解了我的身份、我的使命以及……我那无法被抑制的欲望。\n「吼——————！！」\n我迫不及待的从母亲的怀中跳下，发出震耳欲聋的怒吼，冲入了兄弟姐妹之中。\n我要履行我的职责，我要践行母亲的意志。\n\n「吼——————————！！！！！！」\n随着我的加入，所有兄弟姐妹同时发出兴奋的狂吼，这吼声震撼天地，宣告了宴会的开场。\n我们舔舐，我们纠缠，我们用粗大的触手深入对方的每一个角落，随后相互撕咬，任由彼此的血肉相互交融。\n我们向外奔去，无差别地吞噬眼前的所有，我们是狂欲之母降下的不祥子嗣，是这场孽宴上的唯一主角。\n无需压抑自己的欲望，我们已褪去凡俗的外壳，我们将肆意吞噬，肆意繁衍，肆意释放传承自母亲的无上欲望。\n这是场献给母亲的宴会，我们要把这世界化为污孽的血肉，献给至高无上的母亲！\n\n泰旖丝站在宴会中央，聆听世界被吞噬的哀嚎。\n「没错，就是这样。」\n看着已经完全踏入狂欢的子嗣，慈爱的母亲露出了最本质的疯狂。\n「去吧，去吧，无需再用那脆弱之物伪装，向世界展示你们真实的模样吧！」\n薄纱随着舞步在空中飞舞，从中透出那抹若隐若现的蜜色。\n「你们是原初的使徒，你们不需要任何人承认，你们已无需再压抑自己那不被世俗认可的欲望！」\n这是一支不会停息的舞，这是一场不会停止的孽宴。\n「去将这个世界，全部变成你们的兄弟姐妹吧！」"
  },
  Item_119690_Name = {
    Text = "孽宴狂欲"
  },
