  Item_123478_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「纯全无罪的苍白使者啊，愿父神庇佑你将行之路。」"
  },
  Item_123478_Name = {
    Text = "永不褪色的昨天：萨尔瓦多"
  },
  Item_123478_StoryDesc = {
    Text = "第28期学期课题"
  },
  Item_123481_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「守密人，昨天我送你的围巾……喜欢么？」"
  },
  Item_123481_Name = {
    Text = "永不褪色的昨天：艾继丝"
  },
  Item_123481_StoryDesc = {
    Text = "第28期学期课题"
  },
  Item_123482_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「杀！杀！杀！！哈哈哈！鳟鱼鲜血的香气！」"
  },
  Item_123482_Name = {
    Text = "永不褪色的昨天：尤乌哈希"
  },
  Item_123482_StoryDesc = {
    Text = "第27期学期课题"
  },
  Item_123483_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「我会用这曾束缚我的铁链，撕碎所有妄图给我带上枷锁之人！」"
  },
  Item_123483_Name = {
    Text = "永不褪色的昨天：血链·希洛"
  },
  Item_123483_StoryDesc = {
    Text = "第26期学期课题"
  },
  Item_123484_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「玫瑰盛开的光景还是如此赏心悦目，来共饮一杯吧，我的朋友。」"
  },
  Item_123484_Name = {
    Text = "永不褪色的昨天：索蕾尔"
  },
  Item_123484_StoryDesc = {
    Text = "第27期学期课题"
  },
  Item_123485_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「今天孩子们会带回来什么呢？」"
  },
  Item_123485_Name = {
    Text = "永不褪色的昨天：阿格里帕"
  },
  Item_123485_StoryDesc = {
    Text = "第27期学期课题"
  },
  Item_123486_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「啊……请赐予我更多的疼痛吧~」"
  },
  Item_123486_Name = {
    Text = "永不褪色的昨天：雷娅"
  },
  Item_123486_StoryDesc = {
    Text = "第29期学期课题"
  },
  Item_123487_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「夜深了，小树苗。来让我们继续……昨日未尽兴之事吧~」"
  },
  Item_123487_Name = {
    Text = "永不褪色的昨天：泰旖丝"
  },
  Item_123487_StoryDesc = {
    Text = "第28期学期课题"
  },
  Item_123552_Desc = {
    Text = "「好漂亮的雪花糖啊……哎？谁说我想要！不过不收下你会失望的吧……多谢了。」"
  },
  Item_123552_Name = {
    Text = "姜饼派对·凯刻斯"
  },
  Item_123553_Desc = {
    Text = "「银霜夜快乐，守密人。喏，这是礼物。」"
  },
  Item_123553_EmojiName = {
    Text = "给你礼物"
  },
  Item_123553_Name = {
    Text = "波吕克斯·给你礼物"
  },
  Item_123554_Desc = {
    Text = "「哎呀哎呀，猜猜魔法大师丢来的盒子里，是礼物还是炸弹？」"
  },
  Item_123554_EmojiName = {Text = "扔"},
  Item_123554_Name = {
    Text = "卡茜亚·扔"
  },
  Item_123555_Desc = {
    Text = "「能否请您与我在森林中驻足一小时？我想……再感受一次糖果屋的气息。」"
  },
  Item_123555_Name = {
    Text = "姜饼派对·奥尔拉"
  },
  Item_123556_Desc = {
    Text = "「我会努力照亮大家的银霜夜。」"
  },
  Item_123556_EmojiName = {Text = "发光"},
  Item_123556_Name = {
    Text = "法洛思·发光"
  },
  Item_123557_Desc = {
    Text = "「今夜，我们将馔饮姜饼和枫糖，来共庆这伟大派对！」"
  },
  Item_123557_Name = {
    Text = "姜饼派对·杜勒赛因"
  },
  Item_123558_Desc = {
    Text = "「冬渡节快乐，恩人。啊……帽子压到羽毛了」"
  },
  Item_123558_EmojiName = {
    Text = "冬渡节快乐"
  },
  Item_123558_Name = {
    Text = "卡斯托尔·冬渡节快乐"
  },
  Item_123559_Desc = {
    Text = "不知名的存在在你的信箱里留下了这封请柬——以及一些姜香扑鼻的碎饼干渣。\n使用后可选择一个尚未获得的「姜饼派对」系列头像。"
  },
  Item_123559_Name = {
    Text = "姜饼派对的请柬"
  },
  Item_123560_Desc = {
    Text = "传说在银霜夜的晚上将袜子挂在床头，冬渡节清晨就能收到神秘礼物。切记，一定要挂洗过的袜子。\n使用后可选择一个尚未获得的「冬渡弥萨格」系列对战表情。"
  },
  Item_123560_Name = {
    Text = "冬渡节的礼券"
  },
  Item_123561_Desc = {
    Text = "「干什么，你怎么敢用这种不敬的表情看着本神母？！」"
  },
  Item_123561_EmojiName = {Text = "袜子"},
  Item_123561_Name = {
    Text = "诞妄·墨菲·袜子"
  },
  Item_123638_Desc = {
    Text = "孩子们在银霜夜前夕准备的祈愿箱，上面贴有写着想要的礼物的字条。\n“我已经当了一年好孩子啦，这下冬渡使者总该给我礼物了吧！”"
  },
  Item_123638_Name = {
    Text = "银霜祈愿箱"
  },
  Item_123639_Desc = {
    Text = "只在冬渡节清晨出现的特殊礼物盒，被开启后会迅速消失，因此鲜有人知晓这个秘密。\n“嘘，这是好孩子跟冬渡使者之间的秘密哦。”"
  },
  Item_123639_Name = {
    Text = "冬渡礼物盒"
  },
  Item_123757_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「谢，谢谢您……啊！请不要靠近……会，会伤到您的……」"
  },
  Item_123757_Name = {
    Text = "永不褪色的昨天：菲茵特"
  },
  Item_123757_StoryDesc = {
    Text = "第29期学期课题"
  },
  Item_124899_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「罗网轮转」。\n\n纺织，丈量，以及裁断。\n命运的神明无悲无喜，命运的纺轮亘古不息。"
  },
  Item_124899_Name = {
    Text = "罗网轮转"
  },
  Item_124899_StoryDesc = {
    Text = "纺织，丈量，以及裁断。\n命运的神明无悲无喜，命运的纺轮亘古不息。"
  },
  Item_125136_Desc = {
    Text = "属性为伤害强效的命轮。"
  },
  Item_125136_Name = {
    Text = "玉兰之饵"
  },
  Item_125136_StoryDesc = {
    Text = "那是我与父亲移居海城的第二年，伊芙莲在信中的哭诉使我心烦意乱，我已决意同她分别。这是由丝绸与乌木装潢的富饶之地，所有食腐者都嗅到了它沉睡时的混乱，纸钞的面值能换来等重的黄金，掌握了那些航线，就能以极小的成本撬动千万倍的财富。\n然而伊芙莲，也许是源于她晦涩难追的怪异血统导致的神经质，这个女人坚信所谓先祖的传讯，东方有祂们的旁支所信奉的邪异神明，如同深海中的某种鱼类，会悬垂下招摇美味的饵，将猎物引入一场难以察觉的缓慢进食。\n她错了，海城没有半丝来自海的咸味。\n只有层层叠叠，馥郁到令人迷醉，又心生恐惧的白玉兰。\n令我和父亲同时陷落的白玉兰。\n当我看到她的时候，那个名为「徐」的女人的身影出现在我视线中的第一秒，我就永远不再可能从这片古老的陆地脱身了。\n她令人想要靠近，她令人想要占有，她令人想要@3\n她令人令人令人令人令人令人想要想要想要想要想要\n\n切碎割开砍碎永远永远永远永远永远……@2@3@2！！\n啊，我为什么来到这里？我要带走什么？我是……谁？\n不再重要了，她邀请了我，我坐在那座大宅的桌前。\n早已与我一样疯狂的父亲，脸上挂着乖顺的笑，琳琅满目的配菜摆满餐桌，显得金属带盖餐盘格格不入。\n\n徐逆着光线坐在夕阳中，光晕为她镶上了一层绒绒的金边，缓缓地，那把黑扇放下了。\n像伊芙莲、像我幼时的玩伴、像朦胧间的艳遇……像我的母亲。\n那是一张如同庙宇里鎏金神像般端方美丽的脸。\n我没有听见吮吸声，也没有嗅到父亲身上传来的腥味，只是痴迷地注视着那张脸，以及那张脸的主人伸出一只素白的手，揭开餐盘，捡拾出合适的肉，她用两根细木棍将它钳起，抬高。\n她唤我，烘烤过后的动物油脂滴在我的嘴角。\n「小先生，你该吃些东西。」\n我温顺而木讷地张开嘴。\n玉兰花已经开了，它在簌簌地向我悬垂。\n——「无名者手记」"
  },
  Item_125137_Desc = {
    Text = "男人们争相送上奇珍异宝，却纷纷被要求去每日买来最浓稠甜蜜的那锅梨膏糖。\n她不会让它腐蚀那位小小姐的牙齿，就像邪神总爱应允坏愿望。\n\n至少掉落{s1}个"
  },
