    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得徐时转换获得，用于激活徐的启灵。"
  },
  Item_125187_Name = {
    Text = "残片·徐"
  },
  Item_125187_StoryDesc = {
    Text = "重复获得徐时转换获得，用于激活徐的启灵。"
  },
  Item_125188_Desc = {
    Text = "男人们争相送上奇珍异宝，却纷纷被要求去每日买来最浓稠甜蜜的那锅梨膏糖。\n她不会让它腐蚀那位小小姐的牙齿，就像邪神总爱应允坏愿望。\n\n至少掉落{s1}个"
  },
  Item_125188_Name = {Text = "梨膏糖"},
  Item_125189_Desc = {
    Text = "男人们争相送上奇珍异宝，却纷纷被要求去每日买来最浓稠甜蜜的那锅梨膏糖。\n她不会让它腐蚀那位小小姐的牙齿，就像邪神总爱应允坏愿望。\n\n至少掉落{s1}个"
  },
  Item_125189_Name = {Text = "梨膏糖"},
  Item_125190_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「深宅往事」。\n\n深宅里埋藏了太多秘密，关于权，关于痴，关于欲。\n关于邪神向尘世投来一瞥，饱含「愉悦」与「扭曲」的爱意。"
  },
  Item_125190_Name = {
    Text = "深宅往事"
  },
  Item_125190_StoryDesc = {
    Text = "深宅里埋藏了太多秘密，关于权，关于痴，关于欲。\n关于邪神向尘世投来一瞥，饱含「愉悦」与「扭曲」的爱意。"
  },
