  },
  Item_128552_Name = {Text = "车票"},
  Item_128659_Desc = {
    Text = "不仅祈岁节当天，接下来的整整半个月，磐龙古国四处都会洋溢着喜悦的气氛。\n人们带着礼物，四处走亲访友。所有象征着财富、喜悦、以及祝福意味的好东西，都会带着最美好的祝愿被塞进这个礼盒。"
  },
  Item_128659_Name = {
    Text = "祈岁鸿运盒"
  },
  Item_128660_Desc = {
    Text = "在磐龙古国，每个孩子都盼望着祈岁节的到来。\n枣泥饼、花生酥、杏仁糖，还有父母长辈准备的压岁钱，获得这样一份礼物，一定会度过吉祥如意的一年。"
  },
  Item_128660_Name = {
    Text = "祈岁吉祥箱"
  },
  Item_129143_Desc = {
    Text = "逸散在欢愉列车上的情绪粒子，触碰时仿佛能听到小「N」的笑声。\n用于提升守密人在「疾驰的欢愉专列」中的共鸣。"
  },
  Item_129143_Name = {
    Text = "留影之心"
  },
  Item_129498_Desc = {
    Text = "贵宾积分达到一定值时，「雅室规格」等级提升。可在「疾驰的欢愉专列」中获得。"
  },
  Item_129498_Name = {
    Text = "贵宾积分"
  },
  Item_129499_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「岁末花火」。\n\n岁岁年年花相似，年年岁岁盼团圆。\n今夕祈岁，一枕之梦。愿妾身的小茉莉花于故人身畔，携手共赏万千焰火之时，勿忘妾身情义。"
  },
  Item_129499_Name = {
    Text = "岁末花火"
  },
  Item_129499_StoryDesc = {
    Text = "岁岁年年花相似，年年岁岁盼团圆。\n今夕祈岁，一枕之梦。愿妾身的小茉莉花于故人身畔，携手共赏万千焰火之时，勿忘妾身情义。"
  },
  Item_129628_Desc = {
    Text = "属性为银钥充能等级的命轮。"
  },
  Item_129628_Name = {
    Text = "踏过泥泞的玫瑰"
  },
  Item_129628_StoryDesc = {
    Text = "在无法被记录的某个循环中，环行·拉蒙娜踏过钟楼后的花圃。\n余光瞥见玫瑰园中，丛丛鲜花正绽放得妍烈。\n罕见的片刻停滞后，她便抛下所有无谓的遐思，继续奔赴最终的战场。\n泥泞泼溅在血色般浓烈的花瓣上，转瞬被漆黑的融蚀浆吞噬，只留下风中傲然的背影。"
  },
  Item_129898_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「雅致的餐品需要时间来雕缀，啊~我期待着，你那刻骨铭心的香味。」"
  },
  Item_129898_Name = {
    Text = "永不褪色的昨天：杜勒赛因"
  },
  Item_129898_StoryDesc = {
    Text = "第29期学期课题"
  },
