  },
  Item_130039_StoryDesc = {
    Text = "书架上除了枯燥的研究文献之外，还有几本看起来很有趣的儿童读物。\n《灰姑娘》、《白雪公主》、《美人鱼》、《长发公主》……它们的主人为何会将这些书收在书架上——如今已无从得知。\n\n那些故事编织着与现实截然不同的情节。「王子」、「公主」、「爱」……这些词语令少女的心怦然悸动。\n\n夜空中闪烁的无数光芒倾洒向大地，仿佛即将汇成一条流淌的光之河。\n在洒落的月光中，少女悄悄踮起脚尖，假装踩上一双透明的玻璃鞋。仿佛一直在期盼着——这深沉、孤寂的漫漫长夜终将破晓……"
  },
  Item_130040_Desc = {
    Text = "纯洁无瑕，令人心生亲近的鳞粉，似乎和沙耶的苗圃能够产生奇妙的共鸣。\n把它带给沙耶，可以获得来自她的奖励。\n\n至少掉落{s1}个"
  },
