  Item_130063_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「献给新世界」。\n\n绽放，绽放，将整个世界染成欢喜的颜色。\n那是久远的治愈，悠久的至福，是沙耶送给即将揭幕的新世界的，最后的礼物。"
