  Item_130546_Name = {
    Text = "弥萨格幕间剧：艾尔瓦"
  },
  Item_130547_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「那个......我、「我们」可以饰演很多角色——如果你需要的话。」"
  },
  Item_130547_Name = {
    Text = "弥萨格幕间剧：「24」"
  },
  Item_130547_StoryDesc = {
    Text = "第36期学期课题"
  },
  Item_130548_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「浪费科研时间来演话剧……不，我没说不喜欢。咳咳，剧本上写的是这个表情么？」"
  },
  Item_130548_Name = {
    Text = "弥萨格幕间剧：朵尔"
  },
  Item_130548_StoryDesc = {
    Text = "第31期学期课题"
  },
  Item_130549_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「这是迷迭香，代表追忆；还有三色堇，代表思虑......啊，抱歉，我在念台词。这段携花而上的戏，我很喜欢。」"
  },
  Item_130549_Name = {
    Text = "弥萨格幕间剧：宁菲亚"
  },
  Item_130549_StoryDesc = {
