  Item_130551_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「台词什么的不重要，重要的是气势！」"
  },
  Item_130551_Name = {
    Text = "弥萨格幕间剧：诺缔拉"
  },
  Item_130551_StoryDesc = {
    Text = "第31期学期课题"
  },
  Item_130552_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「赌一把？就赌这幕剧的结局如何？」"
  },
  Item_130552_Name = {
    Text = "弥萨格幕间剧：莱克"
  },
  Item_130552_StoryDesc = {
    Text = "第34期学期课题"
  },
  Item_130553_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「抱歉……我不太适应这种……亮闪闪的感觉……」"
  },
