  },
  Item_130700_Desc = {
    Text = "小煤球，讨厌，莫丝，喜欢！小煤球，上交，奖励~\n\n至少掉落{s1}个"
  },
  Item_130700_Name = {
    Text = "海螺三号"
  },
  Item_130701_Desc = {
    Text = "小煤球，喜欢！莫丝，喜欢！收集，越多越好~\n\n至少掉落{s1}个"
  },
  Item_130701_Name = {
    Text = "海螺一号"
  },
  Item_130702_Desc = {
    Text = "朋友，喜欢，莫丝，收集！帮忙，奖励！送给朋友~\n\n至少掉落{s1}个"
  },
  Item_130702_Name = {
    Text = "海螺二号"
  },
  Item_130703_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「溺亡的纯真」。\n\n即使深知注定溺亡，她依然义无反顾地投身冰冷的大海。\n因为这是她纯真的思维中，拯救朋友的唯一方法。"
  },
  Item_130703_Name = {
    Text = "溺亡的纯真"
  },
  Item_130703_StoryDesc = {
    Text = "即使深知注定溺亡，她依然义无反顾地投身冰冷的大海。\n因为这是她纯真的思维中，拯救朋友的唯一方法。"
  },
  Item_130704_Desc = {
    Text = "专注于增幅使用者狂气爆发的命轮，能够在探索中周期性回复狂气并提高其狂气爆发伤害，切换至怒涛姿态时提供大量界域精通。"
  },
  Item_130704_Name = {
    Text = "渺远的伊甸园"
  },
  Item_130704_StoryDesc = {
    Text = "这是一座没有记录在任何海图上的岛屿。\n从它诞生之初，名为「文明」的病毒便从未踏上过这片净土。\n这里只有沙滩，丛林，一眼望不到头的大海，以及……一位小小的少女。\n………………………………\n「爸爸，妈妈，鱼！」\n「嗷~~」\n两只海豚不紧不慢地游到少女脚边，发出优美清脆的叫声。\n其中一只将少女驮起，另一只接过少女手中刚被打晕的鱼，一口将其吞下。\n「嗷~~」\n「嘿嘿，莫丝！厉害！」\n像不谙世事的孩童，少女做了个很有力量感的动作，来回应「爸爸」「妈妈」的夸奖。\n「今天，太阳！好！」\n「莫丝！爸爸！妈妈！散步！」\n听闻少女的话，驮着少女的海豚轻吟一声，绕着小岛开始缓缓游动。\n温暖的阳光洒在少女身上，驱散了数日前挥之不去的湿冷，轻柔的风拂过少女的发丝，带来了海洋慵懒的呼吸。\n笑声，拍水声，嬉闹声，与世隔绝的小岛上没有「文明」带来的烦恼，只留下了最原始、最纯粹的欢笑。\n两兽一人如往常一样，度过了原始又无忧的一天。\n………………………………\n直到那无边的呼唤，将这份静谧彻底吞噬。\n「回来吧……回来吧……」\n「@1需要你……@2……@4……需要你……」"
  },
  Item_130705_Desc = {
    Text = "朋友，喜欢，莫丝，收集！帮忙，奖励！送给朋友~\n\n至少掉落{s1}个"
  },
