  },
  Item_131369_StoryDesc = {
    Text = "金碧辉煌的俱乐部门口，身穿白衬衫的迎宾员抬起一只手，礼貌地拦住了莱克。\n「先生，您没有邀请函，也并非我们的会员，无法进入。」\n「是吗……这就难办了啊……」\n莱克用手摸了摸下巴，装出一副思考的样子。实际上，他只是在等待。\n等待手中案件的嫌疑人。\n等待那注定的，命运的眷顾。\n果然，他等到了——\n「这不是闻名伦蒂尼恩的好运侦探吗！来来来，我愿意做你的引荐人。」\n「我早就想见识见识你那传奇的运气了，可千万不要让我失望啊……」\n绅士说着，露出看似温和却满怀恶意的笑。\n这样的神情在俱乐部很常见，毕竟你不能指望追求着狂欢的赌徒们循规蹈矩。所以当意识到自己被做局时，莱克并不在意，只是弯起嘴角，从容不迫地拿起了惠斯特牌。\n不要着急，游戏才刚刚开始，不是吗？\n于是，第一局，第二局，第三局……一场接着一场。\n直到莱克输光所有筹码。\n「好运侦探，看来你今天的运气并不好。也对，没有人能永远受到命运的眷顾……」\n「还要继续吗？侦探，可惜你已经一无所有了。」\n「一无所有？并不见得。」连输到底的侦探笑了笑，指了指自己，「我还有这套得体的礼服，还有这把昂贵的手杖，还有……」\n侦探顿了顿，从礼服的胸袋里拿出一枚小巧的仪器，压低声音，微笑着把玩，「我承认你的出千手法极其巧妙，就连这家俱乐部的主人也无法破解，只能寻求我的帮助。但再精妙的手法也需要时间，需要操作，需要配合。」\n「真不巧，这个弥萨格出品的小玩意，已经清晰地记录了你和你的同伙刚才在俱乐部出千的证据。」\n绅士愣了一下，惊愕又愠怒，他的同伙更是恼羞成怒，想要给侦探一个教训。但众目睽睽下，绅士不敢轻举妄动，更何况，侦探给了他一个选择，一个他无法拒绝的选择。\n「再赌一把，怎么样？若是你赢了，这个小玩意和我的命，就都归属于你了。你明白我的意思。」\n「那若是我输了呢？」\n「输了就要麻烦你去自首了。」莱克笑着耸了耸肩，露出闪亮的獠牙，「你觉得自己会输吗？真正的赌徒，只愿意相信自己会赢。」\n是的，每个赌徒都觉得自己会赢。所以无论是谁，都无法拒绝这个赌局。\n于是，惠斯特牌再次流转于牌桌，出牌，垫牌，纂牌，最终，分出胜负。\n「Lucky~」\n没有再看输家一眼，莱克笑着扬手，将那些赢来的钱财扔向空中。于是，本就喧嚣的俱乐部越发狂热，充满了人们争抢的呐喊、获得财富的尖叫和欢笑。\n而在这呐喊、尖叫和欢笑里，莱克将弥萨格颁发的、人手一个的装饰品收回胸袋，又拍了拍裤兜里的写着自己姓名的邀请函，弯起嘴角压了压自己的帽子。\n真正的赌徒，只愿意相信自己会赢。\n因为他坚信，无论做了什么，命运的眷顾始终与他同行。\n"
  },
