  Item_133405_Name = {
    Text = "弥萨格幕间剧：塔薇"
  },
  Item_133406_Desc = {
    Text = "「啊啊啊！我不要看这些啊！」"
  },
  Item_133406_Name = {
    Text = "守密人·震撼"
  },
  Item_133406_StoryDesc = {
    Text = "第32期学期课题"
  },
  Item_133477_Desc = {
    Text = "尚能行动的右手拖着少女残破的躯体，缓缓地向漆黑的淤泥蠕动。\n铁链交错的响声回荡在空无一人的监牢里，没人会在意一个奴隶的死活，见证这一切的只有墙角的累累白骨。\n她不知道自己是否会成为这些白骨中的一员，她只知道，人们是如此畏惧它的力量。\n\n「起码不会……比现在更差了……」\n\n淤泥顺着少女纤细的食指逆流而上，瞬间覆盖少女全身。\n它开始翻涌，开始沸腾，它像是终于找到了注定之人般欣喜若狂。\n许久，监牢内重归平静，扭曲的双手从茧状的淤泥中刺出，撕开了隔绝她与世界的最后壁障。\n少女平静地注视着已经异化为黑色脓液的四肢，四肢和脖颈上的铁链在全新的力量前脆弱不堪，她第一次感到如此轻松。\n她贪婪地呼吸着监牢内的空气，尽管此刻周围充满生物尸体和排泄物的腐臭，但她毫不在乎。\n因为她终于品尝到了，自出生起就梦寐以求的——自由的味道。\n监牢已破，复仇女神开始挥舞她的利爪，向所有奴役者发起复仇。\n……………………\n人们哭喊。\n「救，救命啊！这个奴隶发疯了！卫兵！卫兵在哪？！」\n人们哀求。\n「不要杀我！求求你放了我……我，我把所有钱都给你！」\n人们逃窜。\n「王已经死了！快逃，快逃啊！她不是人……她不是人！」\n人们沉默。\n「…呜…………呃………」\n……………………\n少女停止了屠杀，随手抛下面容扭曲的头颅，那是一副因异物堵塞呼吸道，窒息而死的模样。\n宣泄过后的少女开始思考，她到底要做什么。\n风裹挟着淤泥和血污，肆意涂抹着尸横遍野的城邦。\n最终，少女踏出脚步。\n她将作为一个战士，一个永不停歇的战士，去埋下自由的种子。\n她将一路向北，直至极地尽头。"
  },
