  },
  Item_133706_Desc = {
    Text = "「在很多、很多很多年以前，人类还没有诞生的时候，鹦鹉螺就存在了。」\n「它们的螺壳记住了洋流的方向、海水的温度、陆与海的变迁。」\n「它们也记住了所有的声音，你听。」\n年幼的诺缔拉好奇地把海螺贴到耳边，眼前的海浪在礁石上拍打，螺壳中传来的浪潮声在诺缔拉的耳边拍打。\n她惊喜地睁大了眼睛。\n「妈妈，如果我对它说话的话，下次我们重逢的时候，它也会记住我吗？」\n那些温柔的回答后来和海边的风一起消散了，答案无人知晓。小小的诺缔拉嘀嘀咕咕地和海螺说了很久的话，但担心这个过小的壳没办法装进太多，想了又想，最后决定留下最重要的一句。\n「你好，海螺，我会成为一个伟大的冒险家，再去找你的。等再见面，我一定能记得你，所以，约好了，你也要记得我啊！」\n后来、后来……\n后来发生了什么呢，那已经是很多年以前的事情了。\n诺缔拉觉得自己遗忘了什么重要的事情，但就像螺壳会替鹦鹉螺记住一样，诺缔拉救了自己的朋友，她总觉得自己应该这么做，因为似乎有人曾经为她做过。\n所以她伟大的冒险戛然而止，就像所有的冒险家都会有一个突如其来的结尾，她沉沉地向大海深处坠去。\n看到那枚快要被融蚀浆吞没的鹦鹉螺时，诺缔拉好像想起来了。\n这好像是很久之前的下午，被她放入大海的海螺。\n「下次我们重逢的时候，它也会记住我吗？」\n在痛苦的窒息来临之前，在最后一口空气被水压从肺中挤出去之前，诺缔拉拼尽全力伸出手，把海螺贴到了耳边。\n它伸出了濡软的腹足。\n诺缔拉什么都没能听见。"
  },
  Item_133706_Name = {
    Text = "螺纹回音"
  },
  Item_133766_Desc = {
    Text = "与灵魂共鸣之物，如今只残余轮廓碎片。愿散落各地的希望的聚合能带来穿透现实的增幅。\n可以在「冶炼室」中合成「灵魂回溯之芯」。"
