  Item_140416_Name = {
    Text = "不谐音合奏"
  },
  Item_140416_StoryDesc = {
    Text = "V2.5.1头像礼包"
  },
  Item_140417_Desc = {
    Text = "第一乐章，起。在他高抬的双手落入静息之前，整座宇宙都回响着终末的奏鸣之声。"
  },
  Item_140417_Name = {
    Text = "寰宇奏鸣"
  },
  Item_140418_Desc = {
    Text = "「玫瑰滴落鲜血，于火中化作最后的诗章。优雅、浪漫、以及悄无声息的泪珠。」"
  },
  Item_140418_Name = {
    Text = "玫瑰的诗章"
  },
  Item_140418_StoryDesc = {
    Text = "V2.5.1头像礼包"
  },
  Item_140459_Desc = {
    Text = "在举起指挥棒之前，世界充满了令人厌恶的噪声。\n父亲的严苛手掌无数次重重落在琴盖，宫廷走廊的蚊蝇窃窃私语，报纸上关于他的讨论喋喋不休。\n「安静。」\n@3皇家歌剧院，@3六年春。\n年轻的宫廷乐师第一次站上首席指挥的台阶，质疑与期待的声音同样强烈。他是如此年轻、沉默，带着他明亮灼人的天赋，如同一尊从未被允许现世的瓷器。如今，这尊瓷器第一次在殷红的舞台上举起指挥棒。\n在指挥棒抬起的一瞬间，整座剧院的空气便被某种无形的力量攫住。那是引力与潮汐，是音乐的宇宙里不可违逆的公理。\n指挥棒落下，音符撕开寂静的帷幕，首席小提琴手的弓弦轻轻颤抖。他早已忘记面前站着的是一个比他小了五十岁的孩子，指挥棒的弧线带领着他，他的手指已不再属于自己。\n弦乐涌入，铜管应和，定音鼓在精确的节点炸响。每一个声部都被无形的丝线牵引，臣服于指挥台上那些优雅的轨迹。\n哈姆林的嘴唇抿成一道冷淡的弧线，苍白年轻的面孔精致得近乎不真实。指挥棒的每一次挥动都带着不容置疑的命令，从第一次握住指挥棒时他便清晰地知道，音乐从不是被演奏，而是被统治的。\n乐章行至华彩段，哈姆林望向木偶般的乐手，他的眼里没有任何人。在关于音乐的舞台上，他是唯一的独裁者。\n终章。最后一个音符消亡在寂静中，长久的沉默后掌声如潮水般涌来。\n今天的头条是属于哈姆林的。年轻的天才收获了从未有人收获的名誉与追捧。面对此生第一次万众狂热的喝彩，年轻的指挥家脸上没有丝毫的笑意。\n他鞠躬，缓缓放下指挥棒，离开了人生第一次登上的舞台，推拒了宫廷的筵席，回到了他的琴房。\n凡庸的乐手，不够精准的颤音，偏差了八分之一拍的呼吸——一切的瑕疵，都是对音乐的亵渎。在满堂喝彩中，他听见了唯一真实的声音：头顶那座遥不可及的穹顶之后，有什么东西正在为他鸣响。祂呼唤他，斥责他，等待他。他们终将相遇，在相遇的那一刻，他必须是完美的。\n那一天，恶魔乐师的序曲征服了他的第一座舞台。\n而那漫长的通往神祇的乐章，才刚刚开始奏响。"
  },
  Item_140459_Name = {
    Text = "万籁序曲"
  },
  Item_140460_Desc = {
    Text = "获得幻衣「万籁序曲」后解锁。\n「慢了八分之一拍。一场失败的演出。」"
