  Item_141227_Name = {
    Text = "古老的「猎物」"
  },
  Item_141228_Desc = {
    Text = "众所周知，深渊里的鱼会随便乱长，过于硕大是正常的，与人类相似……也是正常的。\n\n至少掉落{s1}个"
  },
  Item_141228_Name = {
    Text = "硕大的「猎物」"
  },
  Item_141229_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得庞托斯时转换获得，用于激活庞托斯的启灵。"
  },
  Item_141229_Name = {
    Text = "残片·庞托斯"
  },
  Item_141229_StoryDesc = {
    Text = "重复获得庞托斯时转换获得，用于激活庞托斯的启灵。"
  },
  Item_141230_Desc = {
    Text = "别管鱼为什么会在陆地上跑，这里是厄波扬斯。"
  },
  Item_141230_Name = {
    Text = "新鲜的「猎物」"
  },
