  },
  Item_141233_Name = {
    Text = "古老的「猎物」"
  },
  Item_141508_Desc = {
    Text = "让装备者陷入沉睡，醒来后强化狂气爆发的战术型命轮。"
  },
  Item_141508_Name = {
    Text = "梦游仙境"
  },
  Item_141508_StoryDesc = {
    Text = "传说中只要孩子在森林里追着一只野兔奔跑，就有概率掉进通往异世界的树洞。\n莉莉光滑的小脚踩上鹅卵石的小径。\n「莉莉喜欢这里……地面上不会有玻璃碎渣，空气中也没有消毒水的气味。」\n莉莉深吸了一口清新的空气，掠过林间的风卷来奇异花香的气息。\n头顶的树冠交织成彩色玻璃般的穹顶，碎落的阳光像是满地跳动的宝石，瑰丽而迷幻的景致让莉莉几乎不知道应该往哪个方向看。\n「啊，刚才的兔子先生！」\n草丛中冒出一双熟悉的灰色长耳朵，莉莉急忙追了过去。\n脚下的苔藓每踩一步就绽开一朵细小的银花，但莉莉也无暇顾及。她还有更重要的话要找兔子先生说。\n淌过流着蜂蜜色光芒的小溪，穿过会唱歌的芦苇丛。\n气喘吁吁的莉莉终于捉住了兔子先生绒球一样的尾巴。\n「兔子先生，你愿意和丽莎做朋友吗？」\n「丽莎是我的朋友，可是其他人现在都很害怕她……如果是兔子先生的话，一定能和她成为朋友的！」\n兔子先生回头的瞬间，漫天萤火升腾而起。\n「当然，@2是所有人的朋友。不过，现在，你该休息了。」\n于是，莉莉抱着已经成为朋友的兔子先生，爬到森林深处那颗高大的巨树下。\n在飘散的萤火虫温暖的包围中，莉莉倚着巨树的根系，安静地睡着了。\n「受试者：莉莉。临床表征：呼吸平稳，眼球转速正常。第359次意识干涉实验，成功。」\n那是如梦幻一般绮丽的奇幻世界。"
  },
  Item_141529_Desc = {
    Text = "解锁后，完成「秘境游记」全部任务可额外获得以下奖励"
  },
  Item_141529_Name = {
    Text = "秘境游记"
  },
  Item_141666_Desc = {
    Text = "到底是镀金的苹果还是真正的金苹果呢……？只有仙女才知道答案。将它供奉给仙女，可以获得一些奖励。\n\n至少掉落{s1}个"
