  Item_145970_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「并非谎言之物」。\n\n恶贯满盈的毒蛇曾用它蛊惑伊甸园内纯真无知的人类，满腹嫉妒的王后曾用它诱骗雪白无辜的公主，徒有智慧的凡人也曾凭借它赢下荒野猎手的赛跑。\n但此物并非谎言。\n它只是人心底里那一点不能宣之于口的欲望。"
  },
  Item_145970_Name = {
    Text = "并非谎言之物"
  },
  Item_145970_StoryDesc = {
    Text = "恶贯满盈的毒蛇曾用它蛊惑伊甸园内纯真无知的人类，满腹嫉妒的王后曾用它诱骗雪白无辜的公主，徒有智慧的凡人也曾凭借它赢下荒野猎手的赛跑。\n但此物并非谎言。\n它只是人心底里那一点不能宣之于口的欲望。"
  },
  Item_146353_Desc = {
    Text = "逸散在新月雪峰的情绪粒子，触碰时仿佛能听见诡计得逞的嬉笑声。\n用于提升守密人在调查事件「山宴」中的共鸣。"
  },
  Item_146353_Name = {
    Text = "赐福之心"
  },
  Item_146538_Desc = {
    Text = "解锁后，完成「终北纪行」全部任务可额外获得以下奖励"
  },
  Item_146538_Name = {
    Text = "终北纪行"
  },
  Item_146539_Desc = {
    Text = "后勤部向完成「调查行动」的守密人发放了特别许可，在每次完成调查行动后，守密人都可以为下一次的出发购置一批特别的珍贵银芯制品。\n数量有限，愿银钥指引我们。"
  },
  Item_146539_Name = {
    Text = "调查历程特典·星辰篇Ⅵ"
  },
