  },
  Item_147549_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「临时文本」。\n\n（待补充钥令风味文案。）"
  },
  Item_147549_Name = {
    Text = "临时文本"
  },
  Item_147549_StoryDesc = {
    Text = "（待补充钥令风味文案。）"
  },
  Item_147580_Name = {
    Text = "卡拉布手册"
  },
  Item_147581_Name = {Text = "八咫镜"},
  Item_147598_Name = {
    Text = "图鲁王冠"
  },
  Item_148117_Desc = {
    Text = "打出可以获得算力，留在手中积攒生命回复和狂气资源，并提供一次复活的综合型命轮。"
  },
  Item_148117_Name = {
    Text = "魂灵同调"
  },
  Item_148117_StoryDesc = {
    Text = "空旷的实验室内，各类精密的仪器均规整地摆放着，只有无数管线交错，如同蜿蜒缠绕的蛇，伏在地面，吊在空中。\n思维的信号宛如一条无人可见的河流，但天才早已习惯于与之打交道。大脑是它们的源头，再淌过机械的管线，最终汇聚在这具新造的躯壳中。\n意识被传递的同时，许多尘封的记忆也被久违地翻出，家人、弥萨格、未完成的实验……恍惚间，天才想起许多年前，在她还未脱离最初的肉身桎梏时，曾有个无聊的学生，饶有兴趣地围着她转来转去，眼里闪烁着名为好奇心的光芒。\n「您认为，人造的躯体能承载真正的魂灵吗？」\n凡人总爱幻想一些远超他们视野的事物，这是个庸俗的问题。但身为教师，她仍给出了几句回应，纵然没抬一下眼。\n「你的身体未尝不是人造之物，心脏、四肢、五感这些器官的运行又和机械有何区别？」\n「好了，比起胡思乱想这些，不妨抽出时间，好好锻炼下你那生锈的大脑，否则，你这具流通着血液的肉体只会更无用。」\n如今，发问之人早已被时间的砂砾掩埋，不复存在。唯有承载智慧的脑缸仍在思考，并永远思考。\n世人口中所谓的魂灵不过是860亿个神经元交错而成的电化学活动，血肉也好，机械也罢，原材料的相异不会改变它们只是载体的本质。\n是啊，凡人无能为力，但身为天才的她能够做到，且已经做到——唯有如此，才能解明世界的真理，抵达知识的顶端。\n视觉，不过是光线穿过眼球，最终于视网膜上聚焦成像。\n嗅觉，不过是气味分子与受体结合，划过神经的化学感知路径。\n听觉，不过是声波经耳蜗换能，转化为上传至皮层的电信号。\n人偶身处之地太过昏暗，微弱的灯光摇曳，连影子也无法被映照。她双目微闭，因为清楚哪怕睁开它们，映入眼帘的也不过是一成不变的画面。\n房间被打扫得一尘不染，瓶罐中的药液也被紧紧封存。机体不需要呼吸，更没必要为了测试感官而去摄取这无味的空气。\n唯有一声冰冷的机械提示音，回荡在空旷的实验室中：\n「意识同调完成，机体启动确认。」\n足够了。\n虽是无机质的声音，但听起来倒亲切，仿佛锚定了物质世界的真实，又像只是在单纯提醒她，短暂的休憩结束，是时候投身于新一轮的研究中了。"
  },
  Item_148118_Desc = {
    Text = "解锁后，完成「课余时间」全部任务可额外获得以下奖励"
  },
  Item_148118_Name = {
    Text = "课余时间"
  },
  Item_148403_Desc = {
    Text = "这是你与唤醒体「彼此为我」的证明。\n唤醒体同调率达到 Lv20级时获得，将自动装配展示于该唤醒体卡面。"
  },
  Item_148403_Name = {Text = "曜闪"},
  Item_148404_Desc = {
    Text = "同心的终极之证。你们眼中的彼此已非「他者」，彼此之间，只剩下两种形体，以及同一个灵魂。"
  },
  Item_148404_Name = {
    Text = "同心之证"
  },
  Item_148479_Name = {
    Text = "阿拉克捏纺线"
  },
  Item_148480_Name = {Text = "金苹果"},
  Item_148481_Name = {Text = "旧银钥"},
  Item_148482_Name = {
    Text = "希洛眼球"
  },
  Item_148483_Name = {Text = "金币包"},
  Item_148484_Name = {Text = "黑羽"},
  Item_20124_Name = {
    Text = "通用照片"
  },
  Item_20468_Name = {Text = "病例"},
  Item_20469_Name = {
    Text = "孟菲斯仪式镜"
  },
  Item_20470_Name = {
    Text = "日月轮盘"
  },
  Item_20481_Desc = {
    Text = "扑通，扑通。\n散落在无光之境中的小小心脏，是「祂们」最爱的食物。\n用以交换命轮和无垢之芯等物资。"
  },
  Item_20481_Name = {
    Text = "黑色贡物"
  },
  Item_20482_Desc = {
    Text = "金闪闪的徽章，上面篆刻象征雷欧王国的蔷薇。在地下市场能卖个不错的好价钱。\n用以表彰在调查行动中取得优异成绩的守密人，用以在交换商店中兑换物资。"
  },
  Item_20482_Name = {
    Text = "调查徽章"
  },
  Item_21764_Name = {
    Text = "雕塑习作"
  },
  Item_21775_Desc = {
    Text = "它们的肉体、灵识和记忆都被封装于此，直到被唤醒的那一刻。\n可从中选择1个「界域研习」中的以下唤醒体唤醒：\n诺缔拉、宁菲亚、潘狄娅、艾尔瓦、珈伦；戈利亚、法洛思、凯刻斯、珊、希莱斯特；希洛、阿格里帕、尤乌哈希、雷娅、菲茵特；莉兹、汀克特、温柯尔、詹金、卡茜亚。"
  },
  Item_21775_Name = {
    Text = "原质乐园"
  },
  Item_21799_Desc = {
    Text = "请提供交易账户及密码。\n流通于王国地下市场的交易凭证，守密人可据此购入所需的稀有物资。"
  },
  Item_21799_Name = {
    Text = "密银交易凭证"
  },
  Item_21898_Desc = {
    Text = "记载了珍稀命轮的神秘古籍。\n可从中选择1个「轮转之相」中的以下SSR命轮获得：\n记忆螺旋、腐朽赠礼、欲海浮沉、坚韧意志、无声欢宴；巨人之刃、于暴雨之中、伤痛之鳍、珊瑚女之死、引舵之帆；挣脱锁链之日、苍白后裔、血肉狂宴、饕餮寓言、吞噬摇篮曲；旋转，旋转、被缚的歌谣、无法完成的演算、迷失的道路、快乐魔法秀。"
  },
  Item_21898_Name = {
    Text = "轮转之书"
  },
  Item_22164_Desc = {
    Text = "请遵照说明书使用，切勿过量。\n存放灵知制剂的补给箱，为执行任务的守密人提供援助。"
  },
  Item_22164_Name = {
    Text = "调查补给"
  },
  Item_22165_Desc = {
    Text = "没有什么是一支灵知制剂无法解决的。如果有，那就再来几支。\n存放灵知制剂的补给箱，为执行任务的守密人提供援助。"
  },
  Item_22165_Name = {
    Text = "每周制剂礼盒"
  },
  Item_22166_Desc = {
    Text = "每周都能获取的小小助力。\n存放特批药剂的补给箱，为执行任务的守密人提供援助。"
