  Item_22166_Name = {
    Text = "每周特批礼盒"
  },
  Item_22167_Desc = {
    Text = "充足的后勤补给是成功的一半。\n存放珍惜补给的补给箱，为执行任务的守密人提供援助。"
  },
  Item_22167_Name = {
    Text = "限时全界域补给"
  },
  Item_22168_Desc = {
