  },
  Item_22168_Name = {
    Text = "月度制剂礼盒"
  },
  Item_22244_Desc = {
    Text = "繁衍吧，繁衍吧。让流淌着母树鲜血的灵魂遍及世界。\n随机掉落再衍化密契套装部件。"
  },
  Item_22244_Name = {Text = "再衍化"},
  Item_22717_Desc = {
    Text = "在「幻梦深潜」和「相位对弈」获得的守密人经验翻倍！（每日 240 上限不变）。"
