  },
  Item_25126_Name = {Text = "雷娅"},
  Item_25136_Desc = {
    Text = "封装着珍稀材料的礼袋，为执行密境课室的日常试训与周常试训任务的守密人提供额外援助。\n课题等级达到50级后，每提升1级即可获得1份。\n领取时随机获得以下其中一个物品：\n「特批药剂」×1(20%概率)\n「蔷薇金券」×5000(80%概率)"
  },
  Item_25136_Name = {
    Text = "进阶课题礼袋"
  },
  Item_25141_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「弥萨格学生间流传着这样一句话：只要有他在，就没有人会受伤。」"
  },
  Item_25141_Name = {
    Text = "以银钥之名：奥吉尔"
  },
  Item_25141_StoryDesc = {
    Text = "第2期学期课题"
  },
  Item_25142_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「无论是奔赴卡达斯星球的背面，还是深入裂隙中心，她都相信你的判断。」"
  },
  Item_25142_Name = {
    Text = "以银钥之名：拉蒙娜"
  },
  Item_25142_StoryDesc = {
    Text = "第2期学期课题"
  },
  Item_25192_Name = {Text = "校猫"},
  Item_25218_Desc = {
    Text = "它将改写世界的规则。不可直视，不可接触。\n产自弥萨格地底黑池的神秘灵核，能帮助唤醒体提升至难以想象的高度，唤醒体达到60级后可使用。"
  },
  Item_25218_Name = {
    Text = "原初灵核"
  },
  Item_25219_Desc = {
    Text = "它们散落在黑池中，渴望着神圣完整的伟大时刻。\n产自弥萨格地底的神秘碎片，能合成原初灵核。"
  },
  Item_25219_Name = {
    Text = "灵核碎片"
  },
  Item_34698_Desc = {
    Text = "装饰华丽的木匣，内含初阶升格材料。\n后勤处精心准备、悉心搭配的套装，适合那些在短时间内需要一定资源的调查员和守密人。"
  },
  Item_34698_Name = {
    Text = "初阶升格匣子"
  },
  Item_34699_Desc = {
    Text = "可以窥见命运碎片的螺旋视窗。用于兑换命轮。\n黄金、稀土、银芯……与期望的命运相比，再昂贵的材料也变得微不足道。\n使用时可从中选择1个「轮转之相」、往期命轮活动唤醒和当期命轮活动唤醒中的SSR命轮。"
  },
  Item_34699_Name = {
    Text = "命途回溯之芯"
  },
  Item_34700_Desc = {
    Text = "装饰华丽的木匣，内含中阶升格材料。\n后勤处精心准备、悉心搭配的套装，适合那些在短时间内需要一定资源的调查员和守密人。"
  },
  Item_34700_Name = {
    Text = "中阶升格匣子"
  },
  Item_34701_Desc = {
    Text = "有着精致绣花的束口袋，内含高阶补给。\n拿好，它可能有点重。谨记：千万不要让它受到撞击，包括掉到地上。"
  },
  Item_34701_Name = {
    Text = "高阶技能补给"
  },
  Item_34702_Desc = {
    Text = "装饰华丽的木匣，内含高阶升格材料。\n后勤处精心准备、悉心搭配的套装，适合那些在短时间内需要一定资源的调查员和守密人。"
  },
  Item_34702_Name = {
    Text = "高阶升格匣子"
  },
  Item_34703_Desc = {
    Text = "由奇异的材质制成的特殊装置，用于进行唤醒体与命轮的「回溯」。\n它将洗去灵魂的印记，抹除精神的疮疤，它将归还一切于原点，唤回最初的灵知。\n可以为唤醒体或常驻命轮开启「回溯」功能。"
  },
  Item_34703_Name = {
    Text = "时间原点"
  },
  Item_34704_Desc = {
    Text = "有着精致绣花的束口袋，内含初阶补给。 小心，里面的东西可能还保有活性。"
  },
  Item_34704_Name = {
    Text = "初阶技能补给"
  },
  Item_34705_Desc = {
    Text = "有着精致绣花的束口袋，内含中阶补给。\n如果你发现你的袋子在无人的情况下悄悄蠕动，请尽快交还至后勤处。"
  },
  Item_34705_Name = {
    Text = "中阶技能补给"
  },
  Item_34706_Desc = {
    Text = "与灵魂共鸣之物。用于唤醒特定唤醒体。\n或许是它的形状，或许是它的材质本身——这个冰冷之物能够穿透帷幕，将沉睡的精神拉入现实之中。\n使用时可从中选择1个「界域研习」、往期角色活动唤醒和当期角色活动唤醒中的唤醒体。"
  },
  Item_34706_Name = {
    Text = "灵魂回溯之芯"
  },
  Item_34723_Desc = {
    Text = "在「故事的魔法」活动中通关「剧本迷思」或完成活动成就后获得，用于在「魔法剧本商店」中进行交换的道具。\n灵感转瞬即逝，如夜空中飞驰而过的流星。不同的是，你拥有将它永远留下的方法。"
  },
  Item_34723_Name = {
    Text = "飘零的灵感"
  },
  Item_34724_Desc = {
    Text = "逸散在临时片场中的情绪粒子，触碰时仿佛听见了孩子们惬意的笑。\n用于提升守密人在活动玩法「剧本迷思」和特遣纪录「故事的魔法」中的共鸣。\n可在限时活动「故事的魔法」中完成成就奖励获取。"
  },
  Item_34724_Name = {
    Text = "演绎之心"
  },
  Item_34832_Desc = {
    Text = "在活动「故事的魔法」中完成成就获得。\n「弥萨格唤醒体管理处提示：不要给莉莉喂太多东西吃！！就算是守密人也不准再投喂她了！」"
  },
  Item_34832_Name = {
    Text = "以银钥之名：莉莉"
  },
  Item_34832_StoryDesc = {
    Text = "莉莉玩法活动"
  },
  Item_34858_Desc = {
    Text = "属性为死亡抵抗的命轮。"
  },
  Item_34858_Name = {
    Text = "35mm的魔法"
  },
  Item_34858_StoryDesc = {
    Text = "故事中存有魔法，弗朗西斯曾这么告诉莉莉。\n那时她会捧着故事书坐在窗边，初夏的阳光将白大褂烤得微微发烫，散发出温暖柔和的馨香。\n她语调轻缓，娓娓道来，但昨夜长时间精神专注于手术积累了太多疲劳，故事尚未抵达终点，弗朗西斯便沉沉睡去。\n莉莉从未因此责怪母亲，因为母亲倚靠窗沿的疲惫睡颜如此令人安心。\n\n如今胶片代替书本承载了故事与魔法，正如新的胶片取代因孩子们的不慎而曝光破损的胶片，正如新伙伴们的嬉闹取代了过往温暖和疼痛交杂的小憩时光。\n但那些被埋藏的回忆依然如曝光的胶片般，沉睡在某个不为人知的角落，纵使永不见天日，依然熠熠生辉。"
  },
  Item_34908_Desc = {
    Text = "芽孢又做错了什么呢，它们只是想有个家罢了。\n虫蛹和它的芽孢邻居。用于提升血肉界域唤醒体的技能等级。"
  },
  Item_34908_Name = {
    Text = "芽孢聚合物"
  },
  Item_34909_Desc = {
    Text = "他们相约一起杀戮，在海百合盛开的春天。\n尤因他海百合的化石。用于提升深海界域唤醒体的技能等级。"
  },
  Item_34909_Name = {
    Text = "尤因他百合"
  },
  Item_34910_Desc = {
    Text = "在某些平行宇宙里，它拥有毁天灭地的力量。\n来自遥远热带的完美矿晶，用于提升超维界域唤醒体的技能等级。"
  },
  Item_34910_Name = {
    Text = "尤卡坦之星"
  },
  Item_34911_Desc = {
    Text = "扇动的翅膀有助于产生龙卷风，或是花粉过敏。\n成群的水晶蝴蝶。用于提升混沌界域唤醒体的技能等级。"
  },
  Item_34911_Name = {
    Text = "混沌结晶"
  },
  Item_35140_Desc = {
    Text = "用于在「魔法剧本商店」中进行交换的道具。\n灵感转瞬即逝，如夜空中飞驰而过的流星。不同的是，你拥有将它永远留下的方法。\n至少掉落:\n飘零的灵感* {s1}\n有较低概率获得额外的飘零的灵感。"
  },
  Item_35140_Name = {
