  Item_35711_Desc = {
    Text = "一次能亲自决定前进方向的机会。\n限量特供的轮转之书，希望能为执行任务的守密人保驾护航。"
  },
  Item_35711_Name = {
    Text = "特供轮转之书"
  },
  Item_35712_Desc = {
    Text = "没有人能百分之百保证，其中封装的灵识都是自愿被唤醒的。\n限量特供的原质乐园，希望能为执行任务的守密人保驾护航。"
  },
  Item_35712_Name = {
    Text = "特供原质乐园"
  },
  Item_35816_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「当前课题：如何提高守密人外勤任务安全系数。\n课题难度：☆☆☆☆☆」"
  },
  Item_35816_Name = {
    Text = "以银钥之名：朵尔"
  },
  Item_35816_StoryDesc = {
    Text = "第3期学期课题"
  },
  Item_35817_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「无趣！我要战到血流成河！」"
  },
  Item_35817_Name = {
    Text = "以银钥之名：萝坦"
  },
  Item_35817_StoryDesc = {
    Text = "第6期学期课题"
  },
  Item_36018_Desc = {
    Text = "在活动「群星正位」中完成成就获得。\n「草莓果酱司康的恶魔，布朗尼公主，弥萨格食堂推车小蛋糕新的毁灭者——已经降临于此！」"
  },
  Item_36018_Name = {
    Text = "以银钥之名：墨菲"
  },
  Item_36018_StoryDesc = {
    Text = "墨菲玩法活动"
  },
  Item_36782_Desc = {
    Text = "请提供交易账户及密码。\n流通于王国地下市场的交易凭证，守密人可据此购入所需的稀有物资。"
  },
  Item_36782_Name = {
    Text = "密银交易凭证"
  },
  Item_36801_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「奥瑞塔的宝藏」。\n\n玻璃缸。水族箱。宫殿。\n\n称呼它为什么都好，那都是奥瑞塔的朋友们栖居的、没有融蚀和痛苦的小小乐园。"
  },
  Item_36801_Name = {
    Text = "奥瑞塔的宝藏"
  },
  Item_36801_StoryDesc = {
    Text = "玻璃缸。水族箱。宫殿。\n\n称呼它为什么都好，那都是奥瑞塔的朋友们栖居的、没有融蚀和痛苦的小小乐园。"
  },
  Item_36813_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「咆哮的血与沙」。\n\n霞光如血，飞沙扬尘。\n\n无垠沙丘之上，天生的战士毫不犹豫地咬开自己的手腕，将他的血还于天空和大地。"
  },
  Item_36813_Name = {
    Text = "咆哮的血与沙"
  },
  Item_36813_StoryDesc = {
    Text = "霞光如血，飞沙扬尘。\n\n无垠沙丘之上，天生的战士毫不犹豫地咬开自己的手腕，将他的血还于天空和大地。"
  },
  Item_36814_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「最后的誓言」。\n\n骑士曾立誓，他会以这支枪守卫重要之人。此刻它贯穿了主人的胸膛，却只为将危险隔绝于外——这是骑士践行的最后的誓言。"
  },
  Item_36814_Name = {
    Text = "最后的誓言"
  },
  Item_36814_StoryDesc = {
    Text = "骑士曾立誓，他会以这支枪守卫重要之人。此刻它贯穿了主人的胸膛，却只为将危险隔绝于外——这是骑士践行的最后的誓言。"
  },
  Item_36815_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「短暂的永恒」。\n\n机械的人偶拒绝了新生之灵许诺的永恒，核心的电流灼烧她的灵魂。在无力支撑躯体之前，她还有最后一件必须完成的事情——"
  },
  Item_36815_Name = {
    Text = "短暂的永恒"
  },
  Item_36815_StoryDesc = {
    Text = "机械的人偶拒绝了新生之灵许诺的永恒，核心的电流灼烧她的灵魂。在无力支撑躯体之前，她还有最后一件必须完成的事情——"
  },
  Item_36847_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「蚀骨的拥抱」。\n\n血肉消溶于深海，骨骼硬化为珊瑚，她的目光炽热，所拥抱之物是你，所雕刻之物亦是你。\n\n她答应你，要带你一起回家。"
  },
  Item_36847_Name = {
    Text = "蚀骨的拥抱"
  },
  Item_36847_StoryDesc = {
    Text = "血肉消溶于深海，骨骼硬化为珊瑚，她的目光炽热，所拥抱之物是你，所雕刻之物亦是你。\n\n她答应你，要带你一起回家。"
  },
  Item_36848_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「湖畔回眸」。\n\n坎布里安河谷的湖水波光粼粼，清澈见底。\n\n迷宫中的喧嚣忽而远去，享受此刻宁静的只有你和重获自由的少女。"
  },
  Item_36848_Name = {
    Text = "湖畔回眸"
  },
  Item_36848_StoryDesc = {
    Text = "坎布里安河谷的湖水波光粼粼，清澈见底。\n\n迷宫中的喧嚣忽而远去，享受此刻宁静的只有你和重获自由的少女。"
  },
  Item_36849_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「跨越回溯之扉」。\n\n少女已经数不清她经历的轮回，记不明她改变的历史。\n\n这是最后的机会，最后回溯，她的剑贯穿了塔薇的灵核，却只来得及握着那个人的手，一同沦入黑池。"
  },
  Item_36849_Name = {
    Text = "跨越回溯之扉"
  },
  Item_36849_StoryDesc = {
    Text = "少女已经数不清她经历的轮回，记不明她改变的历史。\n\n这是最后的机会，最后回溯，她的剑贯穿了塔薇的灵核，却只来得及握着那个人的手，一同沦入黑池。"
  },
  Item_36850_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「腐烂盛筵」。\n\n欢宴已极，坎布利安的女王大笑着，遥隔狂欢的人群与飞溅的融蚀浆液向你举杯致意。"
  },
  Item_36850_Name = {
    Text = "腐烂盛筵"
  },
  Item_36850_StoryDesc = {
    Text = "欢宴已极，坎布利安的女王大笑着，遥隔狂欢的人群与飞溅的融蚀浆液向你举杯致意。"
  },
  Item_36857_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「神迹降临」。\n\n治愈的神迹降临于被疯狂玷污的圣堂，以甘愿献身者、以无瑕的慈爱者的鲜血为代价。"
  },
  Item_36857_Name = {
    Text = "神迹降临"
  },
  Item_36857_StoryDesc = {
    Text = "治愈的神迹降临于被疯狂玷污的圣堂，以甘愿献身者、以无瑕的慈爱者的鲜血为代价。"
  },
  Item_36858_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「巨人的霸道」。\n\n霸者之道，永不放弃，永不言败。\n\n即便地平线已经吞噬光明，他也要用巨力扛起不熄的太阳。"
  },
  Item_36858_Name = {
    Text = "巨人的霸道"
  },
  Item_36858_StoryDesc = {
    Text = "霸者之道，永不放弃，永不言败。\n\n即便地平线已经吞噬光明，他也要用巨力扛起不熄的太阳。"
  },
  Item_36859_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「全部的她」。\n\n全部的24融为一体，化作星光消散。\n\n她的人格因分割而完整，她的躯体因裂殖而存活。\n\n这世间只有一个24，也是全部的她。"
  },
  Item_36859_Name = {
    Text = "全部的她"
  },
  Item_36859_StoryDesc = {
    Text = "全部的24融为一体，化作星光消散。\n\n她的人格因分割而完整，她的躯体因裂殖而存活。\n\n这世间只有一个24，也是全部的她。"
  },
  Item_36860_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「玫瑰的胜利」。\n\n雍容的玫瑰斩获了她的完全胜利。\n\n她回归了人群中众星捧月的高贵玫瑰，唯有向你投来的目光宣告着与你在歌剧院经历的秘密冒险。"
  },
  Item_36860_Name = {
    Text = "玫瑰的胜利"
  },
  Item_36860_StoryDesc = {
    Text = "雍容的玫瑰斩获了她的完全胜利。\n\n她回归了人群中众星捧月的高贵玫瑰，唯有向你投来的目光宣告着与你在歌剧院经历的秘密冒险。"
  },
  Item_36861_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「灰雾真容」。\n\n微风扬起她的长发，灰雾之海的倒影在刹那间浮现，然后消弭于无形，在你面前的仍是优雅从容的她。但你知道，那不是你的幻觉。"
  },
  Item_36861_Name = {
    Text = "灰雾真容"
  },
  Item_36861_StoryDesc = {
    Text = "微风扬起她的长发，灰雾之海的倒影在刹那间浮现，然后消弭于无形，在你面前的仍是优雅从容的她。但你知道，那不是你的幻觉。"
  },
  Item_36862_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「仲夏之梦」。\n\n那是短暂虚幻的一夕幻梦，轻盈而柔软，未曾留存于胶片，却流淌于每个拍摄者的记忆之中。"
  },
  Item_36862_Name = {
    Text = "仲夏之梦"
  },
  Item_36862_StoryDesc = {
    Text = "那是短暂虚幻的一夕幻梦，轻盈而柔软，未曾留存于胶片，却流淌于每个拍摄者的记忆之中。"
  },
  Item_36863_Desc = {
    Text = "触摸它，然后投身一场新的冒险；\n拥抱它，然后沉入最荒诞的梦境。\n保存未提纯银芯的新装置，用于解锁特遣纪录和意识潜游。"
  },
  Item_36863_Name = {
    Text = "现实起点"
  },
  Item_36889_Desc = {
    Text = "逸散在坎布里安的情绪粒子，触碰时仿佛闻到了红酒和灰烬燃烧的气息。\n用于提升守密人在活动玩法「湖中之城」中的共鸣。\n可在限时活动「燃烧的群宴」中完成成就奖励获取。"
  },
  Item_36889_Name = {
    Text = "享乐之心"
  },
  Item_38702_Desc = {
    Text = "用于在「暗淡之缚」中进行交换的道具。\n散落在伊萨拉乌风中的巨石残骸。\n它们静止不动，庄严地为逝去的都城哀悼。"
  },
  Item_38702_Name = {
    Text = "螺旋遗迹"
  },
  Item_38703_Desc = {
    Text = "用于在「遗迹之守」中进行交换的道具。\n 一圈又一圈碳酸钙组成的梦。为您解开伊萨拉乌之书的秘密。"
  },
  Item_38703_Name = {
    Text = "圆叶菊石"
  },
  Item_38704_Desc = {
    Text = "用于在「脊刺之握」中进行交换的道具。\n脊刺的原材料之一。经由它打磨的脊刺刺入人类胸腔，便可主宰一切。\n意志与情感？不过是生物的脆弱编码罢了。"
  },
  Item_38704_Name = {
    Text = "原生胫骨"
  },
  Item_39313_Desc = {
    Text = "在活动「燃烧的群宴」中商店兑换获得。\n「臣服于我，匍匐于我！还是说，你想再尝尝脊柱被抽离的甜苦呢？」"
  },
