  Item_39462_Name = {
    Text = "螺旋遗迹"
  },
  Item_41327_Name = {
    Text = "提灯教会符号"
  },
  Item_41379_Desc = {
    Text = "属性为伤害强效的命轮。"
  },
  Item_41379_Name = {
    Text = "伊萨拉乌的目光"
  },
  Item_41379_StoryDesc = {
    Text = "第一任王夫来自伊萨拉乌。\n他长着一对伊萨拉乌人特有的眼珠，淡淡的金色，在远空漆黑的夜里闪耀着微弱的光。\n但那光芒随着伊萨拉乌的陷落而消失，旺达从漆黑的泥沼中捞起最后的载体，珍而重之地仔细收藏。\n她与第二、三任王夫相遇于弗兰高地。\n那是一对贪婪的领主双胞胎，旺达曾希望借助他们的力量，重建那失落的湖中之城。\n她受到了欺骗，因此，脊刺深深埋入了他们的骨髓。在麻痹中，旺达取出了那两对卑贱而无礼的眼睛，而后留下它们，作为自己来过的痕迹。\n第四任王夫，旺达记得他叫「约翰」。\n他是个无趣的哑巴，但伺候得她足够舒心。更让她开心的是，「约翰」也有双淡金色的眼睛，和她的几乎一模一样。\n\n「把王夫的眼睛剐出来吧。」\n「谨遵您的希望……但，王夫是做错了什么吗？」\n旺达摇晃着杯中浑浊的水，感受毒素在舌尖徜徉。真是个蠢材，连下毒都做得如此粗劣。\n看着「约翰」爬满融蚀的身体，她想起了还在遥远星外时，目送着她离开了故乡的一双双死寂之眸。\n和「约翰」此时的眼睛如出一辙。\n「……就说他，缺少幽默感吧。」"
  },
  Item_43605_Desc = {
    Text = "期间限定的手忙脚乱，为了收纳这些无序增殖的凝晶，研究员加了好几天的班。\n不定期迎来爆发的的拟态凝晶，限量供应，为执行任务的守密人提供援助。"
  },
  Item_43605_Name = {
    Text = "拟态爆发之夜"
  },
  Item_44174_Desc = {
    Text = "逸散在圣堂内的情绪粒子，触碰时仿佛能听到谁的祷告与低语。\n用于提升守密人在活动玩法「圣堂之路」和特遣纪录「血的颜色」中的共鸣。\n可在限时活动「灵魂的牧人」中完成成就奖励获取。"
  },
  Item_44174_Name = {
    Text = "忏悔之心"
  },
  Item_44265_Desc = {
    Text = "在活动「灵魂的牧人」中通过「圣堂之路」、「市民的善意」和「成就奖励」获取，用于在「义卖现场」中购买商品。\n\n将你的爱心换成义卖券，将你的钱财换成他人的未来。\n互帮互助才是父神期许的道路。"
  },
  Item_44265_Name = {Text = "义卖券"},
  Item_44481_Desc = {
    Text = "在活动「灵魂的牧人」中完成成就获得。\n「父神能看见每个人灵魂的辉光……当然也包括你的，守密人。」"
  },
  Item_44481_Name = {
    Text = "以银钥之名：萨尔瓦多"
  },
  Item_44481_StoryDesc = {
    Text = "萨尔瓦多玩法活动"
  },
  Item_44482_Desc = {
    Text = "在活动「雨镇幽影」中完成成就获得。\n「世界上可没有自动解题机器哦，我可爱的小客人。想要解开谜题的话，为什么不先问问你身边的搭档呢？」"
  },
  Item_44482_Name = {
    Text = "以银钥之名：达芙黛尔"
  },
  Item_44482_StoryDesc = {
    Text = "达芙黛尔玩法活动"
  },
  Item_44483_Desc = {
    Text = "在活动「神王复苏」中完成成就获得。\n「放弃吧，下午四点以后，余将不会阅读任何一份奏章——就算是守密人呈上的，也不看。」"
  },
  Item_44483_Name = {
    Text = "以银钥之名：图鲁"
  },
  Item_44483_StoryDesc = {
    Text = "图鲁玩法活动"
  },
  Item_44576_Desc = {
    Text = "后勤部向完成「调查行动」的守密人发放了特别许可，在每次完成调查行动后，守密人都可以为下一次的出发购置一批特别的珍贵银芯制品。\n数量有限，愿银钥指引我们。"
  },
