  Item_45297_Name = {
    Text = "银鳕鱼的决心"
  },
  Item_45297_StoryDesc = {
    Text = "<Bold:银鳕鱼24>\n每次路过那家炸鱼餐厅，我都忍不住想要尖叫。\n为什么受伤的总是银鳕鱼呢？我们甚至不是真正的鳕鱼！\n肉质紧实、味道鲜美难道也是我们的错吗？\n\n<Bold:猫咪24>\n吸溜吸溜……喵，喵喵（赞成）！\n\n<Bold:银鳕鱼24>\n在雷欧王国，每分钟就有一条银鳕鱼死于非命，成为人类的盘中餐。\n是的，就在我们说话的间隙，已经有10只银鳕鱼壮烈牺牲了。\n整整10只！父神在上，你听到它们的惨叫声了吗？\n\n<Bold:猫咪24>\n呃……喵？喵喵喵，喵喵（哪里）？\n\n<Bold:银鳕鱼24>\n只是个比喻罢了，傻瓜。你虽然蠢了点，却有一颗金子般的心，能够战胜猫的兽欲和短视。\n听着，接下来我有个计划，需要你和我一起实施……\n\n——节选自《大约翰炸鱼餐厅爆炸事件·案卷综述：证词B-03》。由于该时期伯利恒精神病院人满为患，嫌犯被拒收，在伦蒂尼恩塔内关押23天后释放。"
  },
  Item_45298_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「春天的献诗」。\n\n收下这首，春天献给花园的诗吧\n在我们荒寂的生命里，玫瑰正殷红地栖居。"
  },
  Item_45298_Name = {
    Text = "春天的献诗"
  },
  Item_45298_StoryDesc = {
    Text = "收下这首，春天献给花园的诗吧\n在我们荒寂的生命里，玫瑰正殷红地栖居。"
  },
  Item_45299_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「黑天鹅的舞步」。\n\n盈步。跳剪。旋转。在舞曲的高潮处，纵身跃入火焰。\n燃烧吧。燃烧，是舞蹈唯一的答案。"
  },
  Item_45299_Name = {
    Text = "黑天鹅的舞步"
  },
  Item_45299_StoryDesc = {
    Text = "盈步。跳剪。旋转。在舞曲的高潮处，纵身跃入火焰。\n燃烧吧。燃烧，是舞蹈唯一的答案。"
  },
  Item_45300_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「海之祭」。\n\n利莫里亚的主祭，从不期待海洋的回应。\n\n她将一切献予海洋，这与海洋无关。"
  },
  Item_45300_Name = {Text = "海之祭"},
  Item_45300_StoryDesc = {
    Text = "利莫里亚的主祭，从不期待海洋的回应。\n\n她将一切献予海洋，这与海洋无关。"
  },
  Item_45301_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「一声枪响」。\n\n「砰——」\n一声划破长空的枪鸣，贯穿阴谋幕后主使者的心脏。\n\n死亡不是生命的结束，只是谜题反转的高点。"
  },
  Item_45301_Name = {
    Text = "一声枪响"
  },
  Item_45301_StoryDesc = {
    Text = "「砰——」\n一声划破长空的枪鸣，贯穿阴谋幕后主使者的心脏。\n\n死亡不是生命的结束，只是谜题反转的高点。"
  },
  Item_45302_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「群山的觉悟」。\n\n极寒冰川的群山吞噬了英武的战士和癫狂的野兽，以洁白的积雪掩盖故事的残骸。\n但在来年开春之后，微弱的生机终将跨越风雪。群山早已做好觉悟。"
  },
  Item_45302_Name = {
    Text = "群山的觉悟"
  },
  Item_45302_StoryDesc = {
    Text = "极寒冰川的群山吞噬了英武的战士和癫狂的野兽，以洁白的积雪掩盖故事的残骸。\n但在来年开春之后，微弱的生机终将跨越风雪。群山早已做好觉悟。"
  },
  Item_46606_Desc = {
