  Item_47303_Desc = {
    Text = "用于在「人格解析」中进行交换的道具。\n\n并非所有的记忆都忠诚可靠。\n告诉你一个秘密：β是个彻头彻尾的骗子，它在撒谎。\n\n至少掉落{s1}个"
  },
  Item_47303_Name = {
    Text = "记忆拼图α"
  },
  Item_47304_Desc = {
    Text = "逸散在蜡像馆的情绪粒子，触碰时仿佛看见眼泪、红色丝带和雾中的伦蒂尼恩。\n用于提升守密人在活动玩法「记忆编码」和特遣纪录「宁静的裂殖」中的共鸣。\n可在限时活动「多重疗愈」中完成成就奖励获取。"
  },
  Item_47304_Name = {
    Text = "分裂之心"
  },
  Item_47519_Desc = {
    Text = "属性为暴击伤害的命轮。"
  },
  Item_47519_Name = {
    Text = "深海的呼唤"
  },
  Item_47519_StoryDesc = {
    Text = "王座的幻梦中，王聆听神明的启示：\n利莫里亚的风暴将平息。利莫里亚的深渊将消逝。\n以梦境为庭，以星辰为烛。王将庇护他良善的子民，带来神的国度。\n\n吾主之信徒，敞开你的心怀，接纳吾主。\n在遥远的黯淡深渊，古老的伟大灵魂沉眠，倾听诸神的低语。\n祂的意志如星辰之网交织，祂在永恒的虚无中候汝入梦。\n\n风暴静伏，水波不兴；\n地震平息，大地安宁。\n灾祸在祂的宁静梦境中化为虚无，\n子民在祂的庇护下安然无恙。\n愿我们的歌声穿越深海，愿祂赐予我们免受灾难的神谕，\n领我们前往无尽的安宁与极乐之境。\n我们的信念与祂同在，直至星辰消亡，直至时间尽头。\n"
  },
  Item_47520_Desc = {
    Text = "属性为死亡抵抗的命轮。"
  },
  Item_47520_Name = {
    Text = "往昔的花与诗"
  },
  Item_47520_StoryDesc = {
    Text = "自从她的诗篇风靡西岱，好友便更加殷勤地为她送来鲜花。\n「用不了那么多花，柯蕾特，这实在是太浪费了。」\n今天拿来的玫瑰与昨天、前天、大前天的堆在一起，旧的花朵甚至开始因过于拥挤而腐烂。\n「怎么会浪费呢，我们从前说好的，用我的花换你的诗。」\n柯蕾特摇了摇头，有些讪讪地望着她。\n是啊，用花换诗，这是她们的约定。她能感觉到，某些事情似乎变了，但她不愿意再往下想。\n她继续写诗，不分昼夜地写诗。从前她的诗会自然从笔端流淌而出，如今，她的笔竟然有些滞涩起来。\n好友送来鲜花时的眼神让她越来越陌生，她看着满屋匆匆烂掉的玫瑰，闻着那些凋零的腐臭，由衷感到惋惜与惆怅。\n可她从来没有停下过手中的笔。\n「我会靠这块土地上长出的花，给我们买衣服，买吃的。总有一天，就连上面那栋楼房里的房子，我也要买下来！」\n「每个人都有自己生来就要做的事。我生来就是要为这个花园、为那间房子努力……而你，你生来就是要写诗的。」\n「我相信你，奥尔拉！从今天开始，你的所有诗我都会帮你好好珍藏起来。以后，我就用我的花，来换你的诗吧！」\n花与诗，是她们给对方的承诺。\n她永远不会停下手中的笔。"
  },
  Item_47521_Desc = {
    Text = "属性为狂气回充等级的命轮。"
  },
  Item_47521_Name = {
    Text = "灼热的吻别"
  },
  Item_47521_StoryDesc = {
    Text = "沐浴黑血而重获新生的少女，在沙漠萦绕千年的风沙之中，托举起丰穰母树神圣的血之种。\n\n「只要这颗种子存活于世，树的血脉就不会断绝。」\n\n自那之后又是千年，这颗种子随着树的后裔见证了荣辱兴衰，体验了流离失所，经历了不知所踪，消亡而后重生，直到滔滔河水化为黏稠的黑血，它也完成了最后一次传承。\n那是个炽热滚烫而纠缠不休的吻，饱含尚未满足的渴望和未及启齿的离愁别绪，与温暖的心跳一起将新的传承者重重包裹。\n那玛瑙般的色彩、白玉般的光泽，将随着生命的搏动一起跨越黑色的终末。\n然后新世界的第一颗树种，将在她的祝福下拔地而起，化作覆盖天地的巨木。"
  },
  Item_48014_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「脑中之音」。\n\n双手交握的那一刻，你们从对方的眼里看到了迷茫与困惑。\n残缺的声部在此交汇，皆因你们早已遗落了过往。\n沉默的乐章即将谱写，皆因你们决心坠入未来。"
  },
  Item_48014_Name = {
    Text = "未至遗忘的黎明"
  },
  Item_48014_StoryDesc = {
    Text = "双手交握的那一刻，你们从对方的眼里看到了迷茫与困惑。\n残缺的声部在此交汇，皆因你们早已遗落了过往。\n沉默的乐章即将谱写，皆因你们决心坠入未来。"
  },
  Item_48113_Desc = {
    Text = "不小心人格分裂了怎么办？别慌，弥萨格早有准备！\n用以保证守密人身心健康的良方，在「多重疗愈」期间限时供应。"
  },
  Item_48113_Name = {
    Text = "解离急性疗程"
  },
  Item_48114_Desc = {
    Text = "一个疗程没效果怎么办？那就再来一个疗程！\n用以保证守密人身心健康的良方，在「多重疗愈」期间限时供应。"
  },
  Item_48114_Name = {
    Text = "解离巩固疗程"
  },
  Item_48115_Desc = {
    Text = "永远不要质疑父神、《几何原本》和医生的处方。\n用以保证守密人身心健康的良方，在「多重疗愈」期间限时供应。"
  },
  Item_48115_Name = {
    Text = "解离康复疗程"
  },
  Item_48594_Desc = {
    Text = "能够使守密人的细胞活性增强，在「每日试训」中获取双倍无垢之芯、银芯和守密人经验，并且「相位对弈」可使用所有卡牌。仅在本期课题有效。\n超量激活突触活跃的副作用未知，限时限量，不可过度摄入。"
  },
  Item_48594_Name = {
    Text = "突触活性酶片"
  },
  Item_48700_Desc = {
    Text = "用于在「欲孽滋生」中进行交换的道具。\n\n一枚小小的，圆圆的种子。\n终将萌发，扎根，成长为遮天蔽日的葳蕤大树。"
  },
  Item_48700_Name = {
    Text = "丰穰种核"
  },
  Item_48828_Desc = {
    Text = "属性为死亡抵抗的命轮。"
  },
  Item_48828_Name = {
    Text = "极夜与破晓"
  },
  Item_48828_StoryDesc = {
    Text = "他们在黑暗的河流中划行，苍白，沉默，疲惫不堪。\n朦胧的雾气伸长触手，将他们拉入黑暗，徘徊在没有尽头的永夜中。\n\n后来，他们看到了一束光。\n那是来自遥远岸边的曦光，它忽明忽灭，却足以照亮暗淡的灵魂。\n于是他们循着光，笨拙地划出黑暗，来到破晓的黎明面前。\n也来到你们面前。\n\n或许这只是一次短暂的相逢，但他们用力挥舞双手，竭力呼喊。\n所有人都沐浴在神圣的曦光下，所有人都在笑着。\n他们说——\n愿每一个相聚的瞬间都如节日般珍贵。\n愿真诚的心永不停止跳动。\n愿银钥指引前行。"
  },
  Item_48924_Desc = {
    Text = "逸散在勒姆瓦希沙漠中的情绪粒子。触碰时仿佛听见了暧昧的低吟。\n用于提升守密人在调查事件「欲河」中的共鸣。"
  },
  Item_48924_Name = {
    Text = "爱怜之心"
  },
  Item_49204_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「唯一的种子」。\n\n她将唯一的种子，渡让至你的口舌。\n血脉的力量，传承的信仰，超越的勇气，还有深沉的爱意……她将她的一切托付给你。"
  },
  Item_49204_Name = {
    Text = "唯一的种子"
  },
  Item_49204_StoryDesc = {
    Text = "她将唯一的种子，渡让至你的口舌。\n血脉的力量，传承的信仰，超越的勇气，还有深沉的爱意……她将她的一切托付给你。"
  },
  Item_49263_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「吧唧吧唧……小蛋糕好吃……」"
  },
  Item_49263_Name = {
    Text = "以银钥之名：守密人"
  },
