  },
  Item_49264_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n根据守密人性别不同而不同"
  },
  Item_49264_Name = {
    Text = "以银钥之名：守密人"
  },
  Item_49264_StoryDesc = {
    Text = "第5期学期课题"
  },
  Item_49265_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「嘶……好像长蛀牙了？」"
  },
  Item_49265_Name = {
    Text = "以银钥之名：守密人"
  },
  Item_49265_StoryDesc = {
    Text = "第5期学期课题"
  },
  Item_49266_Name = {
    Text = "相位通讯：守密人·大事不妙"
  },
  Item_49266_StoryDesc = {Text = "初始"},
  Item_49271_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「不允许你们靠近守密人半步……！」"
  },
  Item_49271_Name = {
    Text = "以银钥之名：环行·拉蒙娜"
  },
  Item_49271_StoryDesc = {
    Text = "第5期学期课题"
  },
  Item_49318_Desc = {
    Text = "后勤部向完成「调查行动」的守密人发放了特别许可，在每次完成调查行动后，守密人都可以为下一次的出发购置一批特别的珍贵银芯制品。\n数量有限，愿银钥指引我们。"
  },
  Item_49318_Name = {
    Text = "调查历程特典Ⅶ"
  },
  Item_49464_Desc = {
    Text = "「把五支羽毛笔绑在一起，就可以将密契抄写速度提升至五倍。守密人也来试试吧！」\n某个可怜的唤醒体因使用小窍门逃避罚抄而被茜尔维娅的粉笔正中脑门。"
  },
  Item_49464_Name = {
    Text = "密契摘录集"
  },
  Item_49465_Desc = {
    Text = "「注意关注圣河负载能力和自我调节限度，并探明含沙量异常的原因。」\n后勤部提供给守密人进行圣河地理勘测的特殊补给。"
  },
  Item_49465_Name = {
    Text = "水文监测支援"
  },
  Item_49466_Desc = {
    Text = "「秘密一定就在地下，在母树根系覆盖的最深处……那里绝对藏着什么不可告人的……」\n后勤部提供给守密人进行圣河地理勘测的特殊补给。"
  },
  Item_49466_Name = {
    Text = "地层钻探支援"
  },
  Item_49467_Desc = {
    Text = "「自从A.F.225年后，我们就再未观测到圣河源头的所在。」\n后勤部提供给守密人进行圣河地理勘测的特殊补给。"
  },
  Item_49467_Name = {
    Text = "流域勘定支援"
  },
  Item_49486_Desc = {
    Text = "在活动「欲海翻波」中完成成就获得。\n「来吧，与我诞下子嗣，同享永恒的欢愉……」"
  },
  Item_49486_Name = {
    Text = "以银钥之名：泰旖丝"
  },
  Item_49486_StoryDesc = {
    Text = "泰旖丝玩法活动"
  },
