  },
  Item_52177_Name = {
    Text = "祀者之髓"
  },
  Item_52178_Desc = {
    Text = "用于在「莹泪祭坛」中进行交换的道具。\n献上你的泪吧，祭祀之人。所有的苦难，神国将偿还。\n\n至少掉落{s1}个"
  },
  Item_52178_Name = {
    Text = "祀者之泪"
  },
  Item_52304_Desc = {
    Text = "「限定每周一次，过量供应可能会对健康造成不良影响，我们必须对你的安全负责哦。」\n医务室里，茜尔维娅困扰地捋了捋散落的发梢。"
  },
  Item_52304_Name = {
    Text = "周常流明供给"
  },
  Item_52305_Desc = {
    Text = "那沉眠于至暗至深之处的王的诞生将扭曲整片神识之海。\n用以抵抗异梦侵蚀的仪式，在「沉渊之祀」期间限时供应。"
  },
  Item_52305_Name = {
    Text = "神国王诞密仪"
  },
  Item_52306_Desc = {
    Text = "深海泛滥的潮涌冲击意识的边界。\n用以抵抗异梦侵蚀的仪式，在「沉渊之祀」期间限时供应。"
  },
  Item_52306_Name = {
    Text = "潮蚀防卫密仪"
  },
  Item_52307_Desc = {
    Text = "异梦视界中的天灾亦会通过精神共振干扰守密人的灵智。\n用以抵抗异梦侵蚀的仪式，在「沉渊之祀」期间限时供应。"
  },
  Item_52307_Name = {
    Text = "天灾戒备密仪"
  },
  Item_53730_Desc = {
    Text = "「欢迎回家。」"
  },
  Item_53730_Name = {
    Text = "返校邀约"
  },
  Item_53746_Desc = {
    Text = "用于在「金红庆典」中进行交换的道具。\n\n索蕾尔夫人收藏的羽扇。有人相信它能预测股票走势。"
  },
  Item_53746_Name = {
    Text = "通灵鸟羽扇"
  },
  Item_53766_Desc = {
    Text = "在活动「与蔷薇书」中完成成就获得。\n「这就是权力的香味吗？我甚感满意。」"
  },
  Item_53766_Name = {
    Text = "以银钥之名：索蕾尔"
  },
  Item_53766_StoryDesc = {
    Text = "索蕾尔玩法活动"
  },
  Item_53767_Desc = {
    Text = "属性为暴击率的命轮。"
  },
  Item_53767_Name = {
    Text = "百万蒙宠之眼"
  },
  Item_53767_StoryDesc = {
    Text = "祂伏行于无垠的混沌中，偶尔才对匍匐世间的众生投去一缕瞥视。\n\n那些尚可入眼的，譬如索蕾尔，祂向他们提供难以被拒绝的「契约条款」。\n那些粗陋乏味的，祂褪去他们的肉身，留下一只再也无法落泪的眼睛。\n这些眼睛又被唤作「蒙宠者」。\n\n它们在洞穴中忽明忽暗，既满怀希望，又充满绝望，等待祂的召唤。\n然而一千年过去，一万年过去，蒙宠者继续被遗忘在黑暗的角落。\n\n「那……你们一定是因为某种理由才被留下吧。你们的使命是什么？」\n「我们在等待。」\n「等待什么？」\n「等待……就只是等待而已。」\n「会感到痛苦吗？」\n「恰恰相反。对大人的爱充盈我们全身。因为这是我们唯一能做的事。」\n「只有理解这一点，才能成为真正的信徒。」"
  },
  Item_53871_Desc = {
