  },
  Item_53924_Desc = {
    Text = "用于在「金红庆典」中进行交换的道具。\n\n索蕾尔夫人收藏的羽扇。有人相信它能预测股票走势。\n\n至少掉落{s1}个"
  },
  Item_53924_Name = {
    Text = "通灵鸟羽扇"
  },
  Item_54015_Desc = {
    Text = "鳞翅目正死于孤独、爱与绝望。\n随机掉落有机形态密契套装部件。"
  },
  Item_54015_Name = {
    Text = "有机形态"
  },
  Item_54016_Desc = {
    Text = "旋转，然后遗忘——这是她生命的全部。\n随机掉落36室之环密契套装部件。"
  },
  Item_54016_Name = {
    Text = "36室之环"
  },
  Item_54017_Desc = {
    Text = "必然的，偶然的。\n有限的，无限的。\n随机掉落二律背反密契套装部件。"
  },
  Item_54017_Name = {
    Text = "二律背反"
  },
  Item_54018_Desc = {
    Text = "一千年前，五分钟等于四十盎司细沙。\n随机掉落入药之梦密契套装部件。"
  },
  Item_54018_Name = {
    Text = "入药之梦"
  },
  Item_54032_Desc = {
    Text = "某位位高权重之人的葬礼上演奏的弥撒曲，表达了生者对亡者的哀悼和缅怀，同时坚信死亡不是终结，而是通往永生的开始。\n在「与蔷薇书」期间限时供应。"
  },
  Item_54032_Name = {
    Text = "圣祭悼亡弥撒"
  },
  Item_54033_Desc = {
    Text = "某位位高权重之人的葬礼上演奏的弥撒曲，她的荣光与铭旌永在。\n在「与蔷薇书」期间限时供应。"
  },
  Item_54033_Name = {
    Text = "铭旌赞美弥撒"
  },
  Item_54034_Desc = {
    Text = "某位位高权重之人的葬礼上演奏的弥撒曲，安慰已故的灵魂，并祈求它们得到安息。\n在「与蔷薇书」期间限时供应。"
  },
  Item_54034_Name = {
    Text = "受祝安魂弥撒"
  },
  Item_54104_Desc = {
    Text = "获得唤醒体「哈姆林」后解锁"
  },
  Item_54104_Name = {Text = "哈姆林"},
  Item_54105_Desc = {
    Text = "伴随着持有者卡牌的连续打出爆发性提高战斗能力，额外的手牌上限和银钥积攒带来灵活的战术选择。"
  },
  Item_54105_Name = {
    Text = "隐世的转轮"
  },
  Item_54105_StoryDesc = {
    Text = "当一个人能够知晓全部的过去与未来，等待他的不是全知的喜悦，而是无尽的悲悯与绝望。\n她的双眼能看到万事万物背后的丝线，线的这一头连接过去，线的那一头连接未来。\n那丝线被人们称为命运。\n她是如何看待那一个个跟随在她身边的人呢？\n人们善良仁爱，人们傲慢多疑。\n但那些人的命运与人类的命运都在每次见面的开始就已经注定。\n她必定是喜爱他们的，否则何以一次次伸出援手、给予火种。\n她必定是期许他们的，否则何以在毁灭中坚定地走入轮回的阴影。\n因喜爱，她长怀悲伤。\n因期许，她屡屡失望。\n她深陷在黑色的泥沼，于无数的黑色丝线中不断梳理着，不厌其烦。\n命运的轮盘一次次回转。\n她看到贪婪的火焰席卷苍穹。\n她看到盲愚的偏执走向自戕。\n她看到痴狂的妄念加速毁灭。\n无序的混沌总会姗姗而来。\n希望与绝望徒劳地轮转，永无止境。\n直到她在黑暗之中看到一瞬的星光。\n那光微弱，但她已在黑暗中太久。\n直视的那一刻，竟然流下眼泪。\n"
  },
  Item_54106_Name = {Text = "塔薇"},
  Item_54107_Name = {Text = "哈姆林"},
  Item_54108_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得塔薇时转换获得，用于激活塔薇的启灵。"
  },
  Item_54108_Name = {
    Text = "残片·塔薇"
  },
  Item_54108_StoryDesc = {
    Text = "重复获得塔薇时转换获得，用于激活塔薇的启灵。"
  },
  Item_54109_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得血链·希洛时转换获得，用于激活血链·希洛的启灵。"
  },
