    Text = "重复获得血链·希洛时转换获得，用于激活血链·希洛的启灵。"
  },
  Item_54110_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得哈姆林时转换获得，用于激活哈姆林的启灵。"
  },
