  },
  Item_54578_Desc = {
    Text = "获得守密人经验时，额外获得20%的守密人经验。多个效果时取最高值，不可叠加。\n\n据《源液的精神影响报告》，参与源液提取工作的个体，会在工作结束后表现出一定程度的精力、智力等方面的加强。提取时间越长，提取的源液量越多，效果越明显。\n即使只是逸散的颗粒，源液蕴含的力量依旧不容小觑。"
  },
  Item_54578_Name = {
    Text = "至高礼赞·Ⅱ"
  },
  Item_54579_Desc = {
    Text = "极少数守密人才能拥有的身份标识。\n源液提取时，会有微小的颗粒四散飞舞。不知为何，它们格外青睐金属物件，使守密人佩戴的身份标识染上柔和的银白。\n据说这样的印记具有特殊功效。"
  },
  Item_54579_Name = {
    Text = "银白之矩"
  },
  Item_54579_StoryDesc = {
    Text = "累计充值头像框"
  },
  Item_54580_Desc = {
    Text = "获得守密人经验时，额外获得30%的守密人经验。多个效果时取最高值，不可叠加。\n\n据《源液的精神影响报告》，参与源液提取工作的个体，会在工作结束后表现出一定程度的精力、智力等方面的加强。提取时间越长，提取的源液量越多，效果越明显。\n即使只是逸散的颗粒，源液蕴含的力量依旧不容小觑。"
  },
  Item_54580_Name = {
    Text = "至高礼赞·Ⅲ"
  },
  Item_54581_Desc = {
    Text = "获得守密人经验时，额外获得10%的守密人经验。多个效果时取最高值，不可叠加。\n\n据《源液的精神影响报告》，参与源液提取工作的个体，会在工作结束后表现出一定程度的精力、智力等方面的加强。提取时间越长，提取的源液量越多，效果越明显。\n即使只是逸散的颗粒，源液蕴含的力量依旧不容小觑。"
  },
  Item_54581_Name = {
    Text = "至高礼赞·Ⅰ"
  },
  Item_54582_Desc = {
    Text = "守密人的身份标识，低调而且易于隐藏。"
