  Item_55305_Name = {
    Text = "惆怅的诗文"
  },
  Item_55471_Desc = {
    Text = "需要念诵诗文才会开启的神秘匣子。\n向它描述花的梦，它会赠你一束蔷薇。\n在「在春天凋零以前」期间限时供应。"
  },
  Item_55471_Name = {
    Text = "花与诗的梦"
  },
  Item_55472_Desc = {
    Text = "需要念诵诗文才会开启的神秘匣子。\n当你的意象恰到好处，它会让你看到真实。\n在「在春天凋零以前」期间限时供应。"
  },
  Item_55472_Name = {
    Text = "意与诗的梦"
  },
  Item_55473_Desc = {
    Text = "需要念诵诗文才会开启的神秘匣子。\n向它描述你的过去，它会赠你一抹回忆。\n在「在春天凋零以前」期间限时供应。"
  },
  Item_55473_Name = {
    Text = "心与诗的梦"
  },
  Item_55891_Desc = {
    Text = "祂在长梦中赐予灵性丰沛之人神启：禁忌的学识是虚荣者的诅咒，无知是赠予愚者的恩赐。\n在「神王复苏」期间限时供应。"
  },
  Item_55891_Name = {
    Text = "倦怠梦魇神像"
  },
  Item_55892_Desc = {
    Text = "祂在长梦中赐予灵性丰沛之人神启：神明从未遗留旨意，祷告和祈愿皆为徒劳。\n在「神王复苏」期间限时供应。"
  },
  Item_55892_Name = {
    Text = "慵懒梦魇神像"
  },
  Item_55893_Desc = {
    Text = "祂在长梦中赐予灵性丰沛之人神启：祂自群星而来，祂的国度终将升起。\n在「神王复苏」期间限时供应。"
  },
  Item_55893_Name = {
    Text = "谵妄梦魇神像"
  },
  Item_55894_Desc = {
    Text = "不小心人格分裂了怎么办？别慌，弥萨格早有准备！\n用以保证守密人身心健康的良方，在「多重疗愈」期间限时供应。"
  },
  Item_55894_Name = {
    Text = "解离急性疗程"
  },
  Item_55895_Desc = {
    Text = "一个疗程没效果怎么办？那就再来一个疗程！\n用以保证守密人身心健康的良方，在「多重疗愈」期间限时供应。"
  },
  Item_55895_Name = {
    Text = "解离巩固疗程"
  },
  Item_55896_Desc = {
    Text = "永远不要质疑父神、《几何原本》和医生的处方。\n用以保证守密人身心健康的良方，在「多重疗愈」期间限时供应。"
  },
  Item_55896_Name = {
    Text = "解离康复疗程"
  },
  Item_55897_Desc = {
    Text = "受苦难的灵魂啊，你将被嘉奖，仁爱的主教要代父神为你降下赐福。\n在「灵魂的牧人·复刻」期间限时供应。"
  },
  Item_55897_Name = {
    Text = "弥撒后的赐福"
  },
  Item_55898_Desc = {
    Text = "受苦难的灵魂啊，万不可失去希望，仁爱的主教会为你向父神献上祷告。\n在「灵魂的牧人·复刻」期间限时供应。"
  },
  Item_55898_Name = {
    Text = "弥撒中的祈祷"
  },
  Item_55899_Desc = {
    Text = "受苦难的灵魂啊，不需要迷茫，仁爱的主教会为你指引方向。\n在「灵魂的牧人·复刻」期间限时供应。"
  },
  Item_55899_Name = {
    Text = "弥撒前的指引"
  },
  Item_55900_Desc = {
    Text = "你听到无数的宇宙中有无数声呼喊，他们在呼唤你的姓名。\n你握紧双手，大声回应。\n在「万象门扉」期间限时供应。"
  },
  Item_55900_Name = {
    Text = "回声门扉"
  },
  Item_55901_Desc = {
    Text = "虚幻的门扉向你而来，无数个宇宙破碎又重启。\n门扉的光芒闪烁，你知道它选择了你，它将一切交给了你。\n在「万象门扉」期间限时供应。"
  },
  Item_55901_Name = {
    Text = "命定门扉"
  },
  Item_55902_Desc = {
    Text = "你看见无数的宇宙中有无数的人们，他们都和你有关。\n无数双手伸向你，他们前仆后继，将你高高托举。\n在「万象门扉」期间限时供应。"
  },
  Item_55902_Name = {
    Text = "幻象门扉"
  },
  Item_55904_Desc = {
    Text = "交响乐曲的最终篇章，乐曲的主题在此定论，请欣赏充满希望的凯旋颂歌。\n在「无形交响」期间限时供应。"
  },
  Item_55904_Name = {
    Text = "回旋曲乐谱"
  },
  Item_55905_Desc = {
    Text = "在艾尔沃斯山顶新生的蒲公英的种子，从冻土中长出的小小野草散发着勃勃生机。\n在「雪山消融之时」期间限时供应。"
  },
  Item_55905_Name = {
    Text = "雪山蒲公英种子"
  },
  Item_55906_Desc = {
    Text = "在艾尔沃斯山顶新生的常青树的种子，坚韧的树苗终会越过风霜雨雪，长成参天的巨木。\n在「雪山消融之时」期间限时供应。"
  },
  Item_55906_Name = {
    Text = "雪山常青树种子"
  },
  Item_55907_Desc = {
    Text = "在艾尔沃斯山顶新生的洁白花朵的种子，冰与雪作它的枝与叶，严寒也不能催折它的芬芳。\n在「雪山消融之时」期间限时供应。"
  },
  Item_55907_Name = {
    Text = "雪山银霜花种子"
  },
  Item_55908_Desc = {
    Text = "交响乐曲的开篇，戏剧性的核心在此展现，请欣赏截然相反的主题彼此拉扯较量。\n在「无形交响」期间限时供应。"
  },
  Item_55908_Name = {
    Text = "奏鸣曲乐谱"
  },
  Item_55910_Desc = {
    Text = "戴上贝雷帽的一刻，侦探的眼神也锐利了起来，无人敢质疑你的专业身份。\n在「名侦探手册」期间限时供应。"
  },
  Item_55910_Name = {
    Text = "侦探贝雷帽装束"
  },
  Item_55911_Desc = {
    Text = "穿上风衣就会拥有背后音乐响起的气场，让风吹动你的衣摆，摆出你帅气的推理姿势吧！\n在「名侦探手册」期间限时供应。"
  },
  Item_55911_Name = {
    Text = "侦探风衣装束"
  },
  Item_55912_Desc = {
    Text = "刻板印象中的侦探必备饰品，请在沉思时使用，哪怕是空的也比叼棒棒糖帅气。\n在「名侦探手册」期间限时供应。"
  },
  Item_55912_Name = {
    Text = "侦探烟斗装束"
  },
  Item_55914_Desc = {
    Text = "疼痛即是疼爱，在感受到女王的爱时，记得要大声呼喊女王的尊名。\n在「燃烧的群宴」期间限时供应。"
  },
  Item_55914_Name = {
    Text = "鞭笞的宠爱"
  },
  Item_55915_Desc = {
    Text = "低下你的头颅，匍匐于女王的脚下吧，你将成为女王光荣的座椅与脚踏。\n在「燃烧的群宴」期间限时供应。"
  },
  Item_55915_Name = {
    Text = "践踏的宠爱"
  },
  Item_55916_Desc = {
    Text = "接受女王的考验，展示你的忠诚吧，你只需要服从。\n当女王的脸上露出笑容，你会获得她身边荣耀的位置。\n在「燃烧的群宴」期间限时供应。"
  },
  Item_55916_Name = {
    Text = "命令的宠爱"
  },
  Item_55917_Desc = {
    Text = "从母树上取下的形似孕妇的树瘤，能够感受到其中孕育般蓬勃而无穷的活力，仔细听，那是母亲的呼唤。\n在「欲海翻波·复刻」期间限时供应。"
  },
  Item_55917_Name = {
    Text = "慈母母树畸瘤"
  },
  Item_55918_Desc = {
    Text = "从母树上取下的形似少女的树瘤，能够感受到其中纤细而柔和的活力，仔细听，那是青涩的邀请。\n在「欲海翻波·复刻」期间限时供应。"
  },
  Item_55918_Name = {
    Text = "少女母树畸瘤"
  },
  Item_55919_Desc = {
    Text = "从母树上取下的形似婴儿的树瘤，能够感受到其中生命诞生般的活力，仔细听，那是新生的啼哭。\n在「欲海翻波·复刻」期间限时供应。"
  },
  Item_55919_Name = {
    Text = "婴孩母树畸瘤"
  },
  Item_55920_Desc = {
    Text = "与某位淑女同款的阳伞，撑开时可以获得淑女永不低头的自信。\n在「群星正位」期间限时供应。"
  },
  Item_55920_Name = {
    Text = "淑女阳伞赠礼"
  },
  Item_55921_Desc = {
    Text = "交响乐曲抒情后的娱乐篇章，如同生命有力的脉搏，请欣赏静观与沉思后自由诙谐的趣味。\n在「无形交响」期间限时供应。"
  },
  Item_55921_Name = {
    Text = "小步舞曲乐谱"
  },
  Item_55922_Desc = {
    Text = "某位淑女送给你的下午茶会请柬，请来品尝美味的甜点，与洋娃娃和小熊一起跳舞吧。\n在「群星正位」期间限时供应。"
  },
  Item_55922_Name = {
    Text = "淑女请柬赠礼"
  },
  Item_55923_Desc = {
    Text = "与某位淑女同款的洋裙，穿上后可以获得淑女优雅高贵的气质。\n在「群星正位」期间限时供应。"
  },
  Item_55923_Name = {
    Text = "淑女洋裙赠礼"
  },
  Item_56483_Desc = {
    Text = "代表着时代前沿技术的精密齿轮，可以代谢掉人偶老旧的部分。\n朵尔用于维修躯体的齿轮零件。用于在商店交换所需物资。"
  },
  Item_56483_Name = {
    Text = "人偶零件"
  },
  Item_56484_Desc = {
    Text = "一枚平平无奇的筹码，为你带来跌宕起伏的人生。\n用于在「好运俱乐部」交换物资。"
  },
  Item_56484_Name = {
    Text = "决胜筹码"
  },
  Item_56485_Desc = {
    Text = "原初的音符，于伊始之地，指引整支乐队迈向最终的高潮。用于在「安眠宫殿」交换物资。"
  },
  Item_56485_Name = {
    Text = "高亢乐章"
  },
  Item_56486_Desc = {
    Text = "指针轮转不歇，与无回者一同向前。\n在抵达终焉之刻，所有门扉将为你开启，所有乐章将为你奏响。\n穷极之门前精密的指针，用于在「回声」交换物资。"
  },
  Item_56486_Name = {
    Text = "终末指针"
  },
  Item_56487_Desc = {
    Text = "祂的灵识仍沉眠于深渊之中。\n深海中飘荡的胚胎，用于在「圣胎孵化」交换物资。"
  },
  Item_56487_Name = {
    Text = "无识之胚"
  },
  Item_56488_Desc = {
    Text = "祂吞噬万物，永无餍足。\n深海中飘荡的胚胎，用于在「圣胎孵化」交换物资。"
  },
  Item_56488_Name = {
    Text = "无厌之胚"
  },
  Item_56489_Desc = {
    Text = "祂对此世无欲无求。\n深海中飘荡的胚胎，用于在「圣胎孵化」交换物资。"
  },
  Item_56489_Name = {
    Text = "无欲之胚"
  },
  Item_56490_Desc = {
    Text = "冰雪为它镀上幽蓝，庆贺不屈的生命在此诞生。\n从艾尔沃斯山顶新生的花苞，用于在「吞食的野心」交换物资。"
  },
  Item_56490_Name = {
    Text = "寒冻花苞"
  },
  Item_56491_Desc = {
    Text = "月色为它镀上银白，庆贺不屈的生命在此诞生。\n从艾尔沃斯山顶新生的花苞，用于在「复仇的战意」交换物资。"
  },
  Item_56491_Name = {
    Text = "银霜花苞"
  },
  Item_56492_Desc = {
    Text = "日光为它镀上橙黄，庆贺不屈的生命在此诞生。\n从艾尔沃斯山顶新生的花苞，用于在「重生的希冀」交换物资。"
  },
  Item_56492_Name = {
    Text = "日光花苞"
  },
  Item_56493_Desc = {
    Text = "逸散在艾尔沃斯雪山中的情绪粒子。触碰时仿佛听见了野兽的撕咬与吞咽声。\n用于提升守密人在活动玩法「山峦巨口」和特遣纪录「艾尔沃斯的归人」中的共鸣。\n可在限时活动「雪山消融之时」中完成成就奖励获取。"
  },
  Item_56493_Name = {
    Text = "吞噬之心"
  },
  Item_56494_Desc = {
    Text = "逸散在穷极之扉内部的情绪粒子，触碰时仿佛听见每一个维度与时空的絮语。\n用于提升守密人在调查事件「长梦尽时」中的共鸣。"
  },
  Item_56494_Name = {
    Text = "穷极之心"
  },
  Item_56495_Desc = {
    Text = "逸散在弥萨格校园中的情绪粒子，触碰时仿佛听见了无数的嘶吼与叹息。\n用于提升守密人在调查事件「终末交响曲」中的共鸣。"
  },
  Item_56495_Name = {
    Text = "坚韧之心"
  },
  Item_56635_Desc = {
    Text = "属性为伤害强效的命轮。"
  },
  Item_56635_Name = {
    Text = "待到雪山消融"
  },
  Item_56635_StoryDesc = {
    Text = "她站上山峰，举起手中的黑刺。\n在漫天的风雪里，她迎上了那座疯狂的山脉，迎上了自己被抛弃、被背叛、被践踏的命运。\n她终将胜利，冰雪终将消融，到那时，她将以一个崭新的姿态，重现于世。她是这样说的。\n艾尔沃斯是极寒之地，那里的风雪终年不散。这是常识。就像再强大的战士也无法与崇高的存在抗衡，就像再强大的人也无法战胜自己的命运。\n可那雪山终究还是消融了，不是吗？"
  },
  Item_56636_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「门扉的答案」。\n\n万物的真相隐于门扉之后。\n她静默于此，承受所有叩问，以无声作为回应。\n她等候之人终会撰写自己的答案。"
  },
  Item_56636_Name = {
    Text = "门扉的答案"
  },
  Item_56636_StoryDesc = {
    Text = "万物的真相隐于门扉之后。\n她静默于此，承受所有叩问，以无声作为回应。\n她等候之人终会撰写自己的答案。"
  },
  Item_56637_Desc = {
    Text = "属性为狂气回充等级的命轮。"
  },
  Item_56637_Name = {
    Text = "牧羊人的手杖"
  },
  Item_56637_StoryDesc = {
    Text = "茫茫多的羊群徘徊在茫茫大的草原上。\n这世上有太多太多的羊，而羊生来就是需要牧者引领的。\n她一直是这世界的先知，手中握着知识的权杖。\n她一直是一个好牧人，始终决心将羊群引向正确的道路。\n她用那杖管教羔羊，她用那杖赶走豺狼。\n她高举着牧羊人的手杖，因她总能提前看清前路。\n曾经她引领羊群走向丰沛的水源、走向鲜嫩的草场。\n现在她目睹了世界的真相，于是引领羊群走向终极的怀抱。\n向这边走，不要回头。\n她笑着挥舞智慧的手杖。\n于是羊们看不到前方的悬崖。\n一只，两只。\n羊儿坠下，牧人欢唱。\n请跟随着无私的牧羊人吧，她已为你指明了最真切的前路。\n不必害怕，即便行过死荫的幽谷，她的杖依然与你同在。\n直到一同步入湮灭的深渊。\n"
  },
  Item_56638_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「第四乐章」。\n\n音符汇集成奔涌的星海，主题在恢弘的深空中舞蹈。\n 闭目聆听吧。聆听宇宙的落幕，聆听宇宙的高潮。"
  },
  Item_56638_Name = {
    Text = "第四乐章"
  },
  Item_56638_StoryDesc = {
    Text = "音符汇集成奔涌的星海，主题在恢弘的深空中舞蹈。\n 闭目聆听吧。聆听宇宙的落幕，聆听宇宙的高潮。"
  },
  Item_56639_Desc = {
    Text = "属性为暴击率的命轮。"
  },
  Item_56639_Name = {
    Text = "永不停歇的演奏"
  },
  Item_56639_StoryDesc = {
    Text = "「还不够完美，今晚再练十遍，你的天赋平平，想进入乐团就要更加勤奋，知道吗？」\n「是，父亲。」\n什么样的演奏才叫完美？\n他的双手不停飞舞，不容许自己出现一个失误。\n他斥责自己的杂念，鄙夷自己的平庸。\n无数音符环绕在眼前，每天，每天，他生活中的一切只有音乐。\n好在他每天都离完美的演奏距离更近了一些，他望着梦中道路尽头的光芒，又仿佛永远也无法触及。\n渴求完美已经刻入他的灵魂，然而不是所有人都愿意这样。\n「为陛下、为世人呈现最完美的音乐，这难道不是乐团的职责吗？」\n他望着一张张暗含不满的脸，如同鄙视曾经的自己。\n父亲，宫廷乐团也不过如此。\n他抛下了曾经仰望的目标，执拗地继续走上追寻完美的路。\n他无法停下双手去拉住他们的手，正如他无法停住曾经那个自己的手。\n每天，每天，他都在不停演奏着。\n音乐就是他的生命。\n除了音乐，他一无所有。"
  },
  Item_56640_Desc = {
    Text = "属性为黑印掉落的命轮。"
  },
  Item_56640_Name = {
    Text = "命运轮盘赌"
  },
  Item_56640_StoryDesc = {
    Text = "人人都想战胜命运，人人却也畏惧命运。\n勇敢者发出战斗的怒吼，怯懦者发出顺从的低吟，然而只有他发现了战胜命运的秘密。\n那就是不断邀请命运共赴赌局，催促命运开盘下一场。\n他从未畏惧过命运，因为他相信自己不会输。\n他从不询问要赌什么，无论要摆上什么筹码他都毫不犹豫，包括自己的生命。\n凭借一把轮盘赌的手枪，他吓退了无数赌红眼的手下败将，成为了伦蒂尼恩臭名昭著的赌疯子。\n真遗憾啊，没有势均力敌的对手是多么寂寞。\n直到他遇到了那个男人。\n他打败了无数凡人，终于坐上了命运的赌桌。\n很快他失去了自己的一切，又连本带利地重获了所有。\n直到重生为野兽时，他又在地上看到了那把终于射出最后一颗子弹的手枪。\n他将一颗子弹重新装填，对着自己的头再次按下了扳机。\n在一片寂静中，他咧开了嘴。\n他还没有输，那么总有一天他会赢到最后。\n他始终这样相信着，即便要赌上所有。"
  },
  Item_56641_Desc = {
    Text = "属性为银钥充能的命轮。"
  },
  Item_56641_Name = {
    Text = "冰川下的沉眠"
  },
  Item_56641_StoryDesc = {
    Text = "为了等待「那个时刻」，少女沉睡于冰川之底。艾尔沃斯的千尺寒冰封冻了她的躯壳，却未能全然封闭她的神识。\n那缕神识来自一个孩子，也来自一位母亲。在祂女儿黑暗的子宫中，神明延续万古长梦。\n二十五年的时光中，她思考过什么，眷恋过什么，期待过什么吗？\n时至今日，这些问题已经无人能够回答。至于那位少女本人……她会否向身边之人倾诉真心呢？就让一切交给时间和未来吧。"
  },
  Item_56642_Desc = {
    Text = "属性为银钥充能等级的命轮。"
  },
  Item_56642_Name = {
    Text = "真理之门"
  },
  Item_56642_StoryDesc = {
    Text = "她的名字即是智慧的化身。\n她知晓世上的一切知识，是弥萨格所有学者向往的终极。\n只要能聆听只言片语，便能获得醍醐灌顶的开悟。\n但她说，自己只是一个守门人。\n那是一扇什么样的门？\n没有人见过那扇门，学者们便将其称为真理。\n她是真理的守门人，是守护着弥萨格的雅典娜。\n塔薇并没有否定这样的猜测，只是始终如一地注视着这里，注视着这个世界。\n无言而悲悯。\n如果你有一天看到了那扇门，你会看到门上有一只极其熟悉的眼睛。\n那目光沉静而恒久。\n穿透了时间，穿透了你的灵魂。"
  },
  Item_56643_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「虚无瘟疫」。\n\n不要直视那双疯狂的眼睛，小心她已将你感染。"
  },
  Item_56643_Name = {
    Text = "虚无瘟疫"
  },
  Item_56643_StoryDesc = {
    Text = "虚无是真实带来的瘟疫，它抹去所有颜色，要把一切涂染成灰。 \n不要直视那双疯狂的眼睛，小心她已将你感染。"
  },
