  },
  Item_61391_Desc = {
    Text = "属性为银钥充能等级的命轮。"
  },
  Item_61391_Name = {
    Text = "纯银的初心"
  },
  Item_61391_StoryDesc = {
    Text = "那是一颗银白、澄澈、纤尘不染的心。\n它由纯银制成，在机械结构的心脏中有序搏动。\n也曾被血肉侵蚀，也曾因污泥染垢。\n但在死亡的阴霾笼罩之时，它终究回归了本初的形貌。"
  },
  Item_61941_Desc = {
    Text = "月色为它镀上银白，庆贺不屈的生命在此诞生。\n从艾尔沃斯山顶新生的花苞，用于在「复仇的战意」交换物资。\n\n至少掉落{s1}个"
  },
  Item_61941_Name = {
    Text = "银霜花苞"
  },
  Item_61942_Desc = {
    Text = "日光为它镀上橙黄，庆贺不屈的生命在此诞生。\n从艾尔沃斯山顶新生的花苞，用于在「重生的希冀」交换物资。\n\n至少掉落{s1}个"
  },
  Item_61942_Name = {
    Text = "日光花苞"
  },
  Item_61943_Desc = {
    Text = "冰雪为它镀上幽蓝，庆贺不屈的生命在此诞生。\n从艾尔沃斯山顶新生的花苞，用于在「吞食的野心」交换物资。\n\n至少掉落{s1}个"
