    Text = "指针轮转不歇，与无回者一同向前。\n在抵达终焉之刻，所有门扉将为你开启，所有乐章将为你奏响。\n穷极之门前精密的指针，用于在「回声」交换物资。\n\n至少掉落{s1}个"
