  },
  Item_66816_Name = {
    Text = "终末指针"
  },
  Item_67085_Desc = {
    Text = "万千世界中飘散的无法聆听的梦呓，感知的瞬间将被无序的混乱占据心灵。"
  },
  Item_67085_Name = {
    Text = "混沌梦呓"
  },
  Item_67086_Desc = {
    Text = "万千世界中飘散的无法聆听的梦呓，感知的瞬间将被原初的诞生占据心灵。"
  },
  Item_67086_Name = {
    Text = "原初梦呓"
  },
  Item_67087_Desc = {
    Text = "万千世界中飘散的无法聆听的梦呓，感知的瞬间将被彻底的盲目占据心灵。"
  },
  Item_67087_Name = {
    Text = "痴愚梦呓"
  },
  Item_67377_Desc = {
    Text = "对于守密人来说，无论是身份标识、抑或是银芯通讯中表达情绪的造像，都与精神力同样重要——无形者如是说道。\n收集一定数量后使用，可随机获得一个专属的头像、对战表情，或往期课题和相位对弈赛季的头像、对战表情。"
  },
  Item_67377_Name = {
    Text = "无形者的礼券"
  },
  Item_67378_Desc = {
    Text = "狡黠，善变。你向无形者证明了你的价值。很快，祂将向你发来邀请，邀请你一同成为世间万物的化身，无影无质的终极。\n收集一定数量后使用，可选择一个「无形者的礼券」中的未获得的头像或对战表情。"
  },
  Item_67378_Name = {
    Text = "无形者的请柬"
  },
  Item_68281_Desc = {
    Text = "后勤部向完成「调查行动」的守密人发放了特别许可，在每次完成调查行动后，守密人都可以为下一次的出发购置一批特别的珍贵银芯制品。\n数量有限，愿银钥指引我们。"
  },
  Item_68281_Name = {
    Text = "调查历程特典Ⅸ"
  },
  Item_68341_Desc = {
    Text = "购买后，可按时领取所有预购奖励"
  },
  Item_68341_Name = {
    Text = "超越星辰·限时预购"
  },
  Item_68419_Desc = {
    Text = "漫长时光下，这哀愁终会被熨平。\n神王情绪在觉知的维度留下的烙印，用于在「悲愁海渊」交换物资。"
  },
  Item_68419_Name = {
    Text = "悲愁绪思"
  },
  Item_68420_Desc = {
    Text = "无需庆祝，欢悦也为虚无。\n神王情绪在觉知的维度留下的烙印，用于在「欢悦海渊」交换物资。"
  },
  Item_68420_Name = {
    Text = "欢悦绪思"
  },
  Item_68421_Desc = {
    Text = "困倦袭来，祂将再次陷入永恒的沉睡。\n神王情绪在觉知的维度留下的烙印，用于在「惫倦海渊」交换物资。"
  },
  Item_68421_Name = {
    Text = "惫倦绪思"
  },
  Item_68682_Desc = {
    Text = "属性为狂气回充等级的命轮。"
  },
  Item_68682_Name = {
    Text = "青石王座"
  },
  Item_68682_StoryDesc = {
    Text = "在无尽的深渊中，青色王座屹立，\n天幕低垂，星辰颤抖，万物沉默。\n\n古老而又神秘的存在已然湮没，\n世世代代，众生在梦中颂歌。\n幽暗的水域，尘封的秘密，\n你的低语如潮水涌来，淹没心灵的沟壑。\n\n在那无边的梦境，先知与狂徒同游，\n追寻无形的灵魂，恐惧与敬畏交织。\n青藻缠绕的轨迹，宛如命运的编撰，\n将迷失者的心，逐渐引向那青色王座。\n啊，宇宙的荒谬与真理，\n在梦与现实交错之处，永恒的辉光闪烁。"
  },
  Item_68683_Desc = {
    Text = "属性为伤害强效的命轮。"
  },
  Item_68683_Name = {
    Text = "魔女宽檐帽"
  },
  Item_68683_StoryDesc = {
    Text = "魔女和宽檐帽子的因果，有时就像鸡与蛋的关系，分不清是帽子成就了魔女，还是魔女成就了帽子。\n不过总之，达芙黛尔就拥有这样一顶足够优雅的宽檐帽。\n这顶帽子最初属于曾经的店主，那时达芙黛尔的名字还不属于达芙黛尔，她尚且只是一个刚刚被制服的、迷茫的幽魂，一头懵懂的野兽。\n那个总是微笑着的女人带着她，如同教育孩童般，耐心地、一点点地教给她成为一个「人」的方法，以及与人打交道的秘诀。\n海港之城商贸繁华，汇聚了彼时人类文化最丰富的结晶。交换商店所在的街道上林林总总的店铺几乎包罗万象，而店主总能神奇地与所有店家老友般聊上天。\n「她真厉害。」那时的达芙黛尔心想，「但也没什么奇怪的，没有人会不喜欢她。」\n店主喜欢逛街，于是那便是千年来一直扮演着一个个被她斩下头颅的人类的达芙黛尔，第一次被要求给出自己的建议。\n「你觉得哪一顶好看？这一顶小礼帽，还是这顶宽檐帽？」\n女人对着镜子，来回试戴着琳琅满目的帽子们。原本对于达芙黛尔来说，这些不过是用来包裹身体、将自己装点得更像人类的道具。\n但那一天，她看着店主头上像一朵巨大花朵般的宽檐帽，脑海中忽然浮现出了女人戴着这样的帽子，和自己在海边沙滩上散步的样子。\n「这顶。」她突然开口，「就这一顶。」\n店主有些讶异地回过头，像是没有想到她会如此明确地表示自己的喜好。\n「好啊，确实是一顶好帽子，既然是你为我选的，我一定会好好珍惜的。」\n不知道是不是为了鼓励达芙黛尔，这顶帽子如店主承诺的那样，成为了她头上的常驻装饰，直到最后从她逐渐滑落的手中亲手交给达芙黛尔，与她微笑着的头颅一起。\n「真是一顶好帽子，我一定会好好珍惜的。」\n靡丽盛开的紫黑花朵，终于绽放在了新主人的头颅上。"
  },
  Item_68688_Desc = {
    Text = "属性为银钥充能等级的命轮。"
  },
  Item_68688_Name = {
    Text = "本源图鲁SR(临时文本)"
  },
  Item_68688_StoryDesc = {
