  Item_68846_EmojiName = {Text = "警觉"},
  Item_68846_Name = {
    Text = "温柯尔·警觉"
  },
  Item_68846_StoryDesc = {
    Text = "第12期相位对弈"
  },
  Item_68847_Desc = {
    Text = "「想起来了！这里应该这样修！」"
