  Item_68848_Name = {
    Text = "莱克·来一把"
  },
  Item_68848_StoryDesc = {
    Text = "第13期学期课题"
  },
  Item_68849_Desc = {
    Text = "「真的不能……把海里的朋友们都带回来吗？」"
  },
  Item_68849_EmojiName = {Text = "可怜"},
  Item_68849_Name = {
    Text = "奥瑞塔·可怜"
  },
  Item_68849_StoryDesc = {
    Text = "第12期学期课题"
  },
  Item_68850_Desc = {
    Text = "「系统故障，阿巴阿巴……」"
