  Item_68851_EmojiName = {Text = "大吼"},
  Item_68851_Name = {
    Text = "戈利亚·大吼"
  },
  Item_68851_StoryDesc = {
    Text = "第12期学期课题"
  },
  Item_68852_Desc = {
    Text = "「素汁？什么是素汁，我没有素汁。」"
