  Item_68853_EmojiName = {Text = "沧桑"},
  Item_68853_Name = {
    Text = "达芙黛尔·沧桑"
  },
  Item_68853_StoryDesc = {
    Text = "第12期相位对弈"
  },
  Item_68854_Desc = {
    Text = "「我是一条没人爱的鱼……」"
  },
  Item_68854_EmojiName = {Text = "墙角"},
  Item_68854_Name = {
    Text = "凯刻斯·墙角"
  },
  Item_68854_StoryDesc = {
    Text = "第13期相位对弈"
  },
  Item_68855_Desc = {
    Text = "「原来是这样，您说的有道理，我会好好想一想的。」"
  },
  Item_68855_EmojiName = {Text = "确实"},
  Item_68855_Name = {
    Text = "奥尔拉·确实"
  },
  Item_68855_StoryDesc = {
    Text = "第13期学期课题"
  },
  Item_68856_Desc = {
    Text = "「哇，主人好厉害！」"
  },
  Item_68856_EmojiName = {Text = "崇拜"},
  Item_68856_Name = {
    Text = "莉莉·崇拜"
  },
  Item_68856_StoryDesc = {
    Text = "第13期相位对弈"
  },
  Item_68857_Desc = {
    Text = "「再见了妈妈今晚我就要远航！」"
  },
  Item_68857_EmojiName = {Text = "划水"},
  Item_68857_Name = {
    Text = "墨菲·划水"
  },
  Item_68857_StoryDesc = {
    Text = "第13期学期课题"
  },
  Item_68858_Desc = {
    Text = "「主君，一起去骑马吗？」"
  },
  Item_68858_EmojiName = {Text = "开心"},
  Item_68858_Name = {
    Text = "奥吉尔·开心"
  },
  Item_68858_StoryDesc = {
    Text = "第12期相位对弈"
  },
  Item_68859_Desc = {
    Text = "「感谢你的来访。」"
  },
  Item_68859_EmojiName = {Text = "谢幕"},
  Item_68859_Name = {
    Text = "索蕾尔·谢幕"
  },
  Item_68859_StoryDesc = {
