  },
  Item_69844_Desc = {
    Text = "某位位高权重之人的葬礼上演奏的弥撒曲，安慰已故的灵魂，并祈求它们得到安息。\n在「与蔷薇书」期间限时供应。"
  },
  Item_69844_Name = {
    Text = "受祝安魂弥撒"
  },
  Item_69845_Desc = {
    Text = "某位位高权重之人的葬礼上演奏的弥撒曲，她的荣光与铭旌永在。\n在「与蔷薇书」期间限时供应。"
  },
  Item_69845_Name = {
    Text = "铭旌赞美弥撒"
  },
  Item_69846_Desc = {
    Text = "某位位高权重之人的葬礼上演奏的弥撒曲，表达了生者对亡者的哀悼和缅怀，同时坚信死亡不是终结，而是通往永生的开始。\n在「与蔷薇书」期间限时供应。"
  },
  Item_69846_Name = {
    Text = "圣祭悼亡弥撒"
  },
  Item_69851_Desc = {
    Text = "在艾尔沃斯山顶新生的蒲公英的种子，从冻土中长出的小小野草散发着勃勃生机。\n在「雪山消融之时·复刻」期间限时供应。"
  },
  Item_69851_Name = {
    Text = "雪山蒲公英种子"
  },
  Item_69852_Desc = {
    Text = "在艾尔沃斯山顶新生的常青树的种子，坚韧的树苗终会越过风霜雨雪，长成参天的巨木。\n在「雪山消融之时·复刻」期间限时供应。"
  },
  Item_69852_Name = {
    Text = "雪山常青树种子"
  },
  Item_69853_Desc = {
    Text = "在艾尔沃斯山顶新生的洁白花朵的种子，冰与雪作它的枝与叶，严寒也不能催折它的芬芳。\n在「雪山消融之时·复刻」期间限时供应。"
  },
  Item_69853_Name = {
    Text = "雪山银霜花种子"
  },
  Item_69854_Desc = {
    Text = "需要念诵诗文才会开启的神秘匣子。\n向它描述花的梦，它会赠你一束蔷薇。\n在「在春天凋零以前」期间限时供应。"
  },
  Item_69854_Name = {
    Text = "花与诗的梦"
  },
  Item_69855_Desc = {
    Text = "需要念诵诗文才会开启的神秘匣子。\n当你的意象恰到好处，它会让你看到真实。\n在「在春天凋零以前」期间限时供应。"
  },
  Item_69855_Name = {
    Text = "意与诗的梦"
  },
  Item_69856_Desc = {
    Text = "需要念诵诗文才会开启的神秘匣子。\n向它描述你的过去，它会赠你一抹回忆。\n在「在春天凋零以前」期间限时供应。"
  },
  Item_69856_Name = {
    Text = "心与诗的梦"
  },
  Item_69860_Desc = {
    Text = "明明不在人偶身上，却会自己转动的齿轮套组，会在靠近之时传出絮语一般的轻微摩擦声。"
  },
  Item_69860_Name = {
    Text = "双螺旋人偶零件"
  },
  Item_69861_Desc = {
    Text = "解忧小店之中售卖的礼盒，比百货商场中时新的货品还要精致，需要用货真价实的头颅交换。\n在「雨镇幽影」期间限时供应。"
  },
  Item_69861_Name = {
    Text = "百货魔女礼盒"
  },
  Item_69862_Desc = {
    Text = "解忧小店之中售卖的礼盒，能找到来自世界各地的罕有奇珍，需要用新鲜完整的头颅交换。\n在「雨镇幽影」期间限时供应。"
  },
  Item_69862_Name = {
    Text = "奇物魔女礼盒"
  },
  Item_69863_Desc = {
    Text = "解忧小店之中售卖的礼盒，是从店主私人仓库中拿出的秘密珍藏，充满了闻所未闻的神奇物品，需要用值得收藏的美丽头颅交换。\n在「雨镇幽影」期间限时供应。"
  },
  Item_69863_Name = {
    Text = "秘藏魔女礼盒"
  },
  Item_69867_Desc = {
    Text = "某位淑女送给你的下午茶会请柬，请来品尝美味的甜点，与洋娃娃和小熊一起跳舞吧。\n在「群星正位」期间限时供应。"
  },
  Item_69867_Name = {
    Text = "淑女请柬赠礼"
  },
  Item_69868_Desc = {
    Text = "与某位淑女同款的洋裙，穿上后可以获得淑女优雅高贵的气质。\n在「群星正位」期间限时供应。"
  },
  Item_69868_Name = {
    Text = "淑女洋裙赠礼"
  },
  Item_69869_Desc = {
    Text = "与某位淑女同款的阳伞，撑开时可以获得淑女永不低头的自信。\n在「群星正位」期间限时供应。"
  },
  Item_69869_Name = {
    Text = "淑女阳伞赠礼"
  },
  Item_69870_Desc = {
    Text = "一份画有著名商业航线的海图，可以指引往来的商人顺利抵港。\n在「于暴雨中摇曳」期间限时供应。"
  },
  Item_69870_Name = {
    Text = "金色航线的指引"
  },
  Item_69871_Desc = {
    Text = "克莱门汀心灵诊所的特制药方，可以抑制长期复发的心灵障碍。在「埋于记忆之下」期间限时供应。"
  },
  Item_69871_Name = {
    Text = "不定性疯狂处方"
  },
  Item_69872_Desc = {
    Text = "克莱门汀心灵诊所的特制药方，可以拯救永久陷入疯狂深渊之人。在「埋于记忆之下」期间限时供应。"
  },
  Item_69872_Name = {
    Text = "永久疯狂处方"
  },
  Item_69873_Desc = {
    Text = "克莱门汀心灵诊所的特制药方，可以治愈暂时性的心理创伤。在「埋于记忆之下」期间限时供应。"
  },
  Item_69873_Name = {
    Text = "临时疯狂处方"
  },
  Item_69874_Desc = {
    Text = "深海泛滥的潮涌冲击意识的边界。\n用以抵抗异梦侵蚀的仪式，在「沉渊之祀」期间限时供应。"
  },
  Item_69874_Name = {
    Text = "潮蚀防卫密仪"
  },
  Item_69875_Desc = {
    Text = "那沉眠于至暗至深之处的王的诞生将扭曲整片神识之海。\n用以抵抗异梦侵蚀的仪式，在「沉渊之祀」期间限时供应。"
  },
  Item_69875_Name = {
    Text = "神国王诞密仪"
  },
  Item_69876_Desc = {
    Text = "异梦视界中的天灾亦会通过精神共振干扰守密人的灵智。\n用以抵抗异梦侵蚀的仪式，在「沉渊之祀」期间限时供应。"
  },
  Item_69876_Name = {
    Text = "天灾戒备密仪"
  },
  Item_69877_Desc = {
    Text = "一份画有隐秘航线的海图，顺着航路可以找到得以休憩的小岛。\n在「于暴雨中摇曳」期间限时供应。"
  },
  Item_69877_Name = {
    Text = "苍海中的庇护所"
  },
  Item_69885_Desc = {
    Text = "精致细密的人偶部件，闪烁着科技和疯狂的光芒。"
  },
  Item_69885_Name = {
    Text = "精制人偶零件"
  },
  Item_69889_Desc = {
    Text = "被咒文密封的青铜盒子，其中装有呈贡上的物资。已经经过基础的除灵仪式，不会对开启者造成任何危险。\n那里太穷了，即使是最好的贡品也只有这种程度。——凯蒂古拉"
  },
  Item_69889_Name = {
    Text = "青铜呈供的「礼物」"
  },
  Item_69890_Desc = {
    Text = "散发着深渊气息的巨匣，其上缭绕着深红色雾气。里面装有巨量的物资，但开启时请务必通知专业人员进行协同。\n不用那么紧张，我已经把上面的危险清除了，只是保留了这种视觉效果，这样你才知道它来自何处。——凯蒂古拉"
  },
  Item_69890_Name = {
    Text = "猩红深渊的「礼物」"
  },
  Item_69891_Desc = {
    Text = "闪烁着金色光辉的容器，能看到液态黄金在容器边缘不息的流转，里面装有昂贵的供物。\n说实话，我觉得这个盒子比里面的东西值钱，但凡物对你起到的帮助有限，对吧？——凯蒂古拉"
  },
  Item_69891_Name = {
    Text = "黄金流转的「礼物」"
  },
  Item_69892_Desc = {
    Text = "永远不要质疑父神、《几何原本》和医生的处方。\n用以保证守密人身心健康的良方，在「多重疗愈」期间限时供应。"
  },
  Item_69892_Name = {
    Text = "解离康复疗程"
  },
  Item_69893_Desc = {
    Text = "一个疗程没效果怎么办？那就再来一个疗程！\n用以保证守密人身心健康的良方，在「多重疗愈」期间限时供应。"
  },
  Item_69893_Name = {
    Text = "解离巩固疗程"
  },
  Item_69894_Desc = {
    Text = "不小心人格分裂了怎么办？别慌，弥萨格早有准备！\n用以保证守密人身心健康的良方，在「多重疗愈」期间限时供应。"
  },
  Item_69894_Name = {
    Text = "解离急性疗程"
  },
  Item_69895_Desc = {
    Text = "一份画有古老航线的海图，据说标记之处藏有传说中的秘宝。\n在「于暴雨中摇曳」期间限时供应。"
  },
  Item_69895_Name = {
    Text = "藏于深海的秘宝"
  },
  Item_69896_Desc = {
    Text = "葬骸城王邸的宴会餐品，由食尸鬼之王亲制的主菜，每个食客的梦寐之求。\n在「死灵的美学」期间限时供应。"
  },
  Item_69896_Name = {
    Text = "祭灵节主菜"
  },
  Item_69897_Desc = {
    Text = "葬骸城王邸的宴会餐品，所有汤品都是精选食材熬制而成。\n在「死灵的美学」期间限时供应。"
  },
  Item_69897_Name = {
    Text = "祭灵节汤品"
  },
  Item_69898_Desc = {
    Text = "葬骸城王邸的宴会餐品，即使是开胃菜也是用心之作。\n在「死灵的美学」期间限时供应。"
  },
  Item_69898_Name = {
    Text = "祭灵节前菜"
  },
  Item_69899_Desc = {
    Text = "故事的开端，魔法的银芯胶片不翼而飞。这是女孩和主人的悬疑故事。\n在「故事的魔法」期间限时供应。"
  },
  Item_69899_Name = {
    Text = "悬疑故事胶片"
  },
  Item_69900_Desc = {
    Text = "故事的间奏，滑稽的业余演员闪亮登场，这是女孩和怪盗的喜剧故事。\n在「故事的魔法」期间限时供应。"
  },
  Item_69900_Name = {
    Text = "喜剧故事胶片"
  },
  Item_69901_Desc = {
    Text = "故事的结局，同伴的夕阳剪影载入画册，这是女孩和鲸鱼的奇幻故事。\n在「故事的魔法」期间限时供应。"
  },
  Item_69901_Name = {
    Text = "奇幻故事胶片"
  },
  Item_69902_Desc = {
    Text = "不知如何腐蚀残缺的人偶部件，貌似生锈的金属伤口中却流出黑色的脓血。"
  },
  Item_69902_Name = {
    Text = "锈蚀人偶零件"
  },
  Item_69985_Desc = {
    Text = "穷极的门扉开启，带来更加接近原初的力量——无人不畏惧祂，无人不向往祂。\n产自弥萨格地底黑池的神秘灵核，受到门扉之后力量的精炼，更加接近原初的本质，能帮助唤醒体提升至难以想象的高度。"
  },
  Item_69985_Name = {
    Text = "精粹原初灵核"
  },
  Item_69986_Desc = {
    Text = "散落于黑池中的碎片，在穷极门扉的照耀中，等待着来自原初的力量诞临的时刻。\n产自弥萨格地底的神秘碎片，受到门扉之后力量的精炼，能合成精粹原初灵核。"
  },
  Item_69986_Name = {
    Text = "精粹灵核碎片"
  },
