  Item_70292_Desc = {
    Text = "在「超越星辰·限时预购」中可获得。\n「当群星抵达正确的位置，伟大的@1降临于世。」"
  },
  Item_70292_Name = {
    Text = "星辰正位之刻"
  },
  Item_70292_StoryDesc = {
    Text = "V2.0版本预购活动"
  },
  Item_70919_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「群星的庇佑」。\n\n他选择了那顶王冠，那顶王冠亦选择了他。\n新王与古神的灵魂一瞬间共鸣，遮天蔽日的虚影在他身后显现，为国家带来永恒的安宁。"
  },
  Item_70919_Name = {
    Text = "群星的庇佑"
  },
  Item_70919_StoryDesc = {
    Text = "他选择了那顶王冠，那顶王冠亦选择了他。\n新王与古神的灵魂一瞬间共鸣，遮天蔽日的虚影在他身后显现，为国家带来永恒的安宁。"
  },
  Item_71281_Desc = {
    Text = "受苦难的灵魂啊，万不可失去希望，仁爱的主教会为你向父神献上祷告。\n在「灵魂的牧人·复刻」期间限时供应。"
  },
  Item_71281_Name = {
    Text = "弥撒中的祈祷"
  },
  Item_71282_Desc = {
    Text = "受苦难的灵魂啊，你将被嘉奖，仁爱的主教要代父神为你降下赐福。\n在「灵魂的牧人·复刻」期间限时供应。"
  },
  Item_71282_Name = {
    Text = "弥撒后的赐福"
  },
  Item_71283_Desc = {
    Text = "受苦难的灵魂啊，不需要迷茫，仁爱的主教会为你指引方向。\n在「灵魂的牧人·复刻」期间限时供应。"
  },
  Item_71283_Name = {
    Text = "弥撒前的指引"
  },
