  Item_72089_Desc = {
    Text = "”橡果代表着一场冒险的开始，我们需要更多的橡果！“——伊格娜蒂丝。由伊格娜蒂丝的魔力凝结而成的橡果，用于在「回合奇赏」交换物资。"
  },
  Item_72089_Name = {
    Text = "魔法橡果"
  },
  Item_72089_StoryDesc = {
    Text = "逆转回合联动"
  },
  Item_72095_Desc = {
    Text = "记录此钥令后，可在「相位对弈」编队时选择钥令技能:「酒馆之门」。\n\n当一个世界落幕，另一个世界的序章便已开启。故事会随着美酒一同不断被人们传颂，然而时间会为万事万物书写答案。"
  },
  Item_72095_Name = {
    Text = "酒馆之门"
  },
  Item_72095_StoryDesc = {
    Text = "当一个世界落幕，另一个世界的序章便已开启。故事会随着美酒一同不断被人们传颂，然而时间会为万事万物书写答案。"
  },
  Item_72824_Desc = {
    Text = "位于赫普兰德大陆的一间小酒馆，其中有着能够连接不同世界的传送门。\n酒馆的主人伊格娜蒂丝创造了名为万象牌的卡牌游戏，用来传颂曾经英雄们的故事。"
  },
  Item_72824_Name = {
    Text = "逆转回合：万象牌"
  },
  Item_72824_StoryDesc = {
    Text = "逆转回合联动"
  },
  Item_72834_Desc = {
    Text = "有机会通过「无形者的礼券」获得。\n「哎呀，有人想尝一尝我新泡的蜘蛛药茶吗？」"
  },
  Item_72834_Name = {
    Text = "以银钥之名：茜尔维娅"
  },
  Item_72834_StoryDesc = {
    Text = "外观珍藏券专属"
  },
  Item_72835_Desc = {
    Text = "在活动「织者自缚」中完成成就获得。\n「啊呀，不要打断我的编织哦，没有什么比这更重要了……」"
  },
  Item_72835_Name = {
    Text = "以银钥之名：阿拉克涅"
  },
  Item_72835_StoryDesc = {
    Text = "阿拉克涅玩法活动"
  },
  Item_72836_Desc = {
    Text = "「您的演奏……的确……挺努力的。」"
  },
  Item_72836_EmojiName = {Text = "无奈"},
  Item_72836_Name = {
    Text = "哈姆林·无奈"
  },
  Item_72836_StoryDesc = {
    Text = "第18期相位对弈"
  },
  Item_72837_Desc = {
    Text = "在活动「画布的暗面」中完成成就获得。\n「如果只能画出肉眼可见的景象，那与庸俗的凡人有什么两样？」"
  },
  Item_72837_Name = {
    Text = "以银钥之名：皮克曼"
