  },
  Item_72949_Desc = {
    Text = "有机会通过「无形者的礼券」获得。\n「咳，我真没喝多少，你不用叫拉蒙娜。」"
  },
  Item_72949_Name = {
    Text = "以银钥之名：德克斯特"
  },
  Item_72949_StoryDesc = {
    Text = "外观珍藏券专属"
  },
  Item_72950_Desc = {
    Text = "「我堂堂迷宫之神、伟大的苍白之物，为什么要写作业……」"
  },
  Item_72950_EmojiName = {Text = "委屈"},
  Item_72950_Name = {
    Text = "阿格里帕·委屈"
  },
  Item_72950_StoryDesc = {
    Text = "第22期相位对弈"
  },
  Item_72951_Desc = {
    Text = "在活动「坠临的万千耀光」中完成成就获得。\n「太阳底下，皆是灰烬！」"
  },
  Item_72951_Name = {
