  },
  Item_73463_Desc = {
    Text = "珈伦烤的小鱼喵？……唔？！这股味道……怎么跟宛儿做的那么像喵……"
  },
  Item_73463_EmojiName = {Text = "盯"},
  Item_73463_Name = {
    Text = "凯希·盯"
  },
  Item_73463_StoryDesc = {
    Text = "逆转回合联动活动"
  },
  Item_73464_Desc = {
    Text = " 呜……相位对弈好难玩……比最难演奏的曲子还要难！莉雅姐姐，新手卡组求推荐……"
  },
  Item_73464_EmojiName = {Text = "哭泣"},
  Item_73464_Name = {
    Text = "贝蒂·哭泣"
  },
  Item_73464_StoryDesc = {
    Text = "逆转回合联动活动"
  },
  Item_73465_Desc = {
    Text = "嘿嘿，轮到我出牌啦！果然不管是相位对弈还是万象牌，最重要的灵魂，还是最后逆转局面的这个回合呀！"
  },
  Item_73465_EmojiName = {Text = "到我咯"},
  Item_73465_Name = {
    Text = "伊格娜蒂丝·到我咯"
  },
  Item_73465_StoryDesc = {
    Text = "逆转回合联动活动"
  },
  Item_73466_Desc = {
    Text = "为了来自异世界的友谊，以及万象酒馆的诸位，干杯！"
  },
  Item_73466_EmojiName = {Text = "干杯"},
  Item_73466_Name = {Text = "干杯"},
  Item_73466_StoryDesc = {
    Text = "逆转回合联动活动"
  },
  Item_73467_Desc = {
    Text = "维度波动方程？银芯提取原理？那是什么东西？不好意思……光辉女神好像没有教导过我这个。"
  },
  Item_73467_EmojiName = {Text = "疑惑"},
  Item_73467_Name = {
    Text = "波妮·疑惑"
  },
  Item_73467_StoryDesc = {
    Text = "逆转回合联动活动"
  },
  Item_73468_Desc = {
    Text = "尽管相位连接有些时候……不太稳定，但毋庸置疑，这是一场精彩的对局！结束后加个好友点个赞如何？"
  },
  Item_73468_EmojiName = {
    Text = "打得不错"
  },
  Item_73468_Name = {
    Text = "打得不错"
  },
  Item_73468_StoryDesc = {
    Text = "逆转回合联动活动"
  },
  Item_73469_Desc = {
    Text = "这卡在相位对弈里怎么是这个效果！不服不服，再来一把！下把我一定赢！"
  },
  Item_73469_EmojiName = {Text = "不服气"},
  Item_73469_Name = {
    Text = "亚维斯·不服气"
  },
  Item_73469_StoryDesc = {
    Text = "逆转回合联动活动"
  },
  Item_73471_Desc = {
    Text = " 汪！我怎么又变成这样了！完蛋了汪！！老板娘不会放过我的啊啊啊！只…只要找到银芯帽子的话……"
  },
  Item_73471_EmojiName = {Text = "震惊"},
  Item_73471_Name = {
    Text = "莱特·震惊"
  },
  Item_73471_StoryDesc = {
    Text = "逆转回合联动活动"
  },
  Item_73472_Desc = {
    Text = " 原来这个指令装置的运作原理是这样的，真是新奇啊，弗莉达也一定会感兴趣的吧！"
  },
  Item_73472_EmojiName = {
    Text = "豁然开朗"
  },
  Item_73472_Name = {
    Text = "杜兰·豁然开朗"
  },
  Item_73472_StoryDesc = {
    Text = "逆转回合联动活动"
  },
  Item_73473_Desc = {
    Text = "既然老板娘都这么说了……嘿嘿嘿！那就请卡牌大师……不对，那就请守密人多多指教啦！"
  },
  Item_73473_EmojiName = {
    Text = "诶我也要上吗"
  },
  Item_73473_Name = {
    Text = "莉雅·诶我也要上吗"
  },
  Item_73473_StoryDesc = {
    Text = "逆转回合联动活动"
  },
  Item_73582_Desc = {
    Text = "属性为银钥充能等级的命轮。"
  },
  Item_73582_Name = {
    Text = "未送出的花"
  },
  Item_73582_StoryDesc = {
    Text = "一束放置太久而枯萎干涸的花。\n永远等不来它的主人。"
  },
  Item_74093_Desc = {
    Text = "遥远群星于闪烁时留下的破碎梦境。感知其中的灵性，便能窥见肉眼无法观测的未来。"
  },
  Item_74093_Name = {
    Text = "碎裂余梦"
  },
  Item_74143_Desc = {
    Text = "遥远群星于闪烁时留下的完整梦境。那些亘古的灵性，昭示着命定的未来——群星即将正位。"
  },
  Item_74143_Name = {
    Text = "群星余梦"
  },
  Item_74200_Desc = {
    Text = "逸散在灰烬雾都的情绪粒子，触碰时仿佛能听到谁绝望无助的咆哮。\n用于提升守密人在调查事件「重临雾都」中的共鸣。"
  },
  Item_74200_Name = {
    Text = "绝灭之心"
  },
  Item_75778_Desc = {
    Text = "干枯而苍白的野兽头骨，偶尔会发出磨牙一般的咯哒声，也许是你的错觉吧。\n貌似可以赢得那位店主的喜爱。\n\n至少掉落{s1}个"
  },
  Item_75778_Name = {
