  Item_78884_Desc = {
    Text = "属性为暴击率的命轮。"
  },
  Item_78884_Name = {
    Text = "圣子尊容"
  },
  Item_78884_StoryDesc = {
    Text = "「圣子是持灯者注视之人，生而受到祂的眷顾。」\n「圣子应传播祂的旨意，将光明赐予虔诚的义人。」\n「圣子需保持灵魂的洁净。」\n「圣子应戒除俗欲、虔诚修行，全心侍奉光明。」\n「圣子不可多言、不可妄语。」\n「圣子应远离罪孽、远离有罪之人，不可被污浊的灵魂污染。」\n「圣子……」\n从他有记忆开始，一条又一条戒律就如锁链般束缚着他，将他捧上尊崇的高台，又令他不可失仪、不可低头、不可放纵喜怒。\n他被披上宽大而华丽的衣袍，簇拥在无数侍从之中，按照要求扮演那个神圣的代表，俯视着虔诚的信徒匍匐跪倒、小心亲吻他的衣角。\n圣子本应如此，无人在意那副高傲而不变的面容下，究竟有怎样的情绪与喜好。\n正如他习惯了那高傲的笑容，在无人之时亦不知自己真正想摆出怎样的表情。\n「波吕克斯圣子，您该前往赐福仪式了。」低垂头颅的侍女恭敬地安排着他一成不变的生活。\n他转过身，昂起头，露出那同样一成不变的笑容，如同亲手戴上一张神圣的面具。\n那些迷茫、空虚和寂寞，都被遮盖在面具之下，如同从未存在。"
  },
  Item_78885_Desc = {
    Text = "属性为暴击伤害的命轮。"
  },
  Item_78885_Name = {
    Text = "迫近的太阳"
  },
  Item_78885_StoryDesc = {
    Text = "太阳每秒散发出超过300秭焦耳的能量，它们中的数十亿分之一会以光和热的形式，行驶超过147亿米的路程，从太空向地球袭来。\n这些能量满足了地球上所有生物的需求，让这复杂、庞大、混乱的三域中的所有物种可以顺利地进行繁衍，进化。\n\n「这是世界的真理，任何情况都不会改变。」\n他不断这么告诫自己，以此维持精神的稳定。\n「可为什么……这么热，这么亮。」\n因为那147亿米外之物，正缓缓占据他的眼瞳。\n光和热从他瞳孔中散出，灼烧着每一寸华贵的躯体。\n「我理解了，我理解了，我理解为何光会在8分20秒之后，才会来到地球。」\n「因为我们无法支付，直面光辉的代价。」\n当他接受一切时，他开始放声大笑。\n「原来我比伊卡洛斯，更加接近太阳。」"
  },
