  Item_80189_Name = {
    Text = "超值礼包空包"
  },
  Item_80191_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「特殊治疗」。\n\n她曾治愈无数患者，引导他们走向新生，如今的一切，也只是一场心理治疗罢了。\n唯一特殊的是，患者是她自己。"
  },
  Item_80191_Name = {
    Text = "特殊治疗"
  },
  Item_80191_StoryDesc = {
    Text = "她曾治愈无数患者，引导他们走向新生，如今的一切，也只是一场心理治疗罢了。\n唯一特殊的是，患者是她自己。"
  },
  Item_80192_Desc = {
    Text = "逸散在心灵疗养院中的情绪粒子，碰触时仿佛能听到谁濒临崩溃的呢喃。\n用于提升守密人在调查事件「蜕变」中的共鸣。"
  },
  Item_80192_Name = {
    Text = "认知之心"
  },
  Item_80285_Desc = {
    Text = "解锁后，完成「疗养纪行」全部任务可额外获得以下奖励"
  },
  Item_80285_Name = {
    Text = "疗养纪行"
  },
  Item_81021_Desc = {
    Text = "珈伦特制的清扫工具，无论什么东西都能丝滑地清理干净。"
  },
  Item_81021_Name = {
    Text = "清扫工具"
  },
  Item_81069_Desc = {
    Text = "后勤部向完成「调查行动」的守密人发放了特别许可，在每次完成调查行动后，守密人都可以为下一次的出发购置一批特别的珍贵银芯制品。\n数量有限，愿银钥指引我们。"
  },
  Item_81069_Name = {
    Text = "调查历程特典·星辰篇Ⅱ"
  },
