  Item_81756_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「不灭的雷光」\n\n燃烧，燃烧，燃烧。\n哪怕骨血已沸腾，哪怕皮肉已焦糊，也要榨干身体里的最后一滴血液，绽放光明。\n因为这黑暗中，我是唯一的指引。"
  },
  Item_81756_Name = {
    Text = "不灭的雷光"
  },
  Item_81756_StoryDesc = {
    Text = "燃烧，燃烧，燃烧。\n哪怕骨血已沸腾，哪怕皮肉已焦糊，也要榨干身体里的最后一滴血液，绽放光明。\n因为这黑暗中，我是唯一的指引。"
  },
