  Item_88872_Name = {
    Text = "数理之书"
  },
  Item_88873_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「错位命运」。\n他们总在错误的时间与一瞬的希望擦肩而过。\n曾经那只稚嫩的手牵引着他，一同奔向自由的光芒。\n当他拼命挥动翅膀，再一次突破命运的监牢，可为何那只熟悉的手，此刻却穿透了他的胸膛？"
  },
  Item_88873_Name = {
    Text = "错位命运"
  },
