  },
  Item_89573_Desc = {
    Text = "属性为狂气回充等级的命轮。"
  },
  Item_89573_Name = {
    Text = "重生于湮土"
  },
  Item_89573_StoryDesc = {
    Text = "你踏上了一片杳无人烟的荒原。\n人类活动的痕迹消亡已久，灵魂枯槁的生灵在灰烬与尘霾中艰难跋涉。\n这里的存活不值得歆羡，无人知晓旅程的终点，只在无尽循环的光景中徘徊、徘徊、徘徊。\n直到他们的脚步滞涩，重重栽倒在地，仰望着天空伸出呼唤之手——\n\n愿我的跋涉终结之后，\n以尸骨为沃土、为滋养、为源泉，孱弱的新芽重新破土。"
  },
  Item_89651_Desc = {
    Text = "探索过程中爆发性获取狂气的命轮。"
  },
  Item_89651_Name = {Text = "开学日"},
  Item_89651_StoryDesc = {
    Text = "这是你来到弥萨格的一年后。 你仍然记得你从那场大爆炸中醒来后，第一次踏入这所学校的那一天。你被发放了合身而规整的校服，拥有了独属于自己的宿舍，第一次参观餐厅并吃光了两摞餐盘。 所有轻松的时刻在这一天戛然而止，转眼你就因过于贫瘠的知识和婴儿般光滑的脑回路，被勒令就读为期一年的预科班。 语言学习，体能特训，银芯能力测试，特种生物常识补充……在饱受折磨之后，你的成绩好坏参半，你那不及格的雷欧通用语成绩和一次性链接了三个唤醒体的壮举让你在校园中名动一时。 幸运的是，出于你特殊的能力与卓绝的天赋，你还是迅速达到了一位调查员的能力标准，不必再继续延长预科的时长。至于你那些参差不齐的短板，就由那些逐渐默契的伙伴们替你补习与兜底。啊，这里虽然盛产魔鬼，那也是一群可靠温柔的魔鬼。 这里常常多云、落雨、少有晴天，无数被遗忘的和将被遗忘的人们始终坚守、牺牲、不断前进。 在这样诸事如常的一天，弥萨格迎来了又一年的开学日。 你对着镜子整理好校服的衣领，抚平每一丝褶皱，而后推开了宿舍楼的大门。 「哈欠，终于来了，我都快睡着了。」 「你是在宿舍里学习抱窝吗？新生。」 你冲萝坦讪笑一声，对着那个足以引起你生理恐惧的粉色身影缩了缩脖子，躲到了一旁笑着的拉蒙娜和奥吉尔身后，五道影子在清晨的校园里摇晃着拉长。 「走吧，搭档。」 「从今天起，你就正式成为弥萨格的一员了。」"
  },
  Item_89652_Desc = {
    Text = "释放钥令后提高装备者临时暴击率的命轮。"
  },
  Item_89652_Name = {
    Text = "搭档特训"
  },
  Item_89652_StoryDesc = {
    Text = "哪怕没有前面一截人生的记忆，从你并不发达的肌肉也可以看出，你之前一定不是什么热爱运动或暴力的那类人。\n你实在想不通弥萨格对调查员定下的战斗标准为何如此之高、如此全面。\n难道调查员的重点不在于调查两个字，不在于智慧的头脑、缜密的逻辑与一点恰如其分的好运吗？\n每次被拉蒙娜从宿舍的被窝中准时拖起，站在空荡荡的操场上面对一轮又一轮的攻击时，你就格外想念朵尔教授那充满讽刺的逻辑学课程。即使是成山的作业和最令人脱发的试卷，也比战斗训练中一次次被殴打和跌倒的痛苦要温柔太多。\n第19次，你被那柄封堵了所有行动路线的刺剑逼得失去了平衡，向后一屁股栽倒在地，感到浑身骨头即将散架。\n气喘吁吁中，你颓然抹去额头的汗水，说什么也不肯再起来了。\n拉蒙娜没有任何意外的神色，她挽出一个漂亮的剑花收起了剑，鞋跟清脆地踏响着向你走来。你两眼一闭，决心抱头承受所有的指责与批评。\n意外的是，没有任何敲打或谩骂到来，三秒之后你睁开眼睛，只有一张淡淡的笑脸凑在你的面前。\n拉蒙娜微微弯下腰，一只被洁白手套包裹的手掌向你伸来。\n「其实你已经很努力了，我知道。但我们要面对的永远是未知的恐惧与危险，哪怕是我，也会有顾及不到的意外时刻。」\n「就当是为了让我放心一点，再来一次吧，搭档。」"
  },
  Item_89842_Desc = {
    Text = "一枚不知何时出现的纸券，触碰时眼前浮现出神秘的幻象。可用于在「幻衣订购」兑换一期简约幻衣。"
  },
  Item_89842_Name = {
    Text = "简约幻衣绘形券（一期）"
  },
  Item_89873_Desc = {
    Text = "每日常规补助"
  },
  Item_89873_Name = {
    Text = "每日常规补助"
  },
  Item_89952_Desc = {
    Text = "安静的房间里，二十四名房客开始了她们的茶会。\n\n「不知道詹金今天过得怎么样？」\n温吞的24担忧地望着窗外。\n「这是庆祝我们逃出来的日子，我们说好了，在这一天，我们只有自己。高兴一点，24们，这可是一个派对！」热情的24挥舞着双手。\n「或许我们可以考虑一个安静且有深度的方式……」大概没有人在听学者24说的话。\n「你们要跳一支舞吗？我可以为你们奏乐！」小丑24奏响了喇叭。\n「来吧，今天的茶会是为你们准备的。」主人格24拉着两个人的双手，带她们来到舞池。她早已习惯了这间屋子女主人的身份。「我们的痛苦都承担在你们的身上……忘记那些困扰你们的东西吧，至少在今天。」\n「喵~」在影子24的抚摸下，猫咪24期待地摇着尾巴。\n抑郁的24和躁狂的24互相望了一眼。她们共同担下了这间屋子里所有的苦难与困惑。她们是朝夕相伴的挚友。她们是此生不渝的仇敌。她们携起对方的手，来到了房间中央的空地。所有的不安与悲伤都平息下来，她们欢笑、纠缠，她们齐声歌唱，跳跃、旋转。血与泪打湿衣衫与地板，音乐和舞步，在同一个脑海中响起。\n\n安静的房间里，二十四名房客屏住呼吸。\n她们享受着这一刻的平静，只为她们自己。"
  },
  Item_89952_Name = {
    Text = "双相和鸣"
  },
  Item_89953_Desc = {
    Text = "叮咚、叮咚。那是生锈的八音盒在歌唱，歌唱一首变了调的天鹅挽歌。\n悲伤的人偶在八音盒中不停旋转，飞旋的热泪投入青绿色的火焰，凝成一滴滴晶莹的宝石雨。\n\n无数扭曲的面孔从火焰中浮现，贪婪地吞食那些泪滴，又痛苦地抓挠她的裙摆。\n“跳！继续跳！永远都不要停下来！”\n“你凭什么还能跳舞？你有什么资格！谋杀者！杀人狂！”\n\n那是莉兹在每一个深夜都不断轮回的噩梦，无数灵魂在她环状的视野中张大嘴巴，哀嚎又歌唱。而她的脚尖绷直、臂膀僵硬，身体固定成最标准的舞姿——随着齿轮的转动不停旋转、旋转。\n\n如果你于梦醒时分与她相见，不要询问她为何不愿再起舞，她已将所有爱、恨与泪水尽数抛洒于梦中的火焰。\n\n她将爱投入那火，于是她放下了毕生所爱之事。\n她将恨投入那火，于是她绝口不提那些腌臜与罪孽。\n她的爱与恨纠缠焚毁，共同将她的灵魂染上无穷的、青色的愁怨。"
  },
  Item_89953_Name = {
    Text = "旋舞人偶"
  },
  Item_89954_Desc = {
    Text = "可爱的房间，精美的家具，绒绒的毯子，华丽的裙摆，端庄的礼仪。淑女墨菲被慷慨地赐予他人望尘莫及的地位和垂涎以求的珍宝，却始终生活如行尸走肉。\n\n某个无人知晓的夜里，她悄悄躲在废弃的衣柜中，被蹈海者的鱼人们摇摇晃晃地抬出教会，弃置在一片荒无人烟的郊野中。\n\n她推开衣柜，旷野星光灿烂。\n她跃过杂物的小山，在山脚拾到一枚小球。\n\n当戈利亚带着惊惶的鱼人小队找到遗失的圣女时，她仍坐在距离衣柜不远的地方，将手中的小球高高抛起，等小球滚落，再一次高高抛起——\n戈利亚半句话也没有询问，就将圣女重新押回了名为供奉的牢笼。\n所以她所作所为的目的，始终不曾言说，直至将匕首刺入胸膛的时刻，也一直埋藏在心底。\n\n——她想将球抛上又大又圆的月亮。\n——那样的话，它就不必再落下了。"
  },
  Item_89954_Name = {
    Text = "淑女奇趣"
  },
  Item_89955_Desc = {
    Text = "创生之父自星空而下，以血孕育生灵，以骨刻撰规则。\n万物本应以父神之规行举，以父神之意生息。\n然，光阴荏苒，神言破碎，父神之规难以贯彻，父神之意难以落下。\n万物悲苦，劫难丛生。\n\n苍白之主啊，吾将重启济世的神言，带领众生消弭悲苦。\n吾将消去万物之苦，万物之罪，万物之悲，直至吾骨血耗尽，魂归于天。\n\n第一声神言响起，肉体之欲将遭到超脱。 \n至此，色欲消亡。\n\n第二声神言响起，生灵不再沉溺欢愉。 \n至此，暴食消亡。\n\n第三声神言响起，贪欲之魔口舌喑哑。 \n至此，贪婪消亡。\n\n第四声神言响起，世间再无消极度日者。\n至此，怠惰消亡。\n\n第五声神言响起，世人不再行那无理无依之举。\n至此，愤怒消亡。\n\n第六声神言响起，再无枉死之痴迷者。\n至此，嫉妒消亡。\n\n第七声神言响起，众生将敬尊万物。\n至此，傲慢消亡。\n\n吾以父神之骨，代行父神之权。\n愿父神之光，照耀万物。\n愿济世之言……永留世间……"
  },
  Item_89955_Name = {
    Text = "济世神言"
  },
  Item_89964_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「脑中之音」。\n\n双手交握的那一刻，你们从对方的眼里看到了迷茫与困惑。\n残缺的声部在此交汇，皆因你们早已遗落了过往。\n沉默的乐章即将谱写，皆因你们决心坠入未来。"
  },
  Item_89964_Name = {
    Text = "尘封旧忆"
  },
  Item_89964_StoryDesc = {
    Text = "双手交握的那一刻，你们从对方的眼里看到了迷茫与困惑。\n残缺的声部在此交汇，皆因你们早已遗落了过往。\n沉默的乐章即将谱写，皆因你们决心坠入未来。"
  },
  Item_89988_Desc = {
    Text = "获得幻衣「旋舞人偶」后解锁。\n「不要玷污了这支舞。」"
  },
  Item_89988_Name = {
    Text = "莉兹·旋舞人偶"
  },
  Item_89989_Desc = {
    Text = "获得幻衣「双相和鸣」后解锁。\n「我、我、我，一起举办茶会吧！」"
  },
  Item_89989_Name = {
    Text = "「24」·双相和鸣"
  },
  Item_89990_Desc = {
    Text = "获得幻衣「淑女奇趣」后解锁。\n「少对淑女的爱好说三道四的！」"
  },
  Item_89990_Name = {
    Text = "墨菲·淑女奇趣"
  },
  Item_89991_Desc = {
    Text = "获得幻衣「济世神言」后解锁。\n「父神降下神言，引渡你我。」"
  },
  Item_89991_Name = {
    Text = "萨尔瓦多·济世神言"
  },
  Item_90040_Desc = {
    Text = "用厚实硬质的精装书壳包装的图书套组，内容经典、排版考究，是爱书之人装点书架的佳品。"
  },
  Item_90040_Name = {
    Text = "精装图书套组"
  },
  Item_90041_Desc = {
    Text = "从特殊渠道才能淘来的孤本古籍，记载了许多不为人知的古老智慧，只有对获取知识有狂热追求的研究者才会由衷渴望。"
  },
  Item_90041_Name = {
    Text = "孤本图书套组"
  },
  Item_90042_Desc = {
    Text = "不知如何腐蚀残缺的人偶部件，貌似生锈的金属伤口中却流出黑色的脓血。\n在「半步之隔」期间限时供应。"
  },
  Item_90042_Name = {
    Text = "锈蚀人偶零件"
  },
  Item_90043_Desc = {
    Text = "精致细密的人偶部件，闪烁着科技和疯狂的光芒。\n在「半步之隔」期间限时供应。"
  },
  Item_90043_Name = {
    Text = "精制人偶零件"
  },
  Item_90044_Desc = {
    Text = "书店内成套促销的正版书籍，拥有整齐的印刷与精致的插画，是赠送喜好阅读之人的性价比之选。"
  },
  Item_90044_Name = {
    Text = "折扣图书套组"
  },
  Item_90045_Desc = {
    Text = "明明不在人偶身上，却会自己转动的齿轮套组，会在靠近之时传出絮语一般的轻微摩擦声。\n在「半步之隔」期间限时供应。"
  },
  Item_90045_Name = {
    Text = "双螺旋人偶零件"
  },
  Item_90067_Desc = {
    Text = "「再捏……再捏奥瑞塔就要蛰你了！」"
  },
  Item_90067_EmojiName = {Text = "捏脸"},
  Item_90067_Name = {
    Text = "奥瑞塔·捏脸"
  },
  Item_90067_StoryDesc = {
    Text = "第18期学期课题"
  },
  Item_90554_Desc = {
    Text = "逸散在葬骸城中的情绪粒子，碰触时仿佛能听到食尸鬼满含欲望的呼吸。\n用于提升守密人在调查事件「餍飨」中的共鸣。"
  },
  Item_90554_Name = {
    Text = "暴食之心"
  },
  Item_90856_Desc = {
    Text = "在「颅庭挽歌·限时纪行」中可获得。\n「他饥饿地等待着——盛宴开始，「你」被端上餐桌的那一刻。」"
  },
  Item_90856_Name = {
    Text = "永夜的饥饿凝视"
  },
  Item_90856_StoryDesc = {
    Text = "V2.3版本预购活动"
  },
  Item_90857_Desc = {
    Text = "在「共轭命途」中可获得。\n「人们总以为做下的选择，来自于自身的意志与渴望。\n但那永恒的织网者，早就写下了每个人的未来，编织成名为「命运」的罗网。」"
  },
  Item_90857_Name = {
    Text = "命运织者"
  },
  Item_90857_StoryDesc = {
    Text = "V2.5版本预购活动"
  },
  Item_90858_Desc = {
    Text = "在「临时文本」中可获得。\n「临时文本」"
  },
  Item_90858_Name = {
    Text = "临时文本"
  },
  Item_90858_StoryDesc = {
    Text = "V2.7版本预购活动"
  },
  Item_90859_Desc = {
    Text = "在「渊海胎动·限时纪行」中可获得。\n「当胸腔中的荣光洒向世界时，祭坛上的神母流下了，作为人的最后一滴泪。」"
  },
  Item_90859_Name = {
    Text = "深海的哀歌"
  },
  Item_90859_StoryDesc = {
    Text = "V2.4版本预购活动"
  },
  Item_90860_Desc = {
    Text = "在「万愿拟造」中可获得。\n「世界仍在行进，则诡计永不暂停。」"
