  },
  Item_91121_Desc = {
    Text = "有多少人钦佩于她当年的决断与勇气，就有多少人艳羡于那样重生的幸运。\n活跃的大脑之下，是无数个可替换的、不畏刀枪、永不衰老的肉体。永生的诱惑如永恒的禁果与光明的灯烛，吸引着那些掌握了富贵与权势的人们。\n曾有一位弥萨格也无法拒绝的大人物以极其丰厚的筹码作为交换，希望朵尔为他进行同样的大脑移植手术以及唤醒流程。\n朵尔没有拒绝，甚至并未讽刺他的无知，只是从百忙的实验之中抽出了短暂的会面时间，为那位大人物进行了细致的检查。而后平静地宣布了令他勃然大怒的结论——他的大脑不具备重生的条件。\n在弥萨格的百般调和下，重病将死的大人物签署了一系列免责协议，坚持要赌一赌那丝渺茫的希望。\n朵尔亲自为他实施了手术，可惜的是，希望从未存在。在朵尔说出否定的判词时，那颗开发程度不足的大脑就不可能恢复原本的灵性。\n不过看在那些诚意十足的报酬的份上，朵尔还是贴心地完成了售后服务：那颗保持了活性的大脑被放入脑缸，而后被装载了恰好匹配其性能的装置系统。\n于是朵尔的实验室中，渐渐地多了一些符合飞翔的真菌审美的小助手，那些能够短暂飞翔的小东西挥舞着灵活的螯足，执行着最简单的任务，为科学的研究与进步贡献力量。\n「I03，取一份新的蒸馏水。」\n「I05，更换掉上周的培养基。」\n「I01，帮我泡一杯咖啡。」\n看来无知的大脑也并非百无一用嘛。在咖啡氤氲的热气里，朵尔微笑着想。"
  },
  Item_91121_Name = {
    Text = "灵性重生"
  },
  Item_91157_Desc = {
    Text = "胸前的银钥匙忽然亮起，似乎在与这个宇宙之外的某处遥相呼应，你知道这是两个灵魂共鸣的证明。"
  },
  Item_91157_Name = {
    Text = "银钥辉光"
  },
  Item_91237_Desc = {
    Text = "一枚不知何时出现的纸券，触碰时眼前浮现出神秘的幻象。可用于在「幻衣订购」兑换二期简约幻衣。"
  },
  Item_91237_Name = {
    Text = "简约幻衣绘形券（二期）"
  },
  Item_91353_Desc = {
    Text = "后勤部向完成「调查行动」的守密人发放了特别许可，在每次完成调查行动后，守密人都可以为下一次的出发购置一批特别的珍贵银芯制品。\n数量有限，愿银钥指引我们。"
  },
  Item_91353_Name = {
    Text = "调查历程特典·星辰篇III"
  },
  Item_91354_Desc = {
    Text = "解锁后，完成「亡城纪行」全部任务可额外获得以下奖励"
  },
  Item_91354_Name = {
