  Item_91435_Desc = {
    Text = "「轻轻敲醒沉睡的心灵……」"
  },
  Item_91435_EmojiName = {Text = "敲"},
  Item_91435_Name = {Text = "珊·敲"},
  Item_91435_StoryDesc = {
    Text = "第19期相位对弈"
  },
  Item_91730_Desc = {
    Text = "弥萨格餐厅供应的日常肉类套餐之一，分量小巧、皮脆肉嫩，是绝对不会出错的选择。\n在「伟大的征服」期间限时供应。"
  },
  Item_91730_Name = {
    Text = "香料烤鸡套餐"
  },
  Item_91731_Desc = {
    Text = "弥萨格餐厅偶尔供应的肉类套餐之一，选取新鲜羔羊肉低温烤制，香气扑鼻、汁水充盈，深受学生欢迎，很快就会被一抢而空。\n在「伟大的征服」期间限时供应。"
  },
  Item_91731_Name = {
    Text = "嫩烤羔羊套餐"
  },
  Item_91732_Desc = {
    Text = "弥萨格餐厅节日特供的肉类套餐，拥有豪华的分量、诱人的蜜汁焦褐色与油脂充盈的肉汁，最能烘托节日的气氛，带给人满满的幸福感。\n在「伟大的征服」期间限时供应。"
  },
  Item_91732_Name = {
    Text = "火山肉排套餐"
  },
  Item_91764_Desc = {
    Text = "获得幻衣「淬血荣冠」后解锁。\n「我来，我见，我杀戮。」"
  },
  Item_91764_Name = {
    Text = "尤乌哈希·淬血荣冠"
  },
  Item_91765_Desc = {
    Text = "无论经历过多少岁月，他都不会忘记那个时代，那个属于角斗士的荣耀时代。\n「尤乌哈希……」\n起初，重金买下他的奴隶主还需要向人们宣布他的名字，但在他杀光所有对手，徒手掏出敌人的内脏，吸干他们的血液后，整个斗兽场为他沸腾。\n「嗜血者」「魔鬼」「斗兽场的暴君」……\n人们对他的称呼不停变化，与此同时，他的对手也在不停变强。\n孩子、老人、女人、男人、甚至是老虎狮子，都成为过他的对手，也纷纷被他打败\n他对于败者的哀嚎不感兴趣，也更加不可能记住「你在为什么战斗」这种无聊的临终话语。\n他只是不停重复着一件简单的事情：杀戮。\n只要他还活着，还站在斗兽场，他就是这里的无冕之王。\n而这样简单的事情，为他带来了一切。\n人们呼唤他的名字，掀起的声浪足以震动罗马最大的斗兽场。但他嗤之以鼻。\n人们为他一掷千金，抛洒的金币足以铺平斗兽场满是砂砾与血的地面。但他不屑一顾。\n那些声音、那些钱财、那些喜欢与崇拜，在他看来都是令人生厌的恶心东西，唯有温热的血是可碰触的，唯有杀戮是真实的。\n因为他渴望的，永远都是一件简单的事情：\n我来，我见，我杀戮。"
  },
  Item_91765_Name = {
    Text = "淬血荣冠"
  },
  Item_91766_Desc = {
    Text = "黑暗而无尽的迷宫里，终于又迎来了新人，这令总是暴躁不满的苍白之主久违地露出了笑容。 \n「选择吧，是和我签订契约，然后成为我的子嗣。 还是饿死在迷宫里，然后成为我的子嗣。」 \n误闯入迷宫的新人瞪大了眼睛，表情在迷茫、困惑、恐惧中快速切换，然后拔腿就逃。就和无数「前辈」一样。 \n「啊，竟然选择了逃跑~ 哈哈，跑吧跑吧，用尽全力奔跑吧——反正你永远也逃不出我的迷宫。」 \n之后，就是重复了千百次，但对阿格里帕而言仍旧充满乐趣的过程：奔跑、力竭、跌倒，被黑暗与恐惧笼罩的人求救、喊叫、绝望，最后从精神到肉体，都被彻底击碎。 \n当这些可怜人类的大脑被绝望搅拌为浆糊时，就是她这个迷宫之主出场的时刻。无需她多言，可怜可悲的人就向她伸出了求救的手。 \n「救救我……无论是谁都好，救救我……」 \n阿格里帕怜悯又残忍地望着对方，微笑。 \n「我当然会救你。就像你的前辈们一样……成为我的子嗣吧。」 \n「是的，只要签订契约，所有挣扎和痛苦就结束了。」 \n失去理智、可怜可悲的人本能地点点头，于是在黑暗而无尽的迷宫里，苍白之主再次露出了笑容。 \n契约已经完成，接下来要做的就是等待——等待子嗣的成长与诞育。"
  },
  Item_91766_Name = {
    Text = "苍白契约"
  },
  Item_91767_Desc = {
    Text = "获得幻衣「苍白契约」后解锁。\n「签订契约，然后成为我的子嗣~」"
  },
  Item_91767_Name = {
    Text = "阿格里帕·苍白契约"
  },
  Item_94417_Desc = {
    Text = "无论经历过多少岁月，他都不会忘记那个时代，那个属于角斗士的荣耀时代。\n「尤乌哈希……」\n起初，重金买下他的奴隶主还需要向人们宣布他的名字，但在他杀光所有对手，徒手掏出敌人的内脏，吸干他们的血液后，整个斗兽场为他沸腾。\n「嗜血者」「魔鬼」「斗兽场的暴君」……\n人们对他的称呼不停变化，与此同时，他的对手也在不停变强。\n孩子、老人、女人、男人、甚至是老虎狮子，都成为过他的对手，也纷纷被他打败\n他对于败者的哀嚎不感兴趣，也更加不可能记住「你在为什么战斗」这种无聊的临终话语。\n他只是不停重复着一件简单的事情：杀戮。\n只要他还活着，还站在斗兽场，他就是这里的无冕之王。\n而这样简单的事情，为他带来了一切。\n人们呼唤他的名字，掀起的声浪足以震动罗马最大的斗兽场。但他嗤之以鼻。\n人们为他一掷千金，抛洒的金币足以铺平斗兽场满是砂砾与血的地面。但他不屑一顾。\n那些声音、那些钱财、那些喜欢与崇拜，在他看来都是令人生厌的恶心东西，唯有温热的血是可碰触的，唯有杀戮是真实的。\n因为他渴望的，永远都是一件简单的事情：\n我来，我见，我杀戮。"
  },
  Item_94417_Name = {
    Text = "淬血荣冠"
  },
  Item_94418_Desc = {
    Text = "黑暗而无尽的迷宫里，终于又迎来了新人，这令总是暴躁不满的苍白之主久违地露出了笑容。 \n「选择吧，是和我签订契约，然后成为我的子嗣。 还是饿死在迷宫里，然后成为我的子嗣。」 \n误闯入迷宫的新人瞪大了眼睛，表情在迷茫、困惑、恐惧中快速切换，然后拔腿就逃。就和无数「前辈」一样。 \n「啊，竟然选择了逃跑~ 哈哈，跑吧跑吧，用尽全力奔跑吧——反正你永远也逃不出我的迷宫。」 \n之后，就是重复了千百次，但对阿格里帕而言仍旧充满乐趣的过程：奔跑、力竭、跌倒，被黑暗与恐惧笼罩的人求救、喊叫、绝望，最后从精神到肉体，都被彻底击碎。 \n当这些可怜人类的大脑被绝望搅拌为浆糊时，就是她这个迷宫之主出场的时刻。无需她多言，可怜可悲的人就向她伸出了求救的手。 \n「救救我……无论是谁都好，救救我……」 \n阿格里帕怜悯又残忍地望着对方，微笑。 \n「我当然会救你。就像你的前辈们一样……成为我的子嗣吧。」 \n「是的，只要签订契约，所有挣扎和痛苦就结束了。」 \n失去理智、可怜可悲的人本能地点点头，于是在黑暗而无尽的迷宫里，苍白之主再次露出了笑容。 \n契约已经完成，接下来要做的就是等待——等待子嗣的成长与诞育。"
  },
  Item_94418_Name = {
    Text = "苍白契约"
  },
  Item_94440_Desc = {
    Text = "获得唤醒体「茉夏」后解锁"
  },
  Item_94440_Name = {Text = "茉夏"},
  Item_94441_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得茉夏时转换获得，用于激活茉夏的启灵。"
  },
  Item_94441_Name = {
    Text = "残片·茉夏"
  },
  Item_94441_StoryDesc = {
    Text = "重复获得茉夏时转换获得，用于激活茉夏的启灵。"
  },
  Item_94442_Desc = {
    Text = "获得唤醒体「本源奥吉尔」后解锁"
  },
  Item_94442_Name = {
    Text = "本源奥吉尔"
  },
  Item_94443_Desc = {
    Text = "属性为死亡抵抗的命轮。"
  },
  Item_94443_Name = {
    Text = "理智明灯"
  },
  Item_94443_StoryDesc = {
    Text = "「以理智为明灯，就能驱散人生的迷雾。」\n曾几何时，茉夏曾经听过这样的话。\n或许是某次梭罗公司的技术人员在调试驱雾灯时脱口而出的感慨？又或许是某次去菲林根餐厅时某个路人的调侃？\n茉夏已经忘记了，她能够清晰想起的，就是听到这句话时，自己脸上的惯用社交微笑，和藏在这笑容之后的嘲讽。\n「明灯？哈，什么老掉牙的古董，现在人们都用手电筒。」\n她并非不知道这只是一种比喻，她只是不屑于理解。\n因为总有一天，她会死亡。而死亡之后，什么理智，什么迷雾，都不存在了——她会彻底从这个世界解脱。\n这是合理且必然的推测。她需要做的，只是享受这个「必然」到来前的过程。\n但从没有人告诉过她，「必然」也会遭遇「意外」。\n相似的迷雾，相似的困境，可这里没有驱雾灯，没有调查团，没有任何她熟悉的东西。她的斧子能够斩断世间的怪物，却斩不断自身的孤独与困惑化为的迷雾。\n她可以回去吗？她会回去吗？到底什么时候可以回去……\n一个又一个问题自她的内心浮起，像是无形的深水，慢慢吞噬她的心灵。此时此刻，她心中唯一的，全部的想法，就是——\n保持理智。\n不要发疯！不要发疯！不要发疯！\n无论是面对那个世界的迷雾，这个世界的迷雾，还是自己内心的迷雾。\n为了，再次回去。"
  },
  Item_94444_Name = {Text = "茉夏"},
  Item_94445_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得本源奥吉尔时转换获得，用于激活本源奥吉尔的启灵。"
  },
  Item_94445_Name = {
    Text = "残片·本源奥吉尔"
  },
  Item_94445_StoryDesc = {
    Text = "重复获得本源奥吉尔时转换获得，用于激活本源奥吉尔的启灵。"
  },
  Item_94446_Name = {
    Text = "负誓·奥吉尔"
  },
  Item_94447_Desc = {
    Text = "属性为暴击率的命轮。"
  },
  Item_94447_Name = {
    Text = "往日如影随形"
  },
  Item_94447_StoryDesc = {
    Text = "不知名的瘟疫吞噬了城镇与村庄，嗜战的人们在动荡中尽情杀戮，铁与血的交响沸腾癫狂。\n出于恐惧，或利用恐惧。\n恐惧是无形的敌人，古老的敌人，致命的敌人。\n他是一个不合格的骑士，他败给了恐惧。\n\n然而曾郑重许下的誓言仍然回荡耳畔，一年又一日，穿过早已虚无的故乡。\n「我将仁慈地对待弱者，我将勇敢地面对强敌。」\n黑夜藏匿了行凶者的脚印，尖叫和哭泣的洪流淹没街巷，人群如同惊慌失措的羊群。\n「我将毫无保留地对抗恶人，我将为不能战斗者而战。」\n枪尖染血，银盾锈蚀，影子餍足地微笑，群鸦盘旋顶空，瞳仁中有魔鬼的闪光。\n「我将帮助那些需要我帮助的人。」\n「是他，他来了。」人们低声嗫嚅，恐惧扭曲了他们的脸庞，「空心的怪物，复仇的鬼魂，自死亡的深潭归来，要将他的敌人拖入怨恨的黑沼。」\n是他。他并未忘记，他从未忘记。\n\n为何要坚持？倘若万物终将消亡，哪怕是荣耀与信仰。\n为何要退缩？既然无论命运如何嘲弄，人都唯有屈膝顺从。\n难道只为忠于忠诚，献于奉献？\n公国最后的骑士徒劳发问，灵魂同残躯一样荒芜，恐惧的余污肆意流淌，汇聚成毁灭的汪洋。\n可空荡荡的胸腔依旧缄默不语，失落的答案还不知去向。"
  },
  Item_94448_Desc = {
    Text = "能够提高装备者「狂气爆发」和「追击」造成的基础伤害，并伴随打击卡的使用，持续提高装备者打击造成的伤害。"
  },
  Item_94448_Name = {
    Text = "狂戮至世界尽头"
  },
  Item_94448_StoryDesc = {
    Text = "「当一个世界走向末日时，会发生怎样的乐子？」\n茉夏不知道，但她期待着。\n这种期待和之前都不同，这次可不是什么打几个古物的小乐子，是以一个世界为衡量尺度的研究和调查。而这研究与调查中，最重要也最核心的，是一个人——\n弥萨格守密人。\n「我会拯救这个世界……」\n「这个世界，一定不会走向崩毁的命运……」\n那个心怀理想，身负一个世界兴亡的人这样做出承诺。作为回应，茉夏知道自己应该露出感动的表情，这是人类社会约定俗成的社交礼仪。\n但她不想再伪装了，或者说，在观看过守密人直面@4，以自身为代价拯救一个世界后，她觉得没有必要对经历过宇宙恐怖的人做出伪装。\n「伪装」是人类社会的游戏规则，体面却无聊，而宇宙……宇宙真实且直白——\n要么生存，要么毁灭。\n所以，她对守密人的回答也真实且直白。\n「我不在乎这个世界是否会得到拯救，或者毁灭……比起这些，我更好奇你。」\n我好奇你是否能够践行理想，还是会摧折在追求理想的道路中。\n也好奇这个世界是会回应你的愿望，还是不可避免的走向毁灭。\n无论是哪一种，都会是盛大且不可多得的乐子。\n我会始终期待着那一天……\n用我的眼睛，我的斧头，等待着。"
  },
  Item_94449_Desc = {
    Text = "能够增幅装备者「狂气爆发」造成的护盾和力量，在使用「防御」时提供更多护盾和力量。"
  },
  Item_94449_Name = {
    Text = "而雏菊仍然盛开"
  },
  Item_94449_StoryDesc = {
    Text = "「把花环戴好，这就是你的授勋礼了，亲爱的小骑士。」\n雏菊开遍原野时，总有怠惰的兵士借着护卫的名头，拉着少年在此游荡。\n亚奎丹公国最常见的花编做的饰品，被轻轻地放在金色的发上。\n「阁下，也许……我们该训练了？」\n少年这样说着，却乖巧地将洁白的花环戴正。\n这小巧的植物，总是沐浴于光明之中，在少年的国度，亦是希望的象征。\n\n再度睁开双眼时，那些明丽的画面已不复存在。\n战马在嘶鸣，敌人不屑地一拥而上，在千军万马中，他只有孤身一人。\n然后，刺耳的喧哗声戛然而止——\n黑色的潮水涌入他的灵魂。\n随之响起的是长枪贯穿皮肉的撕裂声，鲜血的涌动声，敌人的哀嚎声。\n那些面孔上的轻蔑荡然无存，取而代之的是铺天盖地的畏惧与退缩。\n而少年只是机械地抬手，刺穿，拔出，再举起。\n直到最后一名士兵倒下。\n烟尘隐没了无数面孔，征伐者与被征伐者的残骸堆积在地，再无分别。\n\n影子缠上他的脊背，嗤笑着：「继续呀。落下你的枪，再多一次。」\n「守护者与毁灭者之间，本就只有一线之隔。如今，你已做出了选择。」\n\n黑暗遮蔽了天空，血浸透了大地。\n他看向远方的郊野——只是短短一夜，那里便永远失去了往日的色彩。\n风吹起少年的衣角，也掠过那片侥幸存留的草地。\n在无声的夜色中，在恶魔也不知道的角落里，一抹难察的纯白仍留在他的眼底。\n那是这个国度的最后一朵雏菊，在无人在意之地默默生长。\n尽管沾染了赤色，花茎弯折，却仍未倒下。"
  },
  Item_94559_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「猎食决心」。\n\n这里是弥萨格曾允诺战士们的应许之地，那罐子中储着蜜，那柜子中藏着肉。\n没有什么能阻挡勇敢的战士，他们终将拿回自己应得之物。"
  },
  Item_94559_Name = {
    Text = "猎食决心"
  },
  Item_94559_StoryDesc = {
    Text = "这里是弥萨格曾允诺战士们的应许之地，那罐子中储着蜜，那柜子中藏着肉。\n没有什么能阻挡勇敢的战士，他们终将拿回自己应得之物。"
  },
