    Text = "有机形态Ⅱ"
  },
  Item_9517_StoryDesc = {
    Text = "鳞翅目正死于孤独、爱与绝望。"
  },
  Item_9518_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「注射守护」。\n\n她说过「不痛」…但肯定是骗人的，她明明是最怕痛的小孩。"
  },
  Item_9518_Name = {
    Text = "注射守护"
  },
  Item_9518_StoryDesc = {
