  Item_9528_Name = {Text = "锁头"},
  Item_9529_Desc = {
    Text = "提高持有者造成的护盾与治疗效果，并增强持有者反击获取能力的命轮。"
  },
  Item_9529_Name = {
    Text = "伤痛之鳍"
  },
  Item_9529_StoryDesc = {
    Text = "（以下回答节选自克莱门汀的诊疗手册，仅供参考）\n\n1. 凯刻斯。\n2. 16，17……？天知道。\n人死了以后还会管这些没用的干嘛？\n3. 一个破渔村，你不可能在任何地图上查到它的名字。\n4. 我不想说。\n5. 怪胎。丑八怪。蠢猪。傻@1……这些比较常见。\n6. 闪闪发光的黄金鲶鱼脸，简称鲶鱼脸。\n7. 下雨天。\n8. 我不知道。下雨的时候，我会在沙滩上走来走去……\n有几年了吧，就看看远方，不干别的。\n9. 我说了我#¥%不知道@1滚！！\n-------\n14. 唔……或许是奥恩叔叔曾告诉我，他会在下雨的时候，驾驶一艘大帆船来接我「回家」……\n15. 是的，他履行了自己的诺言……\n我在海底漂了好几天，又渴又饿，全身都在痛……\n然后我看见奥恩叔叔和他的白色大帆船。\n他整个人，哦不，准确来说，是他的骨头挂在帆船的桅杆上——他也蜕变失败了。\n然后我用尽最后的力气漂了过去，坐在桅杆上陪着他。\n16. 我们说好要一起回家的。"
  },
  Item_9530_Desc = {
    Text = "提高持有者生命回复能力，释放狂气爆发能够获取一定的延迟治疗。"
  },
  Item_9530_Name = {
    Text = "引舵之帆"
  },
  Item_9530_StoryDesc = {
    Text = "卡修利亚民间流传着沉没文明的传说。\n\n相传远在历史记录前，星辰的异常移位使一个史前文明沉入了海底，而卡修利亚人就是那个文明的后裔。\n除了经商、渔业外，卡修利亚人出海的一大目的就是寻找失落的先祖文明。\n他们相信，在特定星位下出生的女孩会与先祖文明有感应，她们能指引沉没文明的方位，也能从风浪中庇佑船队。\n\n希莱斯特就是这样被选中的。\n她被捆缚在高悬白帆的桅杆上，看着下方的人类忙忙碌碌。\n她既不关心，也不好奇。\n\n希莱斯特能从海风、海鸟的动向中感知海上的天气，偶尔也能探知来自遥远沉睡之地的气息。\n她天生就是属于大海，属于航船的吧——希莱斯特时常这么想，被禁锢的事实似乎在她的心里没有起任何波澜。\n有时候她会离开桅杆，追寻海空中飞翔的白鸟，那时行船就会紧紧地追着她不放。\n人们相信少女是航行顺利的象征，受祝福的船只能够平安返航，带来巨额的财富与先进的文明。\n而她对此一无所知。"
  },
  Item_9531_Desc = {
    Text = "属性为暴击伤害的命轮。"
  },
  Item_9531_Name = {Text = "吮吸"},
  Item_9531_StoryDesc = {
