  },
  Item_95548_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「不落的太阳」。\n\n即使虚假的黑日已遮蔽天空，真正的太阳也永远不会熄灭。\n此刻短暂的日落，是为了迸发出更加炽热的烈阳。\n现在，燃烧着琥珀色火焰的太阳二度升起，再也不会落下了。"
  },
  Item_95548_Name = {
    Text = "不落的太阳"
  },
  Item_95548_StoryDesc = {
    Text = "即使虚假的黑日已遮蔽天空，真正的太阳也永远不会熄灭。\n此刻短暂的日落，是为了迸发出更加炽热的烈阳。\n现在，燃烧着琥珀色火焰的太阳二度升起，再也不会落下了。"
