  Item_95689_Name = {
    Text = "腐坏手骨"
  },
  Item_9568_Desc = {
    Text = "她只追求某种绝对意义上的纯粹之美，将转瞬即逝的刹那铭刻为永恒。\n·施加延时护盾，同时造成伤害\n·施加护盾，获取触腕"
  },
  Item_9568_Name = {Text = "珊"},
  Item_95690_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得杜勒赛因时转换获得，用于激活杜勒赛因的启灵。"
  },
  Item_95690_Name = {
    Text = "残片·杜勒赛因"
  },
  Item_95690_StoryDesc = {
    Text = "重复获得杜勒赛因时转换获得，用于激活杜勒赛因的启灵。"
  },
  Item_95691_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「残忍的致意」。\n\n满月已升至中天，食尸鬼之王向你致意。\n今夜，我们以仇敌的头颅啜饮仇恨。\n今夜，我们以爱人的肋骨丈量永恒。"
  },
  Item_95691_Name = {
    Text = "残忍的致意"
  },
