  Item_9608_StoryDesc = {Text = "未完成"},
  Item_9609_Desc = {
    Text = "当他纵身跃入湖底，翻腾的气泡温柔地拥抱着他。\n·施加护盾，获得反击\n·回复生命，增强触腕之力"
