  Item_9609_Name = {Text = "凯刻斯"},
  Item_9610_Desc = {
    Text = "属性为银钥充能等级的命轮。"
  },
  Item_9610_Name = {
    Text = "聚首时刻"
  },
  Item_9610_StoryDesc = {
    Text = "自被华德·菲利普斯先生收留以来，阿利斯泰尔陪同他出席过不少次弥萨格的高层会议。\n\n说是高层，实际上更像是每个月一次的辩论赛：\n菲利普斯先生语气温和，循循善诱；\n刻拉尔克什言辞辛辣，寸步不让。\n他们轮流做正方或者反方，为了弥萨格的未来或下个月唤醒系的资源配给争执不休。\n塔薇小姐是个沉默的旁观者，从不轻易给出自己的建议。\n他自己则努力做个正直的记分员，偶尔兼职裁判，甚至有一次得用上一些格斗技巧，避免小小的会议桌遭遇不测。\n\n而今，会议成员仅剩两个，一个永远不能离开黑池，另一个也为了搏得那可能的「未来」而再也不能离开地下。\n至于那张桌子，早在那次事件后就再也找不着了。"
  },
  Item_9611_Desc = {
    Text = "诃勒特代理院长特批的丰厚补给。\n封装着珍稀材料的木盒，为执行密境课室的日常试训与周常试训任务的守密人提供援助。\n可获得以下全部素材：\n闪耀晶蝶*9\n高茎海百合*9\n原生虫蛹*9\n陨星碎块*9"
  },
  Item_9611_Name = {
    Text = "Ⅰ级全界域补给"
  },
  Item_9612_Desc = {
    Text = "套装：\n甜蜜蛞蝓Ⅰ\n甜蜜蛞蝓Ⅱ\n甜蜜蛞蝓Ⅲ\n甜蜜蛞蝓Ⅳ\n甜蜜蛞蝓Ⅴ\n甜蜜蛞蝓Ⅵ"
  },
  Item_9612_Name = {
    Text = "甜蜜蛞蝓"
  },
  Item_9613_Desc = {
    Text = "历史会重演，宇宙可能除外。\n记载了神秘文字的残页，用以升格混沌界域唤醒体的材料。"
  },
  Item_9613_Name = {
    Text = "纯白残片"
  },
  Item_9614_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得旺达时转换获得，用于激活旺达的启灵。"
  },
  Item_9614_Name = {
    Text = "残片·旺达"
  },
  Item_9614_StoryDesc = {
    Text = "重复获得旺达时转换获得，用于激活旺达的启灵。"
  },
  Item_9615_Desc = {
    Text = "它沉淀未知。\n根源浮沫脱水后的沉淀物。仔细保管，这可是弥萨格商店的硬通货。"
  },
  Item_9615_Name = {
    Text = "根源沉淀"
  },
  Item_9616_Desc = {
    Text = "属性为银钥充能等级的命轮。"
  },
  Item_9616_Name = {
    Text = "核心熔解"
  },
  Item_9616_StoryDesc = {
    Text = "A.F.@1年@1月@1日\n\n08:00\n\n对编号为107至133的部件进行组装。\n\nC类型部件就差这一点了，完成后将作为自动人偶「嘀嗒人」的能源核心投入使用。\n\n我本想亲自组装的，但@2说，负责人要学会信任自己的工作伙伴。\n\n真好意思说，明明她才是那个检查部件检查到半夜的人。\n\n-------\n\nA.F.@1年@1月@1日\n\n00:21\n\n电机MF311000组装完毕，齿轮吻合，管道通畅，目前各项机能正常。即将进行最后修正。\n\n13:07\n\n接入特殊能源S，电机MF311000运转良好，与EA307850号人造躯体适配良好，人造躯体正常运转。\n\n@2很乐观，她觉得我们这次能比之前走得更远。我提醒她不要忘记第五次唤醒尝试时发生了什么，她就堵着耳朵说听不见。那次要不是我反应快，能源核心自燃的火焰会把她的头发都烧光。\n\n真该让她尝尝光头的滋味，说不定这样她还能学会谨慎。\n\n-------\n\nA.F.@1年@1月@1日\n\n14:55\n\n最终准备完毕，能源准备完毕，束缚装置已开启，束缚状态：良。躯干将在唤醒完成后进行安装。\n\n15:00\n\n开始「嘀嗒人」第13次启动尝试。\n\n15:05\n\n躯干EA307853运转正常，电机MF311000运转正常。「嘀嗒人」颈部关节活动正常，「嘀嗒人」头部部件运转正常。\n\n15:15\n\n「嘀嗒人」成功执行眨眼、视线跟随、张嘴指令。电机存在发热现象，但仍在可接受范围内。\n\n即将进行四肢部件安装，上天保佑我们这次顺利。\n\n18:07\n\n执行行走指令时，电机核心熔解，线路烧毁。特殊能源S完好无损。\n\n@2对这个特殊能源很保护，即使是我都禁止触碰。我想我可以理解，那确实是一个神秘的物件，看上去就像是普通的金属银，也不像有能量储存的能力的样子，却真的能给自动人偶供能，而且那样高的温度也没有对其造成损坏，实在是不可思议。\n\n如果这个东西能够批量生产，或者大量开采……\n\n或许我该找一天再问问她，也不知道她在这个人偶上还要花多少时间。哪一天她自己变成一个人偶，我都不会感到意外。"
  },
  Item_9617_Desc = {
    Text = "逸散在幽灵船中的情绪粒子，触碰时仿佛听见了“没办法”的沉吟。\n用于提升守密人在调查事件「风暴之眼」中的共鸣。\n可在「风暴之眼」关卡首通奖励中获取。"
  },
  Item_9617_Name = {
    Text = "无望之心"
  },
  Item_9619_Desc = {
    Text = "符号、文字、记忆……它将篡改一切。\n用于密契升级和转录，密契升级可以提升密契的主属性，密契转录会使密契随机获得副属性。"
  },
  Item_9619_Name = {
    Text = "千面印章"
  },
  Item_9620_Desc = {
    Text = "主属性从界域精通、狂气回充等级、黑印掉落和银钥充能中随机获得1个。"
  },
  Item_9620_Name = {
    Text = "甜蜜蛞蝓Ⅳ"
  },
  Item_9620_StoryDesc = {
    Text = "甜甜的，黏黏的。"
  },
  Item_9621_Desc = {
    Text = "翅膀只负责提供美丽，价值五片什。\n闪耀的水晶蝴蝶。身体大部分已被结晶化。\n用于提升混沌界域唤醒体的技能等级。"
  },
  Item_9621_Name = {
    Text = "闪耀晶蝶"
  },
  Item_9622_Desc = {
    Text = "是的，万物皆可淬制。你的本能、你的理智，甚至你的心……到头来你会发现，你和他们其实也没什么不同。\n用以升格深海界域唤醒体的材料。"
  },
  Item_9622_Name = {
    Text = "淬制理智"
  },
  Item_9623_Desc = {
    Text = "提高持有者每次造成的伤害值，超维回合结束后能够额外触发敌方的中毒。"
  },
  Item_9623_Name = {
    Text = "旋转，旋转"
  },
  Item_9623_StoryDesc = {
    Text = "巨大的舞台上，一个少女正在舞蹈。\n她头发紧紧地梳成一个发髻，头上点缀着洁白的羽毛和小巧的王冠，纯白的舞裙随着她的动作展开，在哀婉的提琴声中转了一圈又一圈。\n手臂舒展，足尖点地，白天鹅低垂长颈，向王子诉说自己的悲伤与哀愁。\n年幼的莉兹微张着嘴，看着台上轻盈优雅的少女，那是她的堂姐，在她出生以前就到她家里来，在她祖母手下接受严格的训练。平日里总是朴素而且安静的堂姐从未如今天这般鲜活，她就像一只即将振翅而去的天鹅，而她，他们，剧院里的所有人，都倾倒在她的阴影之下。\n她的心跳越来越快，越来越快——多么令人羡慕！她也想成为那只天鹅，在永恒的舞台上长久地留下属于自己的倒影。她知道自己做得到，难道祖母不曾在她不注意的时候称赞过她的腿又长又直吗？难道她那做了多年首席的表姐不曾说过，她极有舞蹈天赋吗？没错，只要她开始，只要她穿上足尖鞋，人们一定会从遥远的城市前来观看演出，她将是本世纪最伟大的舞者，芭蕾艺术的璀璨明星！\n那时的她还不知道，等待自己的，只有炽热的火焰。"
  },
  Item_9624_Desc = {
    Text = "高傲、任性、自我中心……许多与她接触过的人，都会对她的个性留下如此评价。\n·牺牲生命上限，获取护盾与算力。\n·施加护盾，增强触腕之力"
  },
  Item_9624_Name = {Text = "墨菲"},
  Item_9625_Desc = {
    Text = "持续而稳定的狂气与银钥获取，适合依赖狂气爆发的银钥角色。"
  },
  Item_9625_Name = {
    Text = "阿库特之春"
  },
  Item_9625_StoryDesc = {
    Text = "在灾厄凭空消失，危机宣告暂时解除后，弥萨格特别行动队带着「意外收获」离开了阿库特。\n德克斯特小姐最后回头看了一眼爆炸中心的巨坑，不知名植物的嫩芽竟不知何时悄然破了土。\n她松了一口气，心情愉悦。\n阿库特林地将会迎来它的春天。\n杨柳会在下一个春天到来时抽条，铃兰会在下一个雨季后悄然绽放，所有的生命都将迎来新生。\n而他们对抗未知的旅途，也将踏上新的起点。\n"
  },
  Item_9626_Desc = {
    Text = "主属性从界域精通、黑印掉落、死亡抵抗和伤害强效中随机获得1个。"
  },
