  Item_96331_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「无论何时前往黑池，你看到她的脸上都是那一副诡异的笑容，你常常怀疑是不是融蚀已经毁掉了她大脑的运动皮层，或是杏仁体表达情绪的部分只剩下了这固定的一种。」"
