  Item_96332_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「长达36小时的实验室工作令那颗天才大脑的疲惫透过人偶的躯体散发而出，你仿佛看到那无机的面庞上出现了虚幻的黑眼圈。一个保命的常识：在这种时候绝对不要挑战她的理性，绝对。」"
