  Item_9653_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「鼠鼠的智慧」。\n\n小老鼠和它的主人有着许多的共同点：\n狡黠、勇敢、跑得快……\n他们自由地穿梭在东区错落的房屋间隙，以天空为被，以屋顶为席。\n他们在城市的角落茁壮生长。"
