  Item_9663_Name = {
    Text = "远方的欢宴Ⅴ"
  },
  Item_9663_StoryDesc = {
    Text = "尽情享受欢宴吧，于歌声中。"
  },
  Item_96640_Desc = {
    Text = "梅森最近得到了一把油纸伞。\n那是从东方诸国执行任务归来的调查员，带来的一众纪念品之一。纤细的、竹制的伞骨，以不可思议的柔韧撑起了鲜红亮丽的伞面。\n她曾担心这样脆弱的手工品仅能用来观赏，但当小心地打着伞走入雨幕中时，她发现没有一滴雨珠渗进那薄薄的、仿佛一伸手就能捅破的纸面。在幽幽的油香中，她站在朦胧的红色光晕下，对东方的美感到了前所未有的着迷。\n在得到弥萨格即将举行秋日露天晚宴的通知后，梅森立刻想起了那把油纸伞。她想做一身与之相配的礼服，撑着那把伞走过校园的步道。\n她曾是伦蒂尼恩最好的纺织女工啊，哪怕没有见过东方的服饰，她按照图书馆中借来的书籍上寥寥无几的介绍，凭借想象在台灯下密密地裁剪、缝纫。 \n蕾丝、珠串、拖地的裙摆，以及东方服饰中长长的衣袖。她将她认为最美的装饰缝进了这件礼裙中，而后特地加上了红色裙边与袖衬。\n「这样就能与那把伞相称了吧。」\n梅森站在人台旁，仔细端详这件由她创造的洁白纱裙，而后突然捂住了自己的脑袋。\n「你这样卑贱的蠢货，也配穿上这样纯洁的礼服？」\n「不，不许碰它……啊！」\n恶意的人格忽然出现，四肢手臂痛苦地扭打撕扯成一团——尖叫、翻滚、淋漓飞溅的血液。\n「哈哈哈，不够！还不够红！要变得像那把伞一样红才对！」\n几分钟、或是几小时后，等梅森昏昏沉沉地从房间的地板上醒过来时，礼裙的袖角与裙摆已经溅满了来自她自己的鲜血。\n她颤抖着将手洗净，而后费力地尝试搓洗厚重的裙摆时，只看到血渍顽固地晕开更大片的浅红。\n「可是，明天晚上宴会就要开始了……」\n意识到已经来不及重新制作后，梅森愣在原地，为没用的自己又一次带来麻烦而落下眼泪。 \n「姐姐，你的裙子做好了吗？看我带来了谁！艾继丝说她也想和你学做衣服……姐姐？」 \n拉扯着羞赧伙伴，兴高采烈推开门的詹金止住了声音，两个孩子不知所措地停在门口，看向匆忙抹去泪水的梅森。\n在她故作轻松的解释中，孩子们沉默地对视。\n「没关系，姐姐还有其他漂亮的裙子，这一条就下次……下次再穿。」\n看起来比梅森还要更加悲伤的艾继丝抚摸着那些精心缝制的花边，忽然涨红了脸，着急地拽紧了梅森的袖子。\n「艾继丝刚刚和詹金来的路上，有一位白色头发的画家哥哥正坐在枫树林里画枫叶，我们可不可以把他请过来在裙子上画画，这些污渍……这些红色一定也能变成漂亮的枫叶的！」\n在詹金瞪着眼睛大喊「天才啊」的叫声中，梅森鼻尖一酸，笑着将两个最好的妹妹紧紧抱进了怀中。\n第二天晚上，于漫天飘洒的红叶中，一席红伞下，那摇曳的洁白裙摆之上，也盛满了鲜红的落枫。"
  },
  Item_96640_Name = {
    Text = "落枫如血"
  },
