  Item_9703_Name = {Text = "陨日"},
  Item_9703_StoryDesc = {
    Text = "A.F. 314，冬日的一个深夜，爆炸声响彻阿库特林地。\n大地震颤，林地亮如白昼。伴随着生命的尖啸与自然的哭嚎，村镇被夷为平地。\n据参与了「阿库特灾厄调查」的唤醒系预科生德克斯特所言，那一夜冲天的火光中，闪耀着黑与银的色彩。"
