  },
  Item_9708_Desc = {
    Text = "套装：\n埋骨地絮语Ⅰ\n埋骨地絮语Ⅱ\n埋骨地絮语Ⅲ\n埋骨地絮语Ⅳ\n埋骨地絮语Ⅴ\n埋骨地絮语Ⅵ"
