    Text = "埋骨地絮语"
  },
  Item_9709_Desc = {
    Text = "套装：\n远方的欢宴Ⅰ\n远方的欢宴Ⅱ\n远方的欢宴Ⅲ\n远方的欢宴Ⅳ\n远方的欢宴Ⅴ\n远方的欢宴Ⅵ"
  },
  Item_9709_Name = {
    Text = "远方的欢宴"
  },
  Item_9710_Name = {
    Text = "红色缎带"
  },
  Item_9711_Desc = {
    Text = "为了人类存续。\n被保存在画框里的记忆。用以升格血肉界域唤醒体的材料。"
  },
  Item_9711_Name = {
    Text = "记忆副本"
  },
  Item_9712_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得雷娅时转换获得，用于激活雷娅的启灵。"
  },
  Item_9712_Name = {
    Text = "残片·雷娅"
  },
  Item_9712_StoryDesc = {
    Text = "重复获得雷娅时转换获得，用于激活雷娅的启灵。"
  },
  Item_97139_Desc = {
    Text = "皮克曼画室特供，专属初学者的套装，收录基础画材与实用工具，助你轻松踏入艺术的殿堂。\n在「画布的暗面」期间限时供应。"
  },
  Item_97139_Name = {
    Text = "初学启程套装"
  },
  Item_9713_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得泰旖丝时转换获得，用于激活泰旖丝的启灵。"
  },
  Item_9713_Name = {
    Text = "残片·泰旖丝"
  },
  Item_9713_StoryDesc = {
    Text = "重复获得泰旖丝时转换获得，用于激活泰旖丝的启灵。"
  },
  Item_97140_Desc = {
    Text = "皮克曼画室特供，选用优质画材，助你用笔触撕裂旧规，在色彩与线条的碰撞中释放内心的躁动。\n在「画布的暗面」期间限时供应。"
  },
  Item_97140_Name = {
    Text = "笔触升阶礼盒"
  },
  Item_97141_Desc = {
    Text = "皮克曼画室特供，无与伦比的皮克曼大师珍藏。助力你的激情与疯狂在画布上自由挥洒，创造真正的艺术之美！\n在「画布的暗面」期间限时供应。"
  },
  Item_97141_Name = {
    Text = "狂彩大师珍藏"
  },
  Item_9714_Desc = {
    Text = "被囚禁的少女灵魂渴望鲜血，一如目盲者祈求光明，荒淫者沉迷爱欲。\n·生成胚胎融合度\n·转化生命为力量"
  },
  Item_9714_Name = {Text = "雷娅"},
  Item_9715_Name = {
    Text = "血链·希洛"
  },
  Item_9716_Desc = {
