  },
  Item_97242_Desc = {
    Text = "在葬骸城，没有人惧怕死亡的到来。\n在死亡到来前的每一天，人们都将它当做生命的最后一天度过，欢歌、舞蹈、宴饮作乐，这座死亡之城远比任何生者想象的更加热闹。\n当一朵紫色的勿忘我静静飘落在窗前时，接到这封来信的人会欣然沐浴、梳妆、穿上自己最爱的衣袍，而后将它别在鬓边，与城中的人们一一告别，最终牵起至爱亲朋的手。\n那是来自葬骸之主的祝福，亦是他的承诺。他祝福他们将与爱的人从此融为一体，没有谁会将谁抛弃遗忘；他承诺这份相聚的期限，是直至他消散于世间前的永恒。\n在尘世中那片墓地的附近，在那些寻求解脱的人之间，同样流传着这样一个传说。\n当你不幸受尽了这世界的折磨，将要走到生命的尽头时，你会在静谧的黎明看到一缕令灵魂感到安宁的雾。\n如果你寻着那缕雾的指引走向荒野，走向无人知晓的世界边缘，你会看到一片在无数墓碑之中绽放的紫色花海。\n那雾的尽头会伫立着一个俊美的、花朵幻化一般的青年，他仿佛已等待了你的一生那样久，如今只是按照某种命运约定的落款，要将你接引至再无苦痛的宁静梦乡。\n他会接纳你的一切，抚慰你的一切，为你带来最后的救赎。\n他会站在那片花海之中，温柔地向你伸出掌心：「你愿意和我跳一支舞吗？」"
  },
  Item_97242_Name = {
    Text = "致勿忘我"
  },
  Item_9724_Desc = {
