  Item_9730_Desc = {
    Text = "套装：\n环形诗篇Ⅰ\n环形诗篇Ⅱ\n环形诗篇Ⅲ\n环形诗篇Ⅳ\n环形诗篇Ⅴ\n环形诗篇Ⅵ"
