  Item_97317_Desc = {
    Text = "属性为银钥充能等级的命轮。"
  },
  Item_97317_Name = {
    Text = "蓝环毒素"
  },
  Item_97317_StoryDesc = {
    Text = "许多年后，面对伏地祝祷的蹈海者，诞妄·墨菲会回想起，「母亲」为她讲起蓝环章鱼故事的那个遥远的下午。\n罐中的造物柔软而炫目，奇异的幽蓝在水中浮动，诱使幼小的她不由自主地靠近。\n而弥利亚姆却抚摸她的头，带着不容拒绝的力道让她看向昏暗船舱的角落——一具蹈海者的尸身疲软地瘫倒在地，呈现出一种被毒素吮吸殆尽后的虚无苍白。\n「谨记，海洋里最宁静、也最致命的，往往是最美丽的那种。」\n玻璃罐的冷光映亮她慈悲的侧影，诞妄·墨菲只感到一种被美丽包裹的恐惧。\n\n岁月跟随星辰的节律悄然流逝，诞妄·墨菲一如往日骄纵，却也学会了沉默与观察。\n「利莫里亚，利莫里亚……」\n直至祭坛之上，那张一向平静温柔的面庞逐渐被疯狂浸染，她这才恍然，原来自己从未真正认识过弥利亚姆。那只抚摩她头顶的、温柔的母亲的手，也会为神国的敌人施以最严厉的惩戒。\n彼时，记忆深处被封存的恐惧骤然复苏，最终凝固成一种冰冷的认知——她的仁慈不过是伪装的腕足，而温柔外表幻化成的美丽蓝环，正是见血封喉的毒素本身。\n\n时至今日，虚无的神明终为诞妄·墨菲加冕。她俯视着匍匐的蹈海者，迎上弥利亚姆目光中那一丝未曾泯灭的、近乎荒诞的期冀，仿佛再度看见了那个在玻璃罐前，凝视着美丽生物而战栗的、渺小的自己。"
  },
  Item_9731_Desc = {
