  },
  Item_9736_StoryDesc = {
    Text = "「我的成名作吗？嗯——这么好奇呀，好吧好吧，毕竟是VVIP的要求。不过，普通的讲述未免太不符合我魔术大师的名号了，让我用一场盛大的表演来向你展示吧！\n来来来，请在贵宾席落座，充满金钱与背叛的悬疑快乐魔法回忆秀，即将开演！」\n-------\n一声响指，灯光亮起，卡茜亚的魔术帽悬浮在半空，黄色的开口一开一合，竟然传出了卡茜亚的声音。\n「没有很久以前，在一个不怎么遥远的地方，有一个马戏团，马戏团里有兔子、有小丑、有狮子、有大象——」\n随着帽子的抖动，从里面掉落一只兔子，一个小丑，一头狮子，一头大象。伴奏的鼓点愈发急促，伴随礼炮炸响的砰砰声，穿着华丽戏服的卡茜亚从帽子里钻了出来，并反手将帽子戴在了自己头上。\n「最重要的是，有一位天赋异禀，才华过人的魔术师学徒！」\n-------\n学徒的成长伴随着掌声，甚至成功吸引了一位穿着华丽的投资人。奇怪的是，自从投资人与他们一同旅行后，兔子、小丑、狮子、大象……很多人和动物都一个接一个地不见了踪影。舞台上空了大半，学徒却仿佛亦无所觉，她重复着原本的生活，直到投资人将一杯酒递到她的面前。\n学徒喝下酒水，晕了过去，舞台随之一黑，微弱的叹息从黑暗中飘出。\n「那是我第一次明白遗憾。」\n-------\n「但是，遗憾怎么够？我还想要知道资助人先生哭的时候是什么感觉，观众笑的时候是什么感觉，我想知道更多，更多。这时候——\n我睁开了眼睛。」\n纸制礼花在空中炸开，碎片飘飘扬扬，卡茜亚突然出现在舞台中央，她敲了敲帽檐，礼帽张开嘴，吐出一片炫目的光。\n「我睁开了眼睛，然后发现，所有情感都是光，都可以收纳到我的魔术帽中。\n现在请放轻松，我亲爱的贵宾，接下来的环节一点也不会疼，只会让你有一点麻木，感到生活有一点无趣……」"
  },
