  Item_97415_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「有人曾看见艾尔瓦为了照顾失去母亲的幼犬，整整一个月默默起夜、不得安眠。身为军人，她的忠诚属于集体，却被曾经的同伴残忍抛弃。最终受伤的兽找到了重新接纳她的族群，如果你有幸被她划归到身后，你会发现那个坚硬的外表下，埋藏着最温柔的心。」"
