    Text = "第24期学期课题"
  },
  Item_97419_Desc = {
    Text = "「如果这，就是承受血脉必经的宿命……」"
  },
  Item_97419_EmojiName = {
    Text = "宿命的哀叹"
  },
  Item_97419_Name = {
    Text = "凯刻斯·宿命的哀叹"
  },
  Item_97419_StoryDesc = {
    Text = "第25期相位对弈"
  },
  Item_9741_Desc = {
    Text = "属性为暴击伤害的命轮。"
  },
  Item_9741_Name = {Text = "临界点"},
  Item_9741_StoryDesc = {
    Text = "在贵族夫人怜悯又嫌恶地用手帕捂住鼻子，差遣仆人将不要的珠宝给她时，她想：\n多好啊，济贫院的孩子们能吃上一餐肉了。\n\n在她将自己的餐食都分给孩子们，自己则因为长时间饥饿而晕倒在走廊后，她说：\n没事的，别叫医生，诊金可值好几个面包呢。\n\n在好心的艺术家带着相熟的医生前来拜访，并向她提出长期合作时，她想：\n必须让他们先在我身上试试，不然我可不放心让孩子们来接受他们的这个什么治疗。\n\n莎拉什么都可以忍受，唯一不能忍受的便是所做的一切，最终却导致了悲剧的结局。"
  },
  Item_97420_Desc = {
    Text = "「……是要这样比吗？」"
  },
  Item_97420_EmojiName = {Text = "比拇指"},
  Item_97420_Name = {
    Text = "卡斯托尔·比拇指"
  },
  Item_97420_StoryDesc = {
    Text = "第26期相位对弈"
  },
  Item_97421_Desc = {
    Text = "临时文本"
  },
  Item_97421_Name = {
    Text = "以银钥之名：圣婴"
  },
  Item_97421_StoryDesc = {
    Text = "圣婴玩法活动"
  },
  Item_97422_Desc = {
    Text = "在「学期课题」中购买「核心课题」后可获得。\n「搭档……希望你不介意我这个称呼，你还记得我们第一次相遇的时候么？啊……对，我是指……和拉蒙娜相遇的时候。」"
  },
  Item_97422_Name = {
    Text = "永不褪色的昨天：环行·拉蒙娜"
  },
  Item_97422_StoryDesc = {
    Text = "第23期学期课题"
  },
  Item_9742_Desc = {
    Text = "主属性从暴击率、暴击伤害、银钥充能等级和狂气回充等级中随机获得1个。"
  },
  Item_9742_Name = {
    Text = "二律背反Ⅰ"
  },
  Item_9742_StoryDesc = {
    Text = "必然的，偶然的。有限的，无限的。"
  },
  Item_9743_Desc = {
    Text = "芽孢又做错了什么呢，它们只是想有个家罢了。\n虫蛹和它的芽孢邻居。用于提升血肉界域唤醒体的技能等级。"
  },
  Item_9743_Name = {
    Text = "芽孢聚合物"
  },
  Item_9744_Name = {Text = "肠子"},
  Item_9745_Desc = {
    Text = "她总围着那台修不好的摩托打转：拧一下这里的螺丝，修一下那里的管道……\n·施加可观的护盾\n·以反击施以伤害"
  },
  Item_9745_Name = {Text = "诺缔拉"},
  Item_9746_Desc = {
    Text = "巨刃的獠牙曾斩下过无数敌人、同族的头颅，亦斩下过他自己的。\n·施加力量，发动重击\n·力量对他有额外提升"
  },
  Item_9746_Name = {Text = "戈利亚"},
  Item_9747_Desc = {
    Text = "主属性从暴击率、暴击伤害、死亡抵抗和伤害强效中随机获得1个。"
  },
  Item_9747_Name = {
    Text = "环形诗篇Ⅲ"
  },
  Item_9747_StoryDesc = {
    Text = "漂浮在环形时间的罅隙里。"
  },
  Item_9748_Name = {
    Text = "蜡像先生"
  },
  Item_9749_Desc = {
    Text = "主属性从界域精通、黑印掉落、死亡抵抗和伤害强效中随机获得1个。"
  },
  Item_9749_Name = {
    Text = "埋骨地絮语Ⅵ"
  },
  Item_9749_StoryDesc = {
    Text = "我唾弃你的坟墓。"
  },
  Item_9750_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得艾瑞卡时转换获得，用于激活艾瑞卡的启灵。"
  },
  Item_9750_Name = {
    Text = "残片·艾瑞卡"
  },
  Item_9750_StoryDesc = {
    Text = "重复获得艾瑞卡时转换获得，用于激活艾瑞卡的启灵。"
  },
