    Text = "诃勒特代理院长特批的丰厚补给。\n封装着珍稀材料的木盒，为执行密境课室的日常试训与周常试训任务的守密人提供援助。\n从以下素材中选择一种：\n混沌结晶*9\n尤因他百合*9\n芽孢聚合物*9\n尤卡坦之星*9"
