  },
  Item_97613_Name = {
    Text = "捕梦香薰"
  },
  Item_9761_Desc = {
    Text = "套装：\n有机形态Ⅰ\n有机形态Ⅱ\n有机形态Ⅲ\n有机形态Ⅳ\n有机形态Ⅴ\n有机形态Ⅵ"
  },
  Item_9761_Name = {
    Text = "有机形态"
  },
  Item_9762_Desc = {
    Text = "由弥萨格大学创始人研究出的，能够提升唤醒体能力的制剂。由银芯与秘药调配而成，呈现出一种奇异的色泽。\n可以为唤醒体提供10000经验值。"
  },
  Item_9762_Name = {
    Text = "灵知制剂Ⅲ"
  },
  Item_9763_Name = {
    Text = "蜡像群组"
  },
  Item_9764_Desc = {
    Text = "属性为死亡抵抗的命轮。"
  },
  Item_9764_Name = {
    Text = "伏于夜色"
  },
  Item_9764_StoryDesc = {
    Text = "巨兽潜伏于夜色之中。\n\n小屋之内，痛失爱女的哀哭声在每个午夜冲破白日的隐忍与压抑，毫无掩饰地剧烈迸发。\n从啜泣到哀嚎，最后诉说着那个已经不属于巨兽的名字，以痛楚的呼唤声贯穿巨兽那颗与人类一般无二的心脏。\n\n回家吧，丽莎。\n噢，我的丽莎。\n巨兽无声，潜伏于夜色之中。蜷缩身形，沉沉睡去。\n终有一日，她要回去，回到那个名为「家」的地方。"
  },
  Item_9765_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得莉莉时转换获得，用于激活莉莉的启灵。"
  },
  Item_9765_Name = {
    Text = "残片·莉莉"
  },
  Item_9765_StoryDesc = {
    Text = "重复获得莉莉时转换获得，用于激活莉莉的启灵。"
  },
  Item_9766_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得希洛时转换获得，用于激活希洛的启灵。"
  },
  Item_9766_Name = {
    Text = "残片·希洛"
  },
  Item_9766_StoryDesc = {
    Text = "重复获得希洛时转换获得，用于激活希洛的启灵。"
  },
  Item_9767_Desc = {
    Text = "「繁衍」与「存续」才是泰旖丝的追求——无论这可笑的论调之下是否另有隐情。\n·提供队友狂气\n·模仿友方技能"
  },
  Item_9767_Name = {Text = "泰旖丝"},
  Item_9768_Desc = {
    Text = "给予我们未可知晓的灵知。\n源自菲林诗社的特殊胶片，能转写人的灵知。\n用以升格超维界域唤醒体的材料。"
  },
  Item_9768_Name = {
    Text = "灵知模板"
  },
  Item_9769_Desc = {
    Text = "扇动的翅膀有助于产生龙卷风，或是花粉过敏。\n成群的水晶蝴蝶。用于提升混沌界域唤醒体的技能等级。"
  },
  Item_9769_Name = {
    Text = "混沌结晶"
  },
  Item_9770_Desc = {
    Text = "它并非工艺品，而是蝴蝶撞上炼金术师后的悲惨结局。\n平凡的水晶蝴蝶。用于提升混沌界域唤醒体的技能等级。"
  },
  Item_9770_Name = {
    Text = "失色晶蝶"
  },
  Item_9771_Desc = {
    Text = "花语：离我远点。\n低茎海百合的化石。用于提升深海界域唤醒体的技能等级。"
  },
  Item_9771_Name = {
    Text = "低茎海百合"
  },
  Item_9772_Name = {
    Text = "特殊融蚀痕"
  },
  Item_97737_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「定格的仲夏留念」。\n\n现实的狂欢终有结束的一日，但铭刻于灵魂的记忆永无止息。\n无论多少次，当回忆这定格的一刻时，思念都会涨潮。"
  },
  Item_97737_Name = {
    Text = "定格的仲夏留念"
  },
  Item_97737_StoryDesc = {
    Text = "现实的狂欢终有结束的一日，但铭刻于灵魂的记忆永无止息。\n无论多少次，当回忆这定格的一刻时，思念都会涨潮。"
  },
  Item_9773_Desc = {
    Text = "液态是它的表象，它是万物的基石，是一切的构成。\n封装在玻璃瓶内的特殊物质，据说其拥有干涉命运的力量。\n可以用于提升命轮的等级。"
  },
  Item_9773_Name = {
    Text = "混乱以太（已废弃）"
  },
  Item_9774_Desc = {
    Text = "主属性从暴击率、暴击伤害、银钥充能等级和狂气回充等级中随机获得1个。"
  },
  Item_9774_Name = {
    Text = "荒原狼Ⅰ"
  },
  Item_9774_StoryDesc = {
    Text = "嗷呜，嗷呜。"
  },
  Item_9775_Desc = {
    Text = "翅膀只负责提供美丽，价值五片什。\n闪耀的水晶蝴蝶。身体大部分已被结晶化。\n用于提升混沌界域唤醒体的技能等级。"
  },
  Item_9775_Name = {
    Text = "闪耀晶蝶"
  },
  Item_9776_Desc = {
    Text = "甜甜的，硬硬的。它们在孩童的絮语间传递，成为友谊的象征，童年的珍藏。\n小孩爱吃的糖果。用以提升唤醒体技能等级。"
