  Item_9798_Name = {
    Text = "认知模板"
  },
  Item_97991_Desc = {
    Text = "一个好的节日，应当是一场纵情狂欢的理由。\n评判一个节日是否足够讨人喜欢，它的来由尤为重要。节日太小，诸如鼓励种树或是纪念一只愚蠢土拨鼠的节日，就不足以趁机享乐；节日太大，像是银霜节那样隆重的节日，则过于庄严，规矩太多。\n翻遍整本日历，墨菲最期待的就是这个叫做巡圣节的日子。这个贴心的节日天然附赠了一场夜间派对，所有人都可以将自己盛装打扮成奇形怪状的样子，最最关键的是，在这一天，无数的甜品与糖果将占领弥萨格的每个角落。\n水果软糖、酒心糖、奶糖、薄荷糖、太妃糖、各色巧克力……哈！这难道不是专门为淑女而准备的节日吗？\n墨菲兴致勃勃地戴好尖尖的女巫帽，换好蓬蓬的南瓜裙，然后认真挑选了一个最大的南瓜篮子推门而出。\n「什么？你说这些糖是专门为小孩子准备的？」\n看着詹金满载而归离去的背影，淑女不可置信地竖起了眉毛，裙摆下的触须不满地甩动起来。\n两排牙齿愤恨地磨了磨，她冷笑一声，咚地将南瓜篮子狠狠地摔在了柜台上。\n「不能领是吧，那好，现在我不是小孩，是强盗！打劫！我数三个数，把你们这所有的糖都给我包起来！赶快！」\n满头大汗的餐厅侍者被迫清空了糖果台，而后目送淑女拎着满溢出来的篮子，在猖狂的笑声中大摇大摆离开。\n这诡异的笑声在校园四处持续了整夜，后来，弥萨格之中多了这样一则传闻：在巡圣节的那一夜，所有身上携带了糖果的人都会被一个幽灵环绕的猎糖女巫精准地找上，只有虔诚上缴所有的甜食，才能从可怕的女巫手中逃出生天。"
  },
  Item_97991_Name = {
    Text = "糖果劫案"
  },
  Item_97992_Desc = {
    Text = "被特地做成南瓜形状的节庆糖果，里面的夹心混杂了不同的馅料，据说有机会吃到极其诡异的口味。"
  },
  Item_97992_Name = {
    Text = "怪味南瓜糖"
  },
