  Item_9824_Name = {
    Text = "光合祭礼Ⅴ"
  },
  Item_9824_StoryDesc = {
    Text = "科学是光谱分析，艺术是光合作用。"
  },
  Item_9825_Desc = {
    Text = "它并非工艺品，而是蝴蝶撞上炼金术师后的悲惨结局。\n平凡的水晶蝴蝶。用于提升混沌界域唤醒体的技能等级。"
  },
  Item_9825_Name = {
