  },
  Item_9826_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得莱克时转换获得，用于激活莱克的启灵。"
