  Item_98279_Desc = {
    Text = "获得幻衣「落枫如血」后解锁。\n「那摇曳的洁白裙摆之上，也盛满了鲜红的落枫。」"
  },
  Item_98279_Name = {
    Text = "「24」·落枫如血"
  },
  Item_9827_Desc = {
    Text = "释放狂气爆发后提供临时暴击伤害，并有概率降低持有者卡牌费用。"
  },
  Item_9827_Name = {
    Text = "巨人之刃"
  },
  Item_9827_StoryDesc = {
    Text = "分开。经历。蜂拥而来。侵略。\n\n对于非利士人的闪族语词根「p-l-sh」的真正涵义，经书学者们历来分歧不断。\n平生第一次，戈利亚觉得这些老学究还算有点真才实学，因为这四个简短的词汇几乎概括了他作为非利士人的一生。\n\n非利士人是名副其实的海上民族。\n他们是群聚的长尾鲨，循着鲜血的味道找到可供栖息的岛屿，再杀光那里所有的原住民。\n\n非利士人不知疲倦。\n他们从不逗留，当一切尘埃落定，躁动不安的基因又驱使他们离开，寻找新的猎物。\n\n非利士人不在乎明天。\n他们总是以惊人的速度挥霍掠夺来的财富，饮尽最后一滴葡萄酒，然后尽情繁衍、争斗、背叛……\n\n启航的时候，戈利亚回望船只在海面上拖曳而出的轨迹。\n非利士人的血，原住民的血，敌人的血，海鸟的血……\n它们汇到一处，就像暗红的墨涌入无边无际的蓝。\n\n第二天，太阳照常升起，海水如万片碎金动荡闪烁，一切都了无痕迹。\n他们身处海洋，海洋却已将他们忘却。"
  },
  Item_9828_Desc = {
    Text = "太过强硬之人，她会用战斗软化你的灵魂。\n·提升队伍力量。\n·拥有打击敌方全体的技能"
  },
  Item_9828_Name = {Text = "萝坦"},
  Item_9829_Desc = {
    Text = "他厌倦了超人的智慧，厌倦了狂热的崇拜，也厌倦了超越万古的长梦。\n·号令触腕，降下攻击\n·消耗算力，增强触腕之力"
  },
  Item_9829_Name = {Text = "图鲁"},
  Item_9831_Desc = {
    Text = "主属性从界域精通、狂气回充等级、黑印掉落和银钥充能中随机获得1个。"
  },
  Item_9831_Name = {
    Text = "海归线Ⅳ"
  },
  Item_9831_StoryDesc = {
    Text = "归来吧，那终将重现的失落之城。"
  },
  Item_9833_Desc = {
    Text = "当灵知被无限放大，它将触及真相的一角。\n由银芯驱动的特殊仪器，能按照预设值永久提升唤醒体的能力。\n守密人达到30级后，可以选择任一唤醒体，使其获得以下增幅：\n·等级提升至40级\n·所有技能提升至2级\n·突破等阶提升至3阶"
