  Item_99102_Desc = {
    Text = "记录此钥令后，可在编队时选择钥令技能:「虚世之彩」。\n\n溃烂的幻觉在视网膜上产下畸变的霓虹——\n于是「颜色」的概念于虚世升华，仅剩谵妄的艳彩在现实的尸骸上流淌。"
  },
