  Item_9925_Name = {
    Text = "意识副本"
  },
  Item_9926_Desc = {
    Text = "封装着珍稀命轮的橙色礼匣，纯手工打造。\n用以表彰在学期课题中取得优异成绩的守密人。\n从以下SSR命轮或物品中选择1个：\n「阿库特之春」\n「陨日」\n「灵魂诞生」\n「流明之芯」×5"
