  Item_9932_Desc = {
    Text = "父将庇佑的符文铭刻于石板，予所有生命以仁爱的祷言。\n·减少算力消耗\n·给予护盾的同时，造成伤害"
  },
  Item_9932_Name = {
    Text = "萨尔瓦多"
  },
  Item_9934_Desc = {
    Text = "套装：\n入药之梦Ⅰ\n入药之梦Ⅱ\n入药之梦Ⅲ\n入药之梦Ⅳ\n入药之梦Ⅴ\n入药之梦Ⅵ"
  },
  Item_9934_Name = {
    Text = "入药之梦"
  },
  Item_9935_Desc = {
    Text = "是的，万物皆可淬制。你的本能、你的理智，甚至你的心……到头来你会发现，你和他们其实也没什么不同。\n用以升格深海界域唤醒体的材料。"
  },
  Item_9935_Name = {
    Text = "淬制本能"
  },
  Item_9938_Desc = {
    Text = "那是古老意志的失落灵识。 弥萨格通过神秘的仪式启发唤醒体的灵识，受到启发的唤醒体将永久增强精神能力。\n重复获得戈利亚时转换获得，用于激活戈利亚的启灵。"
  },
  Item_9938_Name = {
    Text = "残片·戈利亚"
  },
  Item_9938_StoryDesc = {
    Text = "重复获得戈利亚时转换获得，用于激活戈利亚的启灵。"
  },
  Item_9940_Desc = {
    Text = "历史会重演，宇宙可能除外。\n记载了神秘文字的残页，用以升格混沌界域唤醒体的材料。"
  },
  Item_9940_Name = {
    Text = "纯白残片"
  },
  Item_9941_Desc = {
    Text = "请遵守规章制度。\n诃勒特代理院长直批的许可证，持有它方能开启调查，或是进行更危险的幕间演习。"
  },
  Item_9941_Name = {
    Text = "研究许可（已废弃）"
  },
  Item_9942_Desc = {
    Text = "主属性从界域精通、狂气回充等级、黑印掉落和银钥充能中随机获得1个。"
  },
  Item_9942_Name = {
    Text = "二律背反Ⅳ"
  },
  Item_9942_StoryDesc = {
    Text = "必然的，偶然的。有限的，无限的。"
  },
  Item_9943_Desc = {
    Text = "提高持有者造成的反击层数，在承受伤害的同时能够积蓄临时力量。"
  },
  Item_9943_Name = {
    Text = "欲海浮沉"
  },
  Item_9943_StoryDesc = {
    Text = "噔，噔，噔。\n脚步声由远及近传来，头戴礼帽的绅士穿过废墟，站在奄奄一息的看守面前。\n绅士：你在这里做什么？\n\n（绅士患了严重的口吃，看守则喜欢兜圈子。为了您的阅读方便，笔者只摘录谈话重点。）\n\n看守：我在看守监狱。\n绅士望了望四周空无一人的原野，以及因沾染融蚀、正在缓慢塌陷的废墟残骸。\n绅士：可是这里没有监狱，也没有囚犯。你的王国早就不存在了。\n看守：我在看守监狱。\n绅士：为什么？\n看守抬起头，稚气未脱的脸上带着茫然与坚定。\n看守：我不知道……我想回家。\n看守：我替那位大人看守监狱。大人高兴了，我就能回家。\n至于那位大人是谁，为什么要替他看守，她自己也搞不清楚。\n绅士并不追问，仿佛这是再自然不过的事情。\n绅士：你的家乡，那是什么样的？\n看守：那里只有冬天和黑夜，还有一望无际的森林与大海。\n绅士：听上去不适合居住。\n看守：我讨厌白天。看到了吗，我是蜡做成的，如果接触到太阳，我就消失了。\n看守：所以我只能躲在这里，没办法自己回家。\n绅士若有所思地点点头。他忽然兴奋起来。\n绅士：真巧，你是由蜡制成的，而我刚好是个蜡像师。\n绅士：我们来做个约定吧——我可以让你行走在日光下，我还可以帮你找到回家的路。作为交换，你要成为我的助手。\n看守：助手，那是做什么的？\n绅士：你可以替我看守蜡像馆。它和这座监狱不一样，它是艺术，艺术是不会坍塌的。\n看守：艺术这么厉害？\n绅士开心地笑了起来。\n绅士：是的，就是这么厉害。\n\n故事的结尾，看守稀里糊涂地跟着绅士走了，正如她稀里糊涂地来到这所监狱一样。\n她一直是个随遇而安的家伙。"
  },
  Item_9944_Desc = {
